var VIDEO_LIBRARY = {"categories":[{"id":"houkoku-renraku","jp":"報告・連絡","vi":"Báo cáo & liên lạc","en":"Reports & Updates"},{"id":"denwa","jp":"電話対応","vi":"Xử lý điện thoại","en":"Phone Handling"},{"id":"kaigi-nittei","jp":"会議・日程","vi":"Họp & lịch trình","en":"Meetings & Scheduling"},{"id":"annai-oshirase","jp":"案内・お知らせ","vi":"Thông báo & hướng dẫn","en":"Announcements & Guidance"},{"id":"sekkyaku-outai","jp":"接客・応対","vi":"Tiếp khách","en":"Visitor & Client Reception"},{"id":"tehai-logistics","jp":"手配・物流","vi":"Sắp xếp & kho vận","en":"Arrangements & Logistics"},{"id":"keiri-keiyaku","jp":"見積・経理","vi":"Báo giá & tài chính","en":"Quotes & Finance"},{"id":"shinsei-kyoka","jp":"申請・許可","vi":"Đơn từ & xin phép","en":"Requests & Permissions"},{"id":"irai-koushou","jp":"依頼・交渉","vi":"Nhờ việc & thương lượng","en":"Requests & Negotiation"},{"id":"iken-kokan","jp":"意見交換","vi":"Trao đổi ý kiến","en":"Opinions & Discussion"},{"id":"aisatsu-reigi","jp":"挨拶・礼儀","vi":"Chào hỏi & lễ nghi","en":"Greetings & Courtesy"}],"videos":[{"slug":"shincho-hokoku","date":"2026-10-30","duration_sec":45,"category":"houkoku-renraku","situation":{"en":"Progress report: delivery delay & countermeasures","jp":"進捗報告 ― 納品の遅れと対策","vi":"Báo cáo tiến độ: giao hàng trễ & biện pháp xử lý"},"dialogue":[{"speaker":"boss_male","jp":"例のプロジェクトの進捗はどうなっていますか。","vi":"Tiến độ của dự án đó thế nào rồi?","en":"How is that project progressing?"},{"speaker":"staff_female","jp":"申し訳ございません。部品の納品が遅れておりまして、作業が予定より三日ほど遅れております。","vi":"Em xin lỗi. Việc giao linh kiện đang bị trễ, nên công việc chậm hơn dự định khoảng 3 ngày.","en":"I'm sorry. The parts delivery is delayed, so the work is about three days behind schedule."},{"speaker":"boss_male","jp":"原因は何ですか。","vi":"Nguyên nhân là gì?","en":"What is the cause?"},{"speaker":"staff_female","jp":"仕入先の工場で設備トラブルが発生したためです。ただ、対策として別の仕入先からも調達することにしました。","vi":"Do nhà máy của nhà cung cấp gặp sự cố thiết bị. Tuy nhiên, để đối phó, bên em đã quyết định thu mua thêm từ một nhà cung cấp khác.","en":"The supplier's factory had an equipment problem. As a countermeasure, we decided to also procure from another supplier."},{"speaker":"boss_male","jp":"最終納期には間に合いそうですか。","vi":"Có kịp hạn giao cuối cùng không?","en":"Will we make the final deadline?"},{"speaker":"staff_female","jp":"はい、金曜日までには完了する見通しです。改めて、本日中に修正したスケジュールをお送りします。","vi":"Dạ, dự kiến sẽ hoàn thành trước thứ Sáu. Em sẽ gửi lại lịch trình đã sửa trong hôm nay.","en":"Yes, we expect to finish by Friday. I will send you the revised schedule later today."}],"vocabulary":[{"jp":"進捗","reading":"しんちょく","vi":"tiến độ","en":"progress"},{"jp":"納品","reading":"のうひん","vi":"giao / bàn giao hàng","en":"delivery"},{"jp":"仕入先","reading":"しいれさき","vi":"nhà cung cấp","en":"supplier, vendor"},{"jp":"調達する","reading":"ちょうたつする","vi":"thu mua, cung ứng","en":"to procure"},{"jp":"対策","reading":"たいさく","vi":"biện pháp đối phó","en":"countermeasure"},{"jp":"見通し","reading":"みとおし","vi":"dự kiến, triển vọng","en":"outlook, prospect"},{"jp":"間に合う","reading":"まにあう","vi":"kịp (thời hạn)","en":"to be in time"}]},{"slug":"denwa-taiou","date":"2026-10-30","duration_sec":50,"category":"denwa","situation":{"en":"Phone handling: delayed order & apology","jp":"電話対応 ― 注文の遅れとお詫び","vi":"Xử lý điện thoại: đơn hàng trễ & xin lỗi"},"dialogue":[{"speaker":"customer_male","jp":"お世話になっております。先週注文した商品についてお伺いしたいのですが。","vi":"Xin chào, tôi muốn hỏi về sản phẩm đã đặt tuần trước.","en":"Hello, I'd like to ask about the product I ordered last week."},{"speaker":"staff_female","jp":"お世話になっております。ご注文の件ですね。お調べいたしますので、少々お待ちいただけますでしょうか。","vi":"Xin chào ạ. Về đơn hàng của quý khách đúng không ạ. Tôi sẽ kiểm tra nên quý khách vui lòng đợi một lát được không ạ.","en":"Hello. Regarding your order, I will check it, so could you please wait a moment?"},{"speaker":"customer_male","jp":"はい、お願いします。実は、納期が過ぎているのにまだ届いていないんです。","vi":"Vâng, nhờ cô. Thực ra đã quá hạn giao mà vẫn chưa nhận được.","en":"Yes, please. Actually, the delivery date has passed, but it still hasn't arrived."},{"speaker":"staff_female","jp":"大変申し訳ございません。確認いたしましたところ、配送の手配に遅れが生じておりました。","vi":"Tôi vô cùng xin lỗi. Sau khi kiểm tra, việc sắp xếp giao hàng đã bị chậm trễ.","en":"I sincerely apologize. Upon checking, there was a delay in arranging the delivery."},{"speaker":"customer_male","jp":"それでは、いつ届くのでしょうか。","vi":"Vậy thì khi nào mới nhận được?","en":"Then when will it arrive?"},{"speaker":"staff_female","jp":"明後日までには必ずお届けいたします。ご迷惑をおかけし、重ねてお詫び申し上げます。","vi":"Chậm nhất là ngày kia chúng tôi nhất định sẽ giao. Gây phiền toái cho quý khách, tôi xin lỗi thêm lần nữa.","en":"We will definitely deliver it by the day after tomorrow. We sincerely apologize again for the inconvenience."}],"vocabulary":[{"jp":"注文","reading":"ちゅうもん","vi":"đặt hàng","en":"order"},{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery deadline"},{"jp":"配送","reading":"はいそう","vi":"giao hàng, vận chuyển","en":"delivery"},{"jp":"手配","reading":"てはい","vi":"sắp xếp","en":"arrangement"},{"jp":"確認","reading":"かくにん","vi":"kiểm tra, xác nhận","en":"confirmation, check"},{"jp":"ご迷惑","reading":"ごめいわく","vi":"phiền toái","en":"inconvenience"},{"jp":"お詫び","reading":"おわび","vi":"lời xin lỗi","en":"apology"}]},{"slug":"kaigi-nittei-chosei","date":"2026-10-31","duration_sec":42,"category":"kaigi-nittei","situation":{"en":"Rescheduling a meeting: change & confirmation","jp":"会議の日程調整 ― 変更と確認","vi":"Điều chỉnh lịch họp: đổi lịch & xác nhận"},"dialogue":[{"speaker":"staff_female","jp":"課長、来週火曜日の会議なのですが、日程を変更していただけますでしょうか。","vi":"Trưởng phòng, về cuộc họp thứ Ba tuần sau, anh có thể đổi lịch giúp em được không ạ?","en":"Manager, could I ask to change the schedule for next Tuesday's meeting?"},{"speaker":"boss_male","jp":"どうしたんですか。何か都合が悪いのですか。","vi":"Có chuyện gì vậy? Có gì không tiện à?","en":"What's up? Is there a scheduling conflict?"},{"speaker":"staff_female","jp":"はい、取引先の訪問が急に入りまして、午後から外出することになりました。","vi":"Dạ, đột nhiên có chuyến thăm khách hàng, nên từ buổi chiều em phải ra ngoài.","en":"Yes, a client visit suddenly came in, so I will be out from the afternoon."},{"speaker":"boss_male","jp":"そうですか。では、水曜日の午後に変更しましょうか。","vi":"Ra vậy. Vậy thì đổi sang chiều thứ Tư nhé?","en":"I see. Then shall we move it to Wednesday afternoon?"},{"speaker":"staff_female","jp":"ありがとうございます。水曜日の午後でしたら、参加者全員が出席できます。変更のメールをすぐにお送りします。","vi":"Cảm ơn anh. Chiều thứ Tư thì mọi người tham gia đều dự được. Em sẽ gửi ngay email thông báo đổi lịch.","en":"Thank you. On Wednesday afternoon all participants can attend. I will send the change email right away."},{"speaker":"boss_male","jp":"よろしくお願いします。参加者への確認も忘れずにお願いします。","vi":"Nhờ anh nhé. Và đừng quên xác nhận với những người tham gia nhé.","en":"Please do. And don't forget to confirm with the participants."}],"vocabulary":[{"jp":"日程","reading":"にってい","vi":"lịch trình","en":"schedule"},{"jp":"変更","reading":"へんこう","vi":"thay đổi","en":"change"},{"jp":"取引先","reading":"とりひきさき","vi":"khách hàng, đối tác","en":"client, business partner"},{"jp":"訪問","reading":"ほうもん","vi":"chuyến thăm","en":"visit"},{"jp":"外出","reading":"がいしゅつ","vi":"ra ngoài","en":"going out"},{"jp":"参加者","reading":"さんかしゃ","vi":"người tham gia","en":"participant"},{"jp":"確認","reading":"かくにん","vi":"xác nhận","en":"confirmation, check"}]},{"slug":"shanai-annai","date":"2026-11-01","duration_sec":41,"category":"annai-oshirase","situation":{"en":"Internal notice: change in company cafeteria use","jp":"社内案内 ― 社員食堂の利用方法の変更","vi":"Thông báo nội bộ: thay đổi cách sử dụng nhà ăn nhân viên"},"dialogue":[{"speaker":"staff_female","jp":"来週から社員食堂の利用方法が変わるそうですよ。","vi":"Nghe nói từ tuần sau cách sử dụng nhà ăn nhân viên sẽ thay đổi đấy.","en":"I heard the way we use the company cafeteria will change from next week."},{"speaker":"colleague_male","jp":"そうなんですか。何が変わるんですか。","vi":"Thật à? Có gì thay đổi vậy?","en":"Really? What will change?"},{"speaker":"staff_female","jp":"まず、利用時間は十一時半から一時半までになります。混雑を避けるためだそうです。","vi":"Trước hết, giờ sử dụng sẽ là từ 11 giờ rưỡi đến 1 giờ rưỡi. Nghe nói là để tránh đông đúc.","en":"First, the hours will be from 11:30 to 1:30. Apparently that's to avoid congestion."},{"speaker":"colleague_male","jp":"予約は必要ですか。","vi":"Có cần đặt trước không?","en":"Is a reservation needed?"},{"speaker":"staff_female","jp":"はい、前日までに専用サイトで予約してください。当日は食券を買う必要がありません。","vi":"Có, hãy đặt trước trên trang web chuyên dụng chậm nhất là hôm trước. Hôm đó thì không cần mua vé ăn.","en":"Yes, please reserve on the dedicated website by the day before. On the day itself, you don't need to buy a meal ticket."},{"speaker":"colleague_male","jp":"分かりました。来週から気をつけます。ありがとうございます。","vi":"Tôi hiểu rồi. Từ tuần sau tôi sẽ chú ý. Cảm ơn nhé.","en":"I see. I'll be careful from next week. Thank you."}],"vocabulary":[{"jp":"社員食堂","reading":"しゃいんしょくどう","vi":"nhà ăn nhân viên","en":"company cafeteria"},{"jp":"利用方法","reading":"りようほうほう","vi":"cách sử dụng","en":"how to use"},{"jp":"混雑","reading":"こんざつ","vi":"đông đúc","en":"congestion"},{"jp":"避ける","reading":"さける","vi":"tránh","en":"to avoid"},{"jp":"予約","reading":"よやく","vi":"đặt trước","en":"reservation"},{"jp":"専用","reading":"せんよう","vi":"chuyên dụng","en":"dedicated"},{"jp":"食券","reading":"しょっけん","vi":"vé ăn","en":"meal ticket"}]},{"slug":"houmonkyaku-outai","date":"2026-11-02","duration_sec":43,"category":"sekkyaku-outai","situation":{"jp":"訪問客の応対 ― 受付と会議室への案内","vi":"Đón khách đến công ty: lễ tân & dẫn vào phòng họp","en":"Receiving a visitor: reception & guiding to the meeting room"},"dialogue":[{"speaker":"staff_female","jp":"いらっしゃいませ。本日はお越しいただき、ありがとうございます。","vi":"Xin chào quý khách. Cảm ơn quý khách đã đến hôm nay ạ.","en":"Welcome. Thank you for coming today."},{"speaker":"visitor_male","jp":"お世話になっております。本日午後2時の打ち合わせで参りました。担当の方とお約束しております。","vi":"Xin chào ạ. Tôi đến cho buổi họp lúc 2 giờ chiều hôm nay. Tôi đã hẹn với người phụ trách ạ.","en":"Hello. I have come for the 2 p.m. meeting today. I have an appointment with the person in charge."},{"speaker":"staff_female","jp":"かしこまりました。受付にて名刺をお預かりしてもよろしいでしょうか。","vi":"Dạ vâng. Tại quầy lễ tân, tôi có thể giữ danh thiếp của anh được không ạ?","en":"Certainly. May I take your business card at the reception desk?"},{"speaker":"visitor_male","jp":"はい、こちらが名刺でございます。よろしくお願いいたします。","vi":"Vâng, đây là danh thiếp của tôi. Rất mong được giúp đỡ.","en":"Yes, here is my business card. I look forward to working with you."},{"speaker":"staff_female","jp":"ありがとうございます。会議室までご案内いたします。こちらへどうぞ。","vi":"Cảm ơn anh. Tôi sẽ dẫn anh đến phòng họp. Mời anh đi lối này.","en":"Thank you. I will show you to the meeting room. This way, please."},{"speaker":"visitor_male","jp":"ありがとうございます。ご案内、よろしくお願いいたします。","vi":"Cảm ơn chị. Nhờ chị dẫn đường giúp tôi.","en":"Thank you. Please show me the way."}],"vocabulary":[{"jp":"訪問客","reading":"ほうもんきゃく","vi":"khách đến thăm","en":"visitor"},{"jp":"受付","reading":"うけつけ","vi":"quầy lễ tân","en":"reception"},{"jp":"名刺","reading":"めいし","vi":"danh thiếp","en":"business card"},{"jp":"担当者","reading":"たんとうしゃ","vi":"người phụ trách","en":"person in charge"},{"jp":"打ち合わせ","reading":"うちあわせ","vi":"buổi họp, trao đổi","en":"meeting, discussion"},{"jp":"会議室","reading":"かいぎしつ","vi":"phòng họp","en":"meeting room"},{"jp":"案内する","reading":"あんないする","vi":"dẫn đường, hướng dẫn","en":"to guide, to show"}]},{"slug":"sasou-kaishoku","date":"2026-11-08","duration_sec":66,"category":"sekkyaku-outai","situation":{"en":"Inviting a client to a business dinner","jp":"誘う ― お客様を会食にお誘いする","vi":"Mời khách hàng đi ăn tối"},"dialogue":[{"speaker":"sales_male","jp":"山本部長、あの、来週の金曜日の夜、ご予定はいかがでしょうか。","vi":"Anh Yamamoto, ơ, tối thứ Sáu tuần sau, anh có lịch gì không ạ?","en":"Mr. Yamamoto, um, next Friday evening — are you free?"},{"speaker":"client_male","jp":"ああ、金曜日ね。夜なら空いてるよ。","vi":"À, thứ Sáu à. Buổi tối thì anh rảnh.","en":"Ah, Friday. I'm free in the evening."},{"speaker":"sales_male","jp":"ありがとうございます。実は、会食のお誘いなんですが、ご一緒していただけますか。","vi":"Cảm ơn anh. Thực ra, em có lời mời ăn tối, không biết anh có thể đi cùng em không ạ?","en":"Thank you. Actually, I have a dinner invitation — would you join me?"},{"speaker":"client_male","jp":"おお、いいね。ぜひ、行こう。","vi":"Ồ, hay đấy. Ừ, đi chứ.","en":"Oh, nice. Yes, let's go."},{"speaker":"sales_male","jp":"はい、駅前の和食のお店を予約しようと思っています。","vi":"Dạ, em định đặt chỗ ở quán Nhật gần ga ạ.","en":"Yes, I was thinking of booking a Japanese restaurant in front of the station."},{"speaker":"client_male","jp":"うん、和食か。いいね。何時ごろ？","vi":"Ừ, đồ Nhật à. Hay đấy. Mấy giờ thì được?","en":"Hmm, Japanese food. Sounds good. Around what time?"},{"speaker":"sales_male","jp":"ええ、六時半ごろはいかがでしょうか。","vi":"Dạ, khoảng 6 giờ rưỡi thì anh thấy sao ạ?","en":"Well, would around 6:30 work for you?"},{"speaker":"client_male","jp":"六時半ね。分かった。じゃあ、その日はよろしく頼むよ。","vi":"6 giờ rưỡi nhé. Được rồi. Hôm đó nhờ em nhé.","en":"6:30, right. Understood. I'll leave that day to you, then."},{"speaker":"sales_male","jp":"はい、ありがとうございます。あの、人数はまた確認して、メールでお知らせします。","vi":"Dạ, cảm ơn anh. Ơ, số người thì em sẽ kiểm tra lại rồi báo qua email ạ.","en":"Yes, thank you. Um, I'll double-check the number of people and let you know by email."},{"speaker":"client_male","jp":"ああ、了解。楽しみにしてるよ。","vi":"À, rõ rồi. Anh mong chờ đấy.","en":"Ah, got it. I'm looking forward to it."}],"vocabulary":[{"jp":"誘う","reading":"さそう","vi":"mời, rủ","en":"to invite"},{"jp":"会食","reading":"かいしょく","vi":"bữa ăn cùng nhau (ăn tối công việc)","en":"business dinner, dining together"},{"jp":"お誘い","reading":"おさそい","vi":"lời mời","en":"invitation"},{"jp":"ご都合","reading":"ごつうごう","vi":"thời gian rảnh, sự tiện lợi (của đối phương)","en":"availability, convenience"},{"jp":"ご予定","reading":"ごよてい","vi":"lịch, kế hoạch (của đối phương)","en":"schedule, plans"},{"jp":"予約","reading":"よやく","vi":"đặt chỗ, đặt trước","en":"reservation, booking"},{"jp":"お店","reading":"おみせ","vi":"quán ăn, cửa hàng","en":"restaurant, shop"},{"jp":"ご一緒","reading":"ごいっしょ","vi":"cùng nhau","en":"together (with someone)"},{"jp":"確認する","reading":"かくにんする","vi":"xác nhận, kiểm tra","en":"to confirm, check"}]},{"slug":"kuremu-taiou","date":"2026-11-09","duration_sec":66,"category":"sekkyaku-outai","situation":{"en":"Handling a complaint: defective product & exchange","jp":"クレーム対応 ― 商品の不具合と交換のご案内","vi":"Xử lý khiếu nại: sản phẩm lỗi & đổi hàng"},"dialogue":[{"speaker":"client_male","jp":"あの、すみません。先週届いたプリンターなんですが、不具合があって…","vi":"Ơ, xin lỗi. Về chiếc máy in được giao tuần trước, nó bị lỗi ạ…","en":"Um, excuse me. About the printer delivered last week — there's a defect…"},{"speaker":"staff_female","jp":"まあ、申し訳ございません。どのような不具合でしょうか。","vi":"Ôi, em xin lỗi. Lỗi như thế nào ạ?","en":"Oh, I'm terribly sorry. What kind of defect is it?"},{"speaker":"client_male","jp":"電源を入れても、画面が真っ暗のままなんです。","vi":"Dù đã bật nguồn mà màn hình vẫn tối đen.","en":"Even when I turn it on, the screen stays completely dark."},{"speaker":"staff_female","jp":"そうですか…。大変ご迷惑をおかけして、申し訳ございません。","vi":"Ra vậy ạ… Gây phiền toái lớn cho anh, em xin lỗi ạ.","en":"I see… We sincerely apologize for the great inconvenience."},{"speaker":"client_male","jp":"仕事で使うものなので、早く対応していただけると助かります。","vi":"Vì là đồ dùng cho công việc nên anh mong được xử lý sớm.","en":"It's something I use for work, so I'd appreciate a quick response."},{"speaker":"staff_female","jp":"はい、もちろんです。すぐに新しい商品と交換させていただきます。","vi":"Dạ, tất nhiên ạ. Em sẽ đổi ngay cho anh một sản phẩm mới.","en":"Yes, of course. We'll exchange it for a new one right away."},{"speaker":"client_male","jp":"交換ですか。いつ頃届きますか。","vi":"Đổi mới à. Khoảng khi nào thì nhận được?","en":"An exchange? Around when would it arrive?"},{"speaker":"staff_female","jp":"明後日までにはお届けできます。送料はこちらで負担いたします。","vi":"Chậm nhất ngày kia sẽ giao được ạ. Phí vận chuyển bên em chịu.","en":"We can deliver it by the day after tomorrow. We'll cover the shipping cost."},{"speaker":"client_male","jp":"分かりました。原因も、後で教えていただけますか。","vi":"Tôi hiểu rồi. Nguyên nhân thì sau này anh có thể cho tôi biết được không?","en":"Understood. Could you also let me know the cause later?"},{"speaker":"staff_female","jp":"はい、調査が終わり次第、ご連絡いたします。今後ともよろしくお願いいたします。","vi":"Dạ, ngay khi điều tra xong em sẽ liên lạc ạ. Mong anh tiếp tục giúp đỡ.","en":"Yes, we'll contact you as soon as the investigation is complete. Thank you for your continued support."}],"vocabulary":[{"jp":"クレーム","reading":"くれーむ","vi":"khiếu nại","en":"complaint"},{"jp":"不具合","reading":"ふぐあい","vi":"lỗi, hỏng hóc","en":"defect, malfunction"},{"jp":"交換","reading":"こうかん","vi":"đổi hàng","en":"exchange, replacement"},{"jp":"返品","reading":"へんぴん","vi":"trả hàng","en":"return (of goods)"},{"jp":"お詫び","reading":"おわび","vi":"lời xin lỗi","en":"apology"},{"jp":"ご迷惑","reading":"ごめいわく","vi":"phiền toái lớn","en":"inconvenience"},{"jp":"確認する","reading":"かくにんする","vi":"kiểm tra, xác nhận","en":"to confirm, to check"},{"jp":"対応","reading":"たいおう","vi":"xử lý, đối ứng","en":"handling, response"},{"jp":"原因","reading":"げんいん","vi":"nguyên nhân","en":"cause"}]},{"slug":"shuccho-tehai","date":"2026-11-03","duration_sec":45,"category":"tehai-logistics","situation":{"jp":"出張の手配 ― 承認と宿泊・交通費の確認","vi":"Sắp xếp công tác: xin phê duyệt & xác nhận khách sạn, chi phí đi lại","en":"Arranging a business trip: approval, hotel & travel expenses"},"dialogue":[{"speaker":"staff_female","jp":"課長、来週の大阪出張の件なのですが、手配を進めさせていただいてもよろしいでしょうか。","vi":"Trưởng phòng, về chuyến công tác Osaka tuần sau, anh cho phép em tiến hành sắp xếp được không ạ?","en":"Manager, regarding next week's Osaka business trip, may I go ahead with the arrangements?"},{"speaker":"boss_male","jp":"ああ、経理部の承認はもう取れたのか。","vi":"À, đã xin được phê duyệt của phòng kế toán chưa?","en":"I see. Have you already got approval from the accounting department?"},{"speaker":"staff_female","jp":"はい、昨日承認をいただきました。宿泊は駅前のホテルを予約しようと思います。","vi":"Dạ, hôm qua em đã nhận được phê duyệt. Về chỗ ở, em định đặt khách sạn trước ga.","en":"Yes, I received approval yesterday. For lodging, I plan to book the hotel in front of the station."},{"speaker":"boss_male","jp":"そうか。交通費は新幹線を利用するんだな。","vi":"Ra vậy. Chi phí đi lại thì đi tàu shinkansen đúng không?","en":"I see. For travel expenses, you'll use the shinkansen, right?"},{"speaker":"staff_female","jp":"はい、往復の新幹線とホテル代をまとめて精算する予定です。","vi":"Dạ, em dự định quyết toán gộp cả vé shinkansen khứ hồi và tiền khách sạn.","en":"Yes, I plan to settle the round-trip shinkansen and hotel costs together."},{"speaker":"boss_male","jp":"分かった。領収書は忘れずに保管しておいてくれ。","vi":"Được rồi. Nhớ giữ lại hoá đơn, đừng quên nhé.","en":"Understood. Don't forget to keep the receipts."}],"vocabulary":[{"jp":"出張","reading":"しゅっちょう","vi":"công tác","en":"business trip"},{"jp":"手配","reading":"てはい","vi":"sắp xếp, chuẩn bị","en":"arrangement"},{"jp":"承認","reading":"しょうにん","vi":"phê duyệt","en":"approval"},{"jp":"経理部","reading":"けいりぶ","vi":"phòng kế toán","en":"accounting dept."},{"jp":"宿泊","reading":"しゅくはく","vi":"lưu trú, ở lại","en":"lodging, stay"},{"jp":"交通費","reading":"こうつうひ","vi":"chi phí đi lại","en":"travel expenses"},{"jp":"精算","reading":"せいさん","vi":"quyết toán, thanh toán","en":"settlement"}]},{"slug":"zaiko-shukka","date":"2026-11-03","duration_sec":44,"category":"tehai-logistics","situation":{"jp":"在庫と出荷 ― 数量の確認と分割出荷","vi":"Tồn kho & xuất hàng: kiểm tra số lượng và chia đợt giao","en":"Inventory & shipping: checking quantities and split shipments"},"dialogue":[{"speaker":"colleague_male","jp":"今月の注文分、在庫は足りているか。","vi":"Đơn hàng tháng này, tồn kho có đủ không?","en":"For this month's orders, is the stock sufficient?"},{"speaker":"staff_female","jp":"はい、現在倉庫に120個ございます。ただ、来週の分まで含めると少し不足します。","vi":"Dạ, hiện trong kho có 120 cái. Tuy nhiên, tính cả phần tuần sau thì hơi thiếu.","en":"Yes, we currently have 120 units in the warehouse. However, including next week's share, we are a bit short."},{"speaker":"colleague_male","jp":"では、まず80個を今週出荷して、残りはどうする。","vi":"Vậy thì, trước hết xuất 80 cái trong tuần này, còn lại thì sao?","en":"Then, let's first ship 80 units this week — what about the rest?"},{"speaker":"staff_female","jp":"残りの40個は来週の月曜日に入荷する予定ですので、その翌日に出荷できます。","vi":"40 cái còn lại dự kiến nhập kho vào thứ Hai tuần sau, nên hôm sau đó có thể xuất hàng.","en":"The remaining 40 units are scheduled to arrive next Monday, so we can ship them the next day."},{"speaker":"colleague_male","jp":"分かった。納期に遅れないよう、取引先には先に連絡しておいてくれ。","vi":"Được rồi. Để không trễ hạn giao, hãy liên lạc trước với đối tác nhé.","en":"Understood. So we don't miss the delivery deadline, please contact the client in advance."},{"speaker":"staff_female","jp":"かしこまりました。本日中にメールでご連絡いたします。","vi":"Dạ vâng. Trong hôm nay tôi sẽ liên lạc qua email.","en":"Certainly. I will contact them by email today."}],"vocabulary":[{"jp":"在庫","reading":"ざいこ","vi":"tồn kho","en":"inventory, stock"},{"jp":"倉庫","reading":"そうこ","vi":"nhà kho","en":"warehouse"},{"jp":"不足","reading":"ふそく","vi":"thiếu, không đủ","en":"shortage"},{"jp":"出荷","reading":"しゅっか","vi":"xuất hàng","en":"shipment"},{"jp":"入荷","reading":"にゅうか","vi":"hàng nhập kho","en":"stock arrival"},{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery deadline"},{"jp":"連絡","reading":"れんらく","vi":"liên lạc","en":"contact"}]},{"slug":"mitsumori-sho","date":"2026-11-04","duration_sec":39,"category":"keiri-keiyaku","situation":{"jp":"見積書 ― 値引きの交渉と正式な見積もりの依頼","vi":"Báo giá: thương lượng giảm giá & yêu cầu báo giá chính thức","en":"Quotation: negotiating a discount & requesting a formal quote"},"dialogue":[{"speaker":"sales_male","jp":"お世話になっております。先日ご依頼の件、見積書をお持ちいたしました。","vi":"Xin chào ạ. Về việc anh/chị nhờ hôm trước, tôi đã mang bản báo giá đến ạ.","en":"Hello. Regarding the matter you requested the other day, I have brought the quotation."},{"speaker":"client_male","jp":"ありがとう。さっそく内容を確認させてもらおう。単価は前回と同じかね。","vi":"Cảm ơn. Để tôi xem ngay nội dung. Đơn giá có giống lần trước không?","en":"Thank you. Let me check the contents right away. Is the unit price the same as last time?"},{"speaker":"sales_male","jp":"はい、単価は据え置きでございます。ただ、数量が増えましたので、合計が少し上がっております。","vi":"Dạ, đơn giá giữ nguyên ạ. Tuy nhiên, vì số lượng tăng nên tổng tiền hơi tăng ạ.","en":"Yes, the unit price is unchanged. However, since the quantity increased, the total is slightly higher."},{"speaker":"sales_male","jp":"その代わり、5％の値引きでしたら、対応可能でございます。","vi":"Đổi lại, nếu giảm giá 5% thì chúng tôi có thể đáp ứng ạ.","en":"In exchange, we can offer a 5% discount."},{"speaker":"client_male","jp":"ありがとう。税込みの金額で、正式な見積もりを送ってくれ。","vi":"Cảm ơn. Hãy gửi cho tôi bản báo giá chính thức với số tiền đã gồm thuế nhé.","en":"Thank you. Please send me the formal quotation with the tax-included amount."}],"vocabulary":[{"jp":"見積書","reading":"みつもりしょ","vi":"bản báo giá","en":"quotation"},{"jp":"単価","reading":"たんか","vi":"đơn giá","en":"unit price"},{"jp":"数量","reading":"すうりょう","vi":"số lượng","en":"quantity"},{"jp":"値引き","reading":"ねびき","vi":"giảm giá","en":"discount"},{"jp":"税込み","reading":"ぜいこみ","vi":"đã gồm thuế","en":"tax-included"},{"jp":"見積もり","reading":"みつもり","vi":"bản báo giá","en":"quotation, estimate"}]},{"slug":"zangyo-kyuka-shinsei","date":"2026-11-04","duration_sec":38,"category":"shinsei-kyoka","situation":{"jp":"残業・休暇の申請 ― 申請書の提出と代休の相談","vi":"Xin làm thêm & nghỉ phép: nộp đơn và hỏi về nghỉ bù","en":"Overtime & leave requests: submitting the form and asking about compensatory leave"},"dialogue":[{"speaker":"staff_female","jp":"課長、来週の残業の件で、ご相談させていただいてもよろしいでしょうか。","vi":"Trưởng phòng, về việc làm thêm tuần sau, em có thể trao đổi với chị được không ạ?","en":"Manager, may I consult with you about next week's overtime?"},{"speaker":"staff_female","jp":"はい、ありがとうございます。火曜日と木曜日に、2時間ずつ残業させていただけますでしょうか。","vi":"Dạ, cảm ơn chị. Thứ Ba và thứ Năm, em có thể làm thêm mỗi ngày 2 tiếng được không ạ?","en":"Yes, thank you. On Tuesday and Thursday, may I work two hours of overtime each day?"},{"speaker":"manager_female","jp":"いいわよ。ただ、申請書は今日中に提出しておいてね。","vi":"Được đấy. Nhưng nhớ nộp đơn trong hôm nay nhé.","en":"That's fine. Just submit the application form by today."},{"speaker":"staff_female","jp":"かしこまりました。実は、来月の有給休暇についても、お伺いしたいのですが。3日間、代休と組み合わせてもよろしいでしょうか。","vi":"Dạ vâng. Thực ra, em cũng muốn hỏi về nghỉ phép có lương tháng sau ạ. Nghỉ 3 ngày, kết hợp với nghỉ bù có được không ạ?","en":"Certainly. Actually, I'd also like to ask about next month's paid leave. May I take three days, combined with compensatory leave?"},{"speaker":"manager_female","jp":"いい考えね。","vi":"Ý hay đấy.","en":"That's a good idea."}],"vocabulary":[{"jp":"残業","reading":"ざんぎょう","vi":"làm thêm giờ","en":"overtime"},{"jp":"相談","reading":"そうだん","vi":"trao đổi, hỏi ý","en":"consultation"},{"jp":"繁忙期","reading":"はんぼうき","vi":"mùa cao điểm","en":"busy season"},{"jp":"申請書","reading":"しんせいしょ","vi":"đơn xin","en":"application form"},{"jp":"提出","reading":"ていしゅつ","vi":"nộp","en":"submission"},{"jp":"有給休暇","reading":"ゆうきゅうきゅうか","vi":"nghỉ phép có lương","en":"paid leave"},{"jp":"代休","reading":"だいきゅう","vi":"nghỉ bù","en":"compensatory leave"}]},{"slug":"irai-wo-kotowaru","date":"2026-11-05","duration_sec":68,"category":"irai-koushou","situation":{"jp":"依頼を断る ― 上司の頼みを丁寧に断る","vi":"Từ chối khéo — từ chối nhờ vả của cấp trên","en":"Politely declining a request — declining a superior's request"},"dialogue":[{"speaker":"chief_female","jp":"山田君、悪いんだけど、明日の会議の資料作成を手伝ってもらえないかな。","vi":"Yamada này, cậu có thể giúp tôi làm tài liệu cho cuộc họp ngày mai không?","en":"Yamada, could you help me prepare the documents for tomorrow's meeting?"},{"speaker":"employee_male","jp":"せっかくお声がけいただいたのですが、あいにく今は手が離せない状況でして。","vi":"Cảm ơn chị đã nhờ, nhưng tiếc là hiện giờ tôi đang bận không rời được.","en":"Thank you for asking, but unfortunately I'm tied up right now and can't get away."},{"speaker":"chief_female","jp":"そうか。明日の午前中までには仕上げたいんだけど、時間は取れそうかな。","vi":"Vậy à. Tôi muốn hoàn thành trước trưa mai, cậu có sắp xếp được thời gian không?","en":"I see. I'd like it finished by tomorrow morning — do you think you could find the time?"},{"speaker":"employee_male","jp":"申し訳ございません。今日が締め切りの資料がございまして、先約の打ち合わせも入っております。","vi":"Vô cùng xin lỗi. Tôi có tài liệu hạn chót hôm nay, và còn có cuộc hẹn đã hẹn trước nữa.","en":"I'm terribly sorry. I have documents due today, and I also have a prior commitment meeting."},{"speaker":"chief_female","jp":"なるほど、それは仕方ないね。じゃあ、代わりに誰か手伝える人はいないかな。","vi":"Ra vậy, thế thì đành chịu. Vậy có ai khác có thể giúp thay không?","en":"I see, that can't be helped. Is there anyone else who could help instead?"},{"speaker":"employee_male","jp":"はい、田中さんでしたら、午後に時間が空いていると伺っております。","vi":"Vâng, nghe nói anh Tanaka thì buổi chiều còn trống ạ.","en":"Yes, I understand Mr. Tanaka has some free time this afternoon."},{"speaker":"chief_female","jp":"そうか、田中さんに頼んでみようかな。山田君の資料は大丈夫かい。","vi":"Vậy để tôi thử nhờ Tanaka nhé. Còn tài liệu của cậu thì ổn chứ?","en":"Then I'll try asking Tanaka. And your own documents — are they all right?"},{"speaker":"employee_male","jp":"はい、おかげさまで、夕方までには仕上がる見込みでございます。","vi":"Vâng, nhờ ơn chị, dự kiến đến chiều tối sẽ hoàn thành ạ.","en":"Yes, thanks to you, I expect to finish by this evening."},{"speaker":"chief_female","jp":"よかった。では、田中さんへの依頼は私から伝えておくよ。","vi":"Tốt rồi. Vậy tôi sẽ tự nhắn lời nhờ cho Tanaka nhé.","en":"Good. Then I'll pass the request on to Tanaka myself."},{"speaker":"employee_male","jp":"ありがとうございます。次回はぜひお手伝いさせてください。","vi":"Cảm ơn chị. Lần tới nhất định hãy để tôi giúp ạ.","en":"Thank you. Next time, please do let me help."}],"vocabulary":[{"jp":"依頼","reading":"いらい","vi":"nhờ việc","en":"a request"},{"jp":"資料作成","reading":"しりょうさくせい","vi":"soạn tài liệu","en":"preparing documents"},{"jp":"締め切り","reading":"しめきり","vi":"hạn chót","en":"deadline"},{"jp":"先約","reading":"せんやく","vi":"hẹn trước","en":"prior commitment"},{"jp":"手が離せない","reading":"てがはなせない","vi":"bận không rời được","en":"tied up, can't get away"},{"jp":"あいにく","reading":"あいにく","vi":"tiếc là","en":"unfortunately"},{"jp":"申し訳ございません","reading":"もうしわけございません","vi":"vô cùng xin lỗi","en":"I'm terribly sorry"},{"jp":"代わり","reading":"かわり","vi":"thay thế","en":"alternative"},{"jp":"お手伝い","reading":"おてつだい","vi":"giúp đỡ","en":"help"}]},{"slug":"denwa-toritsugu","date":"2026-11-04","duration_sec":68,"category":"denwa","situation":{"jp":"電話の取り次ぎ ― 担当者が外出中のとき","vi":"Chuyển máy — khi người cần gặp đi vắng","en":"Transferring a call — when the person is out"},"dialogue":[{"speaker":"employee_male","jp":"はい、ABC商事でございます。","vi":"Vâng, công ty ABC Shoji xin nghe.","en":"Hello, this is ABC Shoji."},{"speaker":"caller_female","jp":"お世話になっております。鈴木と申します。田中課長へのお取り次ぎをお願いいたします。","vi":"Xin chào, tôi là Suzuki. Tôi muốn gặp trưởng phòng Tanaka ạ.","en":"Hello, this is Suzuki. May I speak with Manager Tanaka, please?"},{"speaker":"employee_male","jp":"あいにく田中は外出中でございます。","vi":"Tiếc là anh Tanaka hiện đang ra ngoài ạ.","en":"Unfortunately, Mr. Tanaka is currently out of the office."},{"speaker":"caller_female","jp":"そうですか。何時ごろお戻りになりますか。","vi":"Vậy sao. Khoảng mấy giờ anh ấy quay lại ạ?","en":"I see. Around what time will he be back?"},{"speaker":"employee_male","jp":"午後3時ごろ戻る予定でございます。","vi":"Anh ấy dự kiến quay lại vào khoảng 3 giờ chiều ạ.","en":"He is expected back around 3 p.m."},{"speaker":"caller_female","jp":"では、伝言をお願いできますか。","vi":"Vậy tôi có thể nhờ anh chuyển lời nhắn được không ạ?","en":"In that case, may I leave a message?"},{"speaker":"employee_male","jp":"承知いたしました。ご連絡先を伺ってもよろしいでしょうか。","vi":"Dạ được ạ. Chị cho tôi xin số liên lạc được không ạ?","en":"Certainly. May I have your contact number, please?"},{"speaker":"caller_female","jp":"はい、090の1234の5678でございます。","vi":"Vâng, số của tôi là 090-1234-5678 ạ.","en":"Yes, my number is 090-1234-5678."},{"speaker":"employee_male","jp":"090の1234の5678ですね。","vi":"090-1234-5678, đúng không ạ?","en":"090-1234-5678, correct?"},{"speaker":"caller_female","jp":"恐れ入ります。戻られましたら、折り返しいただけますでしょうか。","vi":"Xin cảm ơn. Khi anh ấy quay lại, anh có thể gọi lại cho tôi được không ạ?","en":"Thank you. Could you please call me back when he returns?"}],"vocabulary":[{"jp":"取り次ぐ","reading":"とりつぐ","vi":"chuyển máy","en":"to transfer (a call)"},{"jp":"外出中","reading":"がいしゅつちゅう","vi":"đang ra ngoài","en":"out of the office"},{"jp":"伝言","reading":"でんごん","vi":"lời nhắn","en":"message"},{"jp":"連絡先","reading":"れんらくさき","vi":"số liên lạc","en":"contact number"},{"jp":"折り返し","reading":"おりかえし","vi":"gọi lại","en":"callback"},{"jp":"承知いたしました","reading":"しょうちいたしました","vi":"tôi đã rõ ạ","en":"certainly / understood"},{"jp":"恐れ入ります","reading":"おそれいります","vi":"xin cảm ơn (lịch sự)","en":"thank you (polite)"},{"jp":"戻る","reading":"もどる","vi":"quay lại","en":"to return"},{"jp":"お世話になっております","reading":"おせわになっております","vi":"cảm ơn đã giúp đỡ","en":"thank you for your continued support"}]},{"slug":"jiko-shokai","date":"2026-11-04","duration_sec":66,"category":"aisatsu-reigi","situation":{"jp":"自己紹介・人紹介 ― 新入社員が上司に自己紹介する","vi":"Tự giới thiệu & giới thiệu người khác: nhân viên mới tự giới thiệu với cấp trên","en":"Self-introduction & introducing people: a new employee introduces herself to her manager"},"dialogue":[{"speaker":"staff_female","jp":"はじめまして。今度、営業部に配属されました佐藤と申します。","vi":"Chào anh/chị lần đầu. Tôi là Sato, mới được phân công về phòng Kinh doanh ạ.","en":"Nice to meet you. I'm Sato, newly assigned to the Sales Department."},{"speaker":"boss_male","jp":"ああ、佐藤さんですね。ようこそ、よろしくお願いします。","vi":"À, cô Sato phải không. Chào mừng cô, rất mong được hợp tác.","en":"Ah, Ms. Sato. Welcome — I look forward to working with you."},{"speaker":"staff_female","jp":"本日からお世話になります。至らない点もありますが、よろしくお願いいたします。","vi":"Từ hôm nay mong được anh giúp đỡ. Còn nhiều điều chưa tốt, mong anh thông cảm và giúp đỡ.","en":"From today, I'll be in your care. I still have much to learn, so I ask for your guidance."},{"speaker":"boss_male","jp":"こちらこそ。まずは先輩の仕事を見て、流れをつかんでください。","vi":"Tôi cũng vậy. Trước hết hãy xem cách làm việc của các anh chị đi trước và nắm được quy trình nhé.","en":"Likewise. First, watch how your seniors work and get a feel for the workflow."},{"speaker":"staff_female","jp":"はい、ありがとうございます。先週の研修で、名刺交換も学びました。","vi":"Dạ, cảm ơn anh. Trong đợt đào tạo tuần trước, em cũng đã học cách trao danh thiếp rồi ạ.","en":"Yes, thank you. In last week's training, I also learned how to exchange business cards."},{"speaker":"boss_male","jp":"それはいいね。来週から、取引先への挨拶回りに同行してもらうよ。","vi":"Tốt đấy. Từ tuần sau, em hãy đi cùng tôi trong các chuyến chào hỏi khách hàng nhé.","en":"That's good. From next week, you'll accompany me on introductory visits to clients."},{"speaker":"staff_female","jp":"はい、ぜひ同行させてください。ご指導のほど、よろしくお願いいたします。","vi":"Dạ, em rất mong được đi cùng ạ. Mong anh chỉ bảo giúp em.","en":"Yes, I'd love to accompany you. I ask for your guidance."},{"speaker":"boss_male","jp":"分かった。分からないことがあれば、遠慮なく聞いてください。","vi":"Được rồi. Có gì không hiểu thì cứ hỏi thẳng, đừng ngại nhé.","en":"Understood. If there's anything you don't understand, don't hesitate to ask."},{"speaker":"staff_female","jp":"ありがとうございます。一生懸命頑張りますので、よろしくお願いいたします。","vi":"Cảm ơn anh. Em sẽ cố gắng hết sức, mong anh giúp đỡ ạ.","en":"Thank you. I'll work with all my effort, so I look forward to your support."},{"speaker":"boss_male","jp":"期待しているよ。では、さっそく席へ案内しよう。","vi":"Anh rất kỳ vọng đấy. Vậy thì, để anh dẫn em đến chỗ ngồi ngay nhé.","en":"I'm counting on you. Now, let me show you to your desk right away."}],"vocabulary":[{"jp":"配属","reading":"はいぞく","vi":"phân công về phòng","en":"assignment to a section"},{"jp":"お世話になる","reading":"おせわになる","vi":"được giúp đỡ","en":"to be in one's care"},{"jp":"研修","reading":"けんしゅう","vi":"đào tạo tập huấn","en":"training"},{"jp":"名刺交換","reading":"めいしこうかん","vi":"trao danh thiếp","en":"business card exchange"},{"jp":"取引先","reading":"とりひきさき","vi":"khách hàng đối tác","en":"client / business partner"},{"jp":"挨拶回り","reading":"あいさつまわり","vi":"chuyến chào hỏi","en":"introductory visits"},{"jp":"同行","reading":"どうこう","vi":"đi cùng","en":"accompanying"},{"jp":"指導","reading":"しどう","vi":"chỉ bảo hướng dẫn","en":"guidance"},{"jp":"一生懸命","reading":"いっしょうけんめい","vi":"hết sức mình","en":"with all one's effort"}]},{"slug":"saisoku-suru","date":"2026-11-05","duration_sec":68,"category":"irai-koushou","situation":{"jp":"催促する ― 返信の遅れた資料の催促","vi":"Nhắc khéo: nhắc đối tác chậm gửi tài liệu","en":"Polite reminder: following up on delayed documents"},"dialogue":[{"speaker":"sales_male","jp":"お世話になっております。催促するようで恐縮ですが、先日の件でご連絡いたしました。","vi":"Xin chào ạ. Nhắc thế này thì thật ngại, nhưng tôi liên lạc về việc hôm trước ạ.","en":"Hello. I apologize for pressing you, but I'm calling about the other day's matter."},{"speaker":"client_female","jp":"ああ、資料の件ですね。申し訳ございません、まだお送りできておりません。","vi":"À, về tài liệu đúng không ạ. Xin lỗi, chúng tôi vẫn chưa gửi được.","en":"Ah, the documents, right? I'm sorry, we haven't sent them yet."},{"speaker":"sales_male","jp":"進捗はいかがでしょうか。","vi":"Tiến độ thế nào rồi ạ?","en":"How is the progress going?"},{"speaker":"client_female","jp":"はい、確認中でございまして、明日中にお送りできる見込みです。","vi":"Dạ, đang trong quá trình kiểm tra, dự kiến sẽ gửi được trong ngày mai ạ.","en":"Yes, it is currently being checked, and we expect to send it by tomorrow."},{"speaker":"sales_male","jp":"ありがとうございます。実は、納期が来週の日曜日に迫っておりまして。","vi":"Cảm ơn chị. Thực ra, hạn giao đang đến gần vào Chủ nhật tuần sau ạ.","en":"Thank you. Actually, the delivery deadline is approaching next Sunday."},{"speaker":"client_female","jp":"承知しております。お手数をおかけして、申し訳ございません。","vi":"Tôi đã rõ ạ. Gây phiền toái cho anh, tôi xin lỗi.","en":"Understood. Sorry for the trouble."},{"speaker":"sales_male","jp":"はい、恐れ入ります。回答をいただけましたら、すぐにお知らせください。","vi":"Dạ, xin cảm ơn. Khi có câu trả lời, xin hãy báo ngay cho tôi.","en":"Yes, thank you. Once you have an answer, please let me know right away."},{"speaker":"client_female","jp":"かしこまりました。明日、必ずご連絡いたします。","vi":"Dạ vâng. Ngày mai nhất định tôi sẽ liên lạc.","en":"Certainly. I will definitely contact you tomorrow."},{"speaker":"sales_male","jp":"ご迷惑をおかけしますが、どうぞよろしくお願いいたします。","vi":"Gây phiền cho chị, nhưng mong chị giúp đỡ.","en":"Sorry for the inconvenience, and thank you for your cooperation."},{"speaker":"client_female","jp":"こちらこそ、よろしくお願いいたします。明日、メールでお送りいたします。","vi":"Tôi cũng vậy, mong anh giúp đỡ. Ngày mai tôi sẽ gửi qua email.","en":"Likewise, I look forward to working with you. I'll send it by email tomorrow."}],"vocabulary":[{"jp":"催促する","reading":"さいそくする","vi":"nhắc nhở thúc giục","en":"to press remind"},{"jp":"恐縮","reading":"きょうしゅく","vi":"ngại áy náy","en":"feeling obliged"},{"jp":"進捗","reading":"しんちょく","vi":"tiến độ","en":"progress"},{"jp":"確認","reading":"かくにん","vi":"kiểm tra xác nhận","en":"confirmation"},{"jp":"見込み","reading":"みこみ","vi":"dự kiến","en":"prospect expectation"},{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery deadline"},{"jp":"お手数","reading":"おてすう","vi":"phiền toái","en":"trouble bother"},{"jp":"回答","reading":"かいとう","vi":"câu trả lời","en":"reply answer"},{"jp":"ご迷惑","reading":"ごめいわく","vi":"phiền toái","en":"inconvenience"}]},{"slug":"chumon-yoyaku","date":"2026-11-05","duration_sec":68,"category":"tehai-logistics","situation":{"jp":"注文・予約する ― コピー用紙の注文と条件の確認","vi":"Đặt hàng & đặt trước — đặt giấy copy và xác nhận điều kiện","en":"Placing an order — ordering copy paper and confirming terms"},"dialogue":[{"speaker":"buyer_male","jp":"お世話になっております。コピー用紙の注文をお願いしたいんですが。","vi":"Xin chào ạ. Tôi muốn đặt mua giấy copy ạ.","en":"Hello. I'd like to place an order for copy paper."},{"speaker":"supplier_male","jp":"はい、承知いたしました。A4とB4でよろしいでしょうか。","vi":"Dạ, tôi đã rõ ạ. A4 và B4 đúng không ạ?","en":"Certainly. A4 and B4, is that right?"},{"speaker":"buyer_male","jp":"はい、A4を5箱と、B4を3箱お願いします。","vi":"Dạ, cho tôi 5 hộp A4 và 3 hộp B4 ạ.","en":"Yes, 5 boxes of A4 and 3 boxes of B4, please."},{"speaker":"supplier_male","jp":"かしこまりました。トナーもご一緒にいかがですか。","vi":"Dạ vâng. Anh có muốn lấy thêm mực in cùng luôn không ạ?","en":"Certainly. Would you like some toner as well?"},{"speaker":"buyer_male","jp":"はい、トナーも3本お願いします。単価は前回と同じですか。","vi":"Dạ, cho tôi thêm 3 hộp mực nữa. Đơn giá có như lần trước không ạ?","en":"Yes, 3 toner cartridges too. Is the unit price the same as last time?"},{"speaker":"supplier_male","jp":"はい、A4は1箱2,000円、トナーは1本4,000円です。","vi":"Dạ, A4 là 2.000 yên một hộp, mực in là 4.000 yên một hộp ạ.","en":"Yes, A4 is 2,000 yen a box, and toner is 4,000 yen a cartridge."},{"speaker":"buyer_male","jp":"そうですか。合計で税込みいくらになりますか。","vi":"Vậy à. Tổng cộng cả thuế là bao nhiêu ạ?","en":"I see. How much is the total, tax included?"},{"speaker":"supplier_male","jp":"A4が1万円、B4が4,500円、トナーが1万2,000円、合計26,500円です。","vi":"A4 là 10.000 yên, B4 là 4.500 yên, mực in là 12.000 yên, tổng cộng 26.500 yên ạ.","en":"A4 is 10,000 yen, B4 is 4,500 yen, toner is 12,000 yen — 26,500 yen in total."},{"speaker":"buyer_male","jp":"わかりました。納品は明日の午前中でお願いします。お支払いは今月末でよろしいですか。","vi":"Tôi đã rõ. Xin giao hàng vào sáng mai giúp tôi. Thanh toán vào cuối tháng này được không ạ?","en":"Understood. Please deliver tomorrow morning. May I pay at the end of this month?"},{"speaker":"supplier_male","jp":"はい、在庫がございますので、明日の午前中にお届けいたします。","vi":"Dạ, chúng tôi còn hàng, nên sẽ giao vào sáng mai ạ.","en":"Yes, we have it in stock, so we'll deliver tomorrow morning."}],"vocabulary":[{"jp":"注文する","reading":"ちゅうもんする","vi":"đặt hàng","en":"to place an order"},{"jp":"納品","reading":"のうひん","vi":"giao hàng","en":"delivery"},{"jp":"単価","reading":"たんか","vi":"đơn giá","en":"unit price"},{"jp":"税込み","reading":"ぜいこみ","vi":"đã gồm thuế","en":"tax included"},{"jp":"合計","reading":"ごうけい","vi":"tổng cộng","en":"total"},{"jp":"在庫","reading":"ざいこ","vi":"hàng tồn kho","en":"stock, inventory"},{"jp":"トナー","reading":"とナー","vi":"mực in (toner)","en":"toner"},{"jp":"お支払い","reading":"おしはらい","vi":"thanh toán","en":"payment"},{"jp":"承知いたしました","reading":"しょうちいたしました","vi":"tôi đã rõ","en":"certainly, understood"}]},{"slug":"apointomento-wo-toru","date":"2026-11-06","duration_sec":66,"category":"kaigi-nittei","situation":{"en":"Making an appointment: setting a visit date by phone","jp":"アポイントメントを取る ― 電話で訪問の日を決める","vi":"Hẹn gặp khách hàng: gọi điện chốt ngày đến thăm"},"dialogue":[{"speaker":"sales_female","jp":"お世話になっております。ABC商事の佐藤と申します。","vi":"Xin chào ạ, tôi là Sato của công ty ABC Shoji ạ.","en":"Hello, this is Sato from ABC Shoji."},{"speaker":"client_female","jp":"お世話になっております。","vi":"Xin chào ạ.","en":"Hello."},{"speaker":"sales_female","jp":"新商品のカタログをお持ちしたいのですが、明日お伺いしてもよろしいでしょうか。","vi":"Tôi muốn mang catalog sản phẩm mới đến cho chị — ngày mai tôi đến thăm chị được không ạ?","en":"I'd like to bring our new product catalog — may I visit tomorrow?"},{"speaker":"client_female","jp":"ええ、ぜひ。明日は何時ごろがよろしいですか。","vi":"Vâng, mời chị cứ đến. Ngày mai khoảng mấy giờ thì tiện ạ?","en":"Yes, please. What time tomorrow would suit you?"},{"speaker":"sales_female","jp":"午後2時はいかがでしょうか。30分ほどで済ませます。","vi":"2 giờ chiều thì sao ạ? Chỉ mất khoảng 30 phút thôi ạ.","en":"How about 2 p.m.? It will only take about 30 minutes."},{"speaker":"client_female","jp":"あいにく2時は会議が入っております。4時でしたら空いておりますが。","vi":"Tiếc là 2 giờ tôi có cuộc họp. 4 giờ thì tôi trống, không biết có được không ạ?","en":"Unfortunately I have a meeting at 2. I'm free at 4, though."},{"speaker":"sales_female","jp":"はい、4時でお願いいたします。4時に伺わせていただきます。","vi":"Vâng, 4 giờ ạ. Tôi sẽ đến lúc 4 giờ ạ.","en":"Yes, 4 o'clock, please. I'll visit at 4."},{"speaker":"client_female","jp":"承知いたしました。受付でお名前をお伝えください。","vi":"Tôi đã rõ ạ. Chị nhớ báo tên ở quầy lễ tân nhé.","en":"Understood. Please give your name at reception."},{"speaker":"sales_female","jp":"かしこまりました。確認のメールをお送りいたします。","vi":"Dạ vâng. Tôi sẽ gửi thêm email xác nhận ạ.","en":"Certainly. I'll also send a confirmation email."},{"speaker":"client_female","jp":"よろしくお願いいたします。お待ちしております。","vi":"Rất mong được đón tiếp chị ạ.","en":"Thank you. I look forward to seeing you."}],"vocabulary":[{"jp":"アポイントメント","reading":"あぽいんとめんと","vi":"cuộc hẹn","en":"appointment"},{"jp":"カタログ","reading":"かたろぐ","vi":"catalog sản phẩm","en":"catalog"},{"jp":"お伺いする","reading":"うかがう","vi":"đến thăm (kính ngữ)","en":"to visit (humble)"},{"jp":"新商品","reading":"しんしょうひん","vi":"sản phẩm mới","en":"new product"},{"jp":"会議","reading":"かいぎ","vi":"cuộc họp","en":"meeting"},{"jp":"空いている","reading":"あいている","vi":"đang trống","en":"free, available"},{"jp":"承知いたしました","reading":"しょうちいたしました","vi":"tôi đã rõ","en":"certainly, understood"},{"jp":"受付","reading":"うけつけ","vi":"quầy lễ tân","en":"reception"},{"jp":"確認","reading":"かくにん","vi":"xác nhận","en":"confirmation"}]},{"slug":"kyoka-wo-motomeru-the-ten","date":"2026-11-06","duration_sec":66,"category":"shinsei-kyoka","situation":{"jp":"許可を求める ― 出先からの直帰の許可","vi":"Xin phép cấp trên — xin về thẳng sau khi thăm khách hàng","en":"Asking permission — going straight home after a client visit"},"dialogue":[{"speaker":"staff_male","jp":"課長、すみません。今から横浜の取引先へ行くのですが、直帰させていただけますでしょうか。","vi":"Trưởng phòng, xin lỗi anh. Em sắp đến thăm khách hàng ở Yokohama, xong việc em có thể về thẳng nhà được không ạ?","en":"Manager, excuse me. I'm about to visit our client in Yokohama — after that, may I go straight home?"},{"speaker":"boss_male","jp":"直帰？明日の朝一番の会議の資料は、できているのか。","vi":"Về thẳng à? Tài liệu cho cuộc họp đầu giờ sáng mai đã xong chưa?","en":"Straight home? Are the documents for tomorrow's first meeting ready?"},{"speaker":"staff_male","jp":"はい、資料のほとんどはできております。今晩、自宅で仕上げて、メールでお送りいたします。","vi":"Dạ, gần như xong hết rồi ạ. Tối nay em sẽ hoàn thiện ở nhà rồi gửi qua email cho anh ạ.","en":"Yes, most of the documents are ready. Tonight I'll finish them at home and send them by email."},{"speaker":"boss_male","jp":"そうか。会議は朝一だから。","vi":"Ra vậy. Cuộc họp lại là việc đầu tiên buổi sáng đấy.","en":"I see. The meeting is first thing in the morning, after all."},{"speaker":"staff_male","jp":"承知しております。夜9時までには、必ずお送りいたします。","vi":"Em hiểu ạ. Em nhất định sẽ gửi trước 9 giờ tối ạ.","en":"Understood. I'll definitely send them by 9 p.m."},{"speaker":"boss_male","jp":"なるほど。では、誰かに手伝わせれば、もっと早く終わるんじゃないか。","vi":"Ra vậy. Thế thì nhờ ai đó phụ một tay, có phải xong sớm hơn không?","en":"I see. Then, if you get someone to help, wouldn't it finish sooner?"},{"speaker":"staff_male","jp":"はい、鈴木さんには、この前も手伝っていただきましたので、たびたびお願いできません。","vi":"Dạ, chị Suzuki lần trước cũng đã giúp em rồi, nên em không thể nhờ đi nhờ lại mãi được ạ.","en":"Yes, Ms. Suzuki already helped me last time, so I can't keep asking her again and again."},{"speaker":"boss_male","jp":"そうか。分かった。ただし、資料は今夜中に送る。","vi":"Ra vậy. Được rồi. Nhưng nhớ gửi tài liệu trong tối nay đấy nhé.","en":"I see. All right. But send the documents tonight."},{"speaker":"staff_male","jp":"ありがとうございます。必ずお送りいたしますので、ご安心ください。","vi":"Cảm ơn anh nhiều ạ. Em nhất định sẽ gửi, nên anh cứ yên tâm ạ.","en":"Thank you very much. I will definitely send them, so please don't worry."},{"speaker":"boss_male","jp":"よし、頼んだぞ。取引先では、よろしく伝えておいてくれ。","vi":"Tốt, nhờ em đấy. Ở chỗ khách hàng thì gửi lời hỏi thăm của anh nhé.","en":"Good, I'm counting on you. And please give my regards to the client."}],"vocabulary":[{"jp":"許可","reading":"きょか","vi":"sự cho phép","en":"permission"},{"jp":"直帰","reading":"ちょっき","vi":"về thẳng nhà","en":"going straight home"},{"jp":"取引先","reading":"とりひきさき","vi":"khách hàng, đối tác","en":"client"},{"jp":"資料","reading":"しりょう","vi":"tài liệu","en":"documents"},{"jp":"仕上げる","reading":"しあげる","vi":"hoàn thiện","en":"to finish up"},{"jp":"目を通す","reading":"めをとおす","vi":"xem qua","en":"to look through"},{"jp":"手伝う","reading":"てつだう","vi":"giúp đỡ","en":"to help"},{"jp":"認める","reading":"みとめる","vi":"cho phép","en":"to allow, approve"},{"jp":"朝一","reading":"あさいち","vi":"đầu giờ sáng","en":"first thing in the morning"}]},{"slug":"iitsutaeru-kikidasu","date":"2026-11-06","duration_sec":66,"category":"houkoku-renraku","situation":{"en":"Passing on a message & eliciting information: a client's message and confirming the delivery date","jp":"言い伝える・聞きだす ― 取引先からの伝言と納期の確認","vi":"Truyền đạt lời nhắn & khéo hỏi thông tin: lời nhắn của khách hàng và xác nhận hạn giao"},"dialogue":[{"speaker":"staff_female","jp":"課長、お時間よろしいでしょうか。ABC商事の鈴木様から、伝言をお預かりしました。","vi":"Trưởng phòng, anh có chút thời gian không ạ? Em đã nhận lời nhắn của anh Suzuki bên ABC Shoji ạ.","en":"Manager, do you have a moment? I've taken a message from Mr. Suzuki at ABC Shoji."},{"speaker":"boss_male","jp":"ああ、どうした。何か用件があったのか。","vi":"À, có chuyện gì vậy? Có việc gì à?","en":"Yes, what is it? Was there something he needed?"},{"speaker":"staff_female","jp":"はい、納期を前倒しできないかとのことです。連絡先も伺いました。","vi":"Dạ, anh ấy hỏi có thể giao hàng sớm hơn hạn đã hẹn không ạ. Em cũng đã xin số liên lạc của anh ấy rồi ạ.","en":"Yes, he asked whether the delivery date could be moved earlier. I've also taken down his contact details."},{"speaker":"boss_male","jp":"そうか。納期は今週の金曜日だな。在庫はあるのか。","vi":"Ra vậy. Hạn giao là thứ Sáu tuần này đúng không. Trong kho còn hàng không?","en":"I see. The delivery date was this Friday, right? Do we have the stock in the warehouse?"},{"speaker":"staff_female","jp":"はい、確認いたしました。在庫は十分ございます。","vi":"Dạ, em đã kiểm tra rồi ạ. Hàng trong kho còn đủ ạ.","en":"Yes, I've checked. We have enough stock."},{"speaker":"boss_male","jp":"なるほど。配送業者に聞き出してみてくれ。木曜日には出荷できるはずだ。","vi":"Ra vậy. Hãy hỏi bên vận chuyển xem sao nhé. Thứ Năm chắc là xuất hàng được đấy.","en":"I see. Please ask the delivery company. We should be able to ship on Thursday."},{"speaker":"staff_female","jp":"承知いたしました。木曜日にお届けできると、お伝えしてよろしいでしょうか。","vi":"Em hiểu ạ. Em có thể báo với anh Suzuki là dự kiến giao được vào thứ Năm được không ạ?","en":"Understood. May I tell Mr. Suzuki that we expect to deliver on Thursday?"},{"speaker":"boss_male","jp":"ああ、そう伝えてくれ。決まったら、メールでも確認しておいてくれ。","vi":"Ừ, cứ báo như thế đi. Khi nào chốt được thì gửi thêm email xác nhận nữa nhé.","en":"Yes, tell him that. Once it's settled, please also confirm by email."},{"speaker":"staff_female","jp":"かしこまりました。確認が取れ次第、すぐにお電話で折り返しいたします。","vi":"Dạ vâng. Ngay khi xác nhận được, em sẽ gọi lại cho anh ấy ngay ạ.","en":"Certainly. As soon as I have confirmation, I'll call him back right away."},{"speaker":"boss_male","jp":"よし、頼んだぞ。鈴木様には、よろしく言い伝えておいてくれ。","vi":"Tốt, nhờ em đấy. Gửi lời hỏi thăm của anh đến anh Suzuki nhé.","en":"Good, I'm counting on you. And please give my regards to Mr. Suzuki."}],"vocabulary":[{"jp":"言い伝える","reading":"いいつたえる","vi":"truyền đạt lại lời nhắn","en":"to pass on a message"},{"jp":"伝言","reading":"でんごん","vi":"lời nhắn (để lại)","en":"message (left for someone)"},{"jp":"聞き出す","reading":"ききだす","vi":"khéo hỏi ra (thông tin)","en":"to elicit, draw out (information)"},{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery date"},{"jp":"前倒し","reading":"まえだおし","vi":"dời lên sớm hơn","en":"moving (a date) earlier"},{"jp":"在庫","reading":"ざいこ","vi":"tồn kho","en":"stock, inventory"},{"jp":"配送","reading":"はいそう","vi":"giao hàng","en":"delivery, shipping"},{"jp":"折り返し","reading":"おりかえし","vi":"gọi lại (điện thoại)","en":"calling back"},{"jp":"確認","reading":"かくにん","vi":"xác nhận, kiểm tra","en":"confirmation, check"}]},{"slug":"iken-wo-noberu-teian-suru","date":"2026-11-07","duration_sec":66,"category":"iken-kokan","situation":{"en":"Expressing an opinion & making a proposal — proposing recyclable paper packaging","jp":"意見を述べる・提案する ― 会議で意見を述べて提案する","vi":"Phát biểu ý kiến & đề xuất trong cuộc họp: đề xuất đổi bao bì sang giấy tái chế"},"dialogue":[{"speaker":"staff_female","jp":"課長、新商品のパッケージについて、意見を述べさせてください。","vi":"Trưởng phòng, về bao bì của sản phẩm mới, cho em xin phép trình bày ý kiến ạ.","en":"Manager, regarding the new product's packaging, please let me share my opinion."},{"speaker":"boss_male","jp":"ああ、どうぞ。何かいいアイデアがあるのか。","vi":"Ừ, cứ nói đi. Có ý tưởng gì hay à?","en":"Sure, go ahead. Do you have a good idea?"},{"speaker":"staff_female","jp":"はい、プラスチック容器を、リサイクルできる紙の容器に変えることを提案いたします。","vi":"Dạ, em đề xuất đổi bao bì nhựa hiện tại sang bao bì giấy có thể tái chế ạ.","en":"Yes, I propose we change the current plastic containers to recyclable paper ones."},{"speaker":"boss_male","jp":"ほう、理由は何だい。","vi":"Ồ, lý do là gì?","en":"Oh, what's the reason?"},{"speaker":"staff_female","jp":"はい、環境問題に取り組む。コストも抑えられます。","vi":"Dạ, chúng ta cùng giải quyết vấn đề môi trường. Chi phí cũng có thể kiềm chế được ạ.","en":"Yes, we'd be tackling environmental issues. The cost can be kept down too."},{"speaker":"boss_male","jp":"なるほど。ただ、紙の容器は壊れやすくないか。","vi":"Ra vậy. Nhưng bao bì giấy có dễ rách không?","en":"I see. But won't paper containers break easily?"},{"speaker":"staff_female","jp":"はい、大丈夫です。試作品は十分な強度です。","vi":"Dạ, không sao ạ. Mẫu thử có độ bền đầy đủ ạ.","en":"Yes, that's fine. The prototype is sufficiently durable."},{"speaker":"boss_male","jp":"そうか。では、来週までにサンプルと見積もりを持ってきてくれ。","vi":"Ra vậy. Vậy thì, trước tuần sau hãy mang mẫu thử và bảng ước tính đến cho tôi nhé.","en":"I see. Then, please bring me a sample and an estimate by next week."},{"speaker":"staff_female","jp":"かしこまりました。来週の会議までに、資料を準備いたします。","vi":"Dạ vâng. Em sẽ chuẩn bị tài liệu trước cuộc họp tuần sau ạ.","en":"Certainly. I'll prepare the materials before next week's meeting."},{"speaker":"boss_male","jp":"よし、頼んだぞ。いい提案だと思うよ。","vi":"Tốt, nhờ em đấy. Tôi thấy đó là một đề xuất hay.","en":"Good, I'm counting on you. I think it's a good proposal."}],"vocabulary":[{"jp":"意見を述べる","reading":"いけんをのべる","vi":"phát biểu ý kiến","en":"to express an opinion"},{"jp":"提案する","reading":"ていあんする","vi":"đề xuất","en":"to propose"},{"jp":"理由","reading":"りゆう","vi":"lý do","en":"reason"},{"jp":"容器","reading":"ようき","vi":"bao bì, vật chứa","en":"container"},{"jp":"リサイクル","reading":"リサイクル","vi":"tái chế","en":"recycling"},{"jp":"環境問題","reading":"かんきょうもんだい","vi":"vấn đề môi trường","en":"environmental issue"},{"jp":"強度","reading":"きょうど","vi":"độ bền","en":"strength, durability"},{"jp":"試作品","reading":"しさくひん","vi":"mẫu thử","en":"prototype"},{"jp":"費用","reading":"ひよう","vi":"chi phí","en":"cost, expense"}]},{"slug":"settoku-suru-hanron-suru","date":"2026-11-07","duration_sec":66,"category":"iken-kokan","situation":{"en":"Persuading & counter-arguing politely — countering a new product's price plan","jp":"説得する・反論する ― 新製品の価格案に反論する","vi":"Thuyết phục & phản biện lịch sự — phản biện phương án giá sản phẩm mới"},"dialogue":[{"speaker":"boss_male","jp":"新製品の価格案だが、少し高めに設定したいんだ。","vi":"Về phương án giá cho sản phẩm mới, tôi muốn đặt giá hơi cao một chút.","en":"About the new product's pricing plan, I'd like to set it a bit high."},{"speaker":"staff_male","jp":"お言葉を返すようですが、この価格では負担が大きいと思うんです。","vi":"Xin lỗi phải nói ngược lại, nhưng giá này sẽ là gánh nặng lớn cho khách hàng mục tiêu.","en":"I don't mean to contradict you, but at this price, I think the burden on our target customers would be too great."},{"speaker":"boss_male","jp":"高級イメージを作れば、受け入れられるんじゃないかね。","vi":"Nếu tạo được hình ảnh cao cấp thì chắc sẽ được chấp nhận thôi.","en":"If we build a premium image, I think it will be accepted."},{"speaker":"staff_male","jp":"はい、基本的には賛成ですが、競合と比べると、割高感がぬぐえないんです。","vi":"Dạ, về cơ bản em đồng ý, nhưng so với đối thủ thì cảm giác đắt vẫn không xua đi được.","en":"Yes, I basically agree, but compared with our competitors, the sense of overpricing just won't go away."},{"speaker":"boss_male","jp":"なるほど。だが、デザインの斬新さは他社にない強みだ。","vi":"Ra vậy. Nhưng sự mới lạ trong thiết kế là điểm mạnh mà hãng khác không có.","en":"I see. But the novelty of the design is a strength our rivals don't have."},{"speaker":"staff_male","jp":"はい、そのとおりですが、差別化できるのはデザインだけなんです。","vi":"Dạ, đúng là như vậy, nhưng điểm khác biệt duy nhất là thiết kế thôi ạ.","en":"Yes, that's true, but design is the only thing that sets us apart."},{"speaker":"boss_male","jp":"うーん、なるほどな。何か代替案はあるか。","vi":"Ừm, ra vậy. Có phương án thay thế nào không?","en":"Hmm, I see. Do you have an alternative?"},{"speaker":"staff_male","jp":"はい、発売を段階的にして、まず限定版でどうでしょうか。","vi":"Dạ, sao ta không ra mắt theo từng giai đoạn, trước hết bán bản giới hạn ạ?","en":"Yes, how about launching in stages — first a limited edition?"},{"speaker":"boss_male","jp":"そうか、説得されたよ。限定版なら反発も抑えられるな。","vi":"Ra vậy, cậu thuyết phục được tôi rồi. Nếu là bản giới hạn thì phản ứng về giá cũng kiềm chế được.","en":"I see, you've persuaded me. With a limited edition, the backlash over price can be kept down."},{"speaker":"staff_male","jp":"はい、ありがとうございます。来週、会議で説明します。","vi":"Dạ, cảm ơn anh. Tuần sau, em sẽ giải thích trong cuộc họp ạ.","en":"Yes, thank you. Next week, I'll explain it at the meeting."}],"vocabulary":[{"jp":"説得する","reading":"せっとくする","vi":"thuyết phục","en":"to persuade"},{"jp":"反論する","reading":"はんろんする","vi":"phản biện, nói ngược lại","en":"to counter-argue"},{"jp":"価格案","reading":"かかくあん","vi":"phương án giá","en":"price proposal"},{"jp":"負担","reading":"ふたん","vi":"gánh nặng","en":"burden"},{"jp":"競合他社","reading":"きょうごうたしゃ","vi":"đối thủ cạnh tranh","en":"competitor"},{"jp":"割高感","reading":"わりだかかん","vi":"cảm giác đắt","en":"sense of being overpriced"},{"jp":"差別化","reading":"さべつか","vi":"khác biệt hóa","en":"differentiation"},{"jp":"段階的","reading":"だんかいてき","vi":"theo từng giai đoạn","en":"phased, step-by-step"},{"jp":"限定版","reading":"げんていばん","vi":"bản giới hạn","en":"limited edition"}]},{"slug":"machigai-denwa","date":"2026-11-07","duration_sec":66,"category":"denwa","situation":{"jp":"間違い電話・電話トラブル ― 番号を間違えてしまったとき","vi":"Gọi nhầm số & sự cố điện thoại — gọi nhầm số, xác nhận lại số đã bấm","en":"Wrong-number calls & phone troubles — dialing the wrong number and confirming it"},"dialogue":[{"speaker":"staff_female","jp":"お世話になっております。ABC商事の営業部の鈴木様でいらっしゃいますでしょうか。","vi":"Xin chào, cho tôi hỏi đây có phải chị Suzuki, phòng kinh doanh, công ty ABC không ạ?","en":"Hello, may I speak with Ms. Suzuki of the sales department at ABC Corporation?"},{"speaker":"other_female","jp":"恐れ入りますが、こちらはABC商事ではございません。おかけ間違いではないでしょうか。","vi":"Xin lỗi chị, nhưng đây không phải là ABC商事. Có lẽ chị đã gọi nhầm số phải không ạ?","en":"I'm sorry, but this isn't ABC Corporation. I think you may have dialed the wrong number."},{"speaker":"staff_female","jp":"あっ、失礼いたしました。間違い電話でしたか。ご迷惑をおかけして、申し訳ございません。","vi":"À, xin lỗi chị. Tôi đã gọi nhầm số sao? Tôi xin lỗi vì đã làm phiền chị.","en":"Oh, I'm sorry. Did I dial the wrong number? I apologize for the trouble."},{"speaker":"other_female","jp":"いえいえ、お気になさらないでください。どちらにおかけだったのでしょうか。","vi":"Không sao đâu ạ, chị đừng bận tâm. Chị định gọi cho số nào vậy ạ?","en":"Not at all, please don't worry. Which number were you trying to reach?"},{"speaker":"staff_female","jp":"はい、ABC商事の鈴木様にお電話しようと思いまして。番号を確認させていただけますでしょうか。","vi":"Dạ, tôi định gọi cho chị Suzuki của ABC商事. Cho tôi xác nhận lại số điện thoại được không ạ?","en":"Yes, I was trying to call Ms. Suzuki at ABC Corporation. Could I check the number, please?"},{"speaker":"other_female","jp":"もちろんです。03-4420-5317です。","vi":"Dạ, tất nhiên ạ. Số là 03-4420-5317 ạ.","en":"Yes, of course. The number is 03-4420-5317."},{"speaker":"staff_female","jp":"ありがとうございます。私は最後を「はち」と押したつもりでしたが、一つ間違えてしまったようです。","vi":"Cảm ơn chị. Tôi cứ tưởng mình đã bấm số cuối là 8, nhưng hình như tôi đã bấm sai một số.","en":"Thank you. I thought I pressed 8 as the last digit, but it seems I got one digit wrong."},{"speaker":"other_female","jp":"そうでしたか。","vi":"Ra vậy ạ.","en":"I see."},{"speaker":"staff_female","jp":"はい、本当に申し訳ございませんでした。改めて正しい番号にかけ直させていただきます。","vi":"Dạ, tôi thật sự xin lỗi. Tôi sẽ gọi lại số đúng ngay ạ.","en":"Yes, I'm truly sorry. I'll call the correct number again right away."},{"speaker":"other_female","jp":"はい、とんでもございません。","vi":"Dạ, không có gì đâu ạ.","en":"Yes, not at all."}],"vocabulary":[{"jp":"間違い電話","reading":"まちがいでんわ","vi":"gọi nhầm số","en":"wrong-number call"},{"jp":"おかけ間違い","reading":"おかけまちがい","vi":"bấm nhầm số","en":"wrong number"},{"jp":"番号","reading":"ばんごう","vi":"số điện thoại","en":"phone number"},{"jp":"確認","reading":"かくにん","vi":"xác nhận","en":"to confirm"},{"jp":"恐れ入ります","reading":"おそれいります","vi":"xin lỗi (lịch sự)","en":"I'm sorry (polite)"},{"jp":"ご迷惑","reading":"ごめいわく","vi":"sự phiền phức","en":"trouble"},{"jp":"かけ直す","reading":"かけなおす","vi":"gọi lại","en":"to call back"},{"jp":"連絡先","reading":"れんらくさき","vi":"số liên lạc","en":"contact number"},{"jp":"折り返し","reading":"おりかえし","vi":"gọi lại (cuộc gọi lại)","en":"return call"}]},{"slug":"orei-to-owabi","date":"2026-11-08","duration_sec":66,"category":"aisatsu-reigi","situation":{"jp":"お礼とおわび ― 納品の遅れを詫び、ご理解に感謝する","vi":"Cảm ơn & xin lỗi trang trọng: xin lỗi vì giao hàng trễ, cảm ơn sự thông cảm của khách hàng","en":"Formal thanks & apology: apologizing for a late delivery and thanking the client for their understanding"},"dialogue":[{"speaker":"sales_male","jp":"本日はお忙しいところ、お時間をいただき、ありがとうございます。","vi":"Hôm nay cảm ơn chị đã dành thời gian dù rất bận ạ.","en":"Thank you for making time for me today despite your busy schedule."},{"speaker":"manager_female","jp":"ええ、どうぞ。あ、手土産まで、お気になさらずに。","vi":"Ừ, mời anh ngồi. À, anh còn mang quà đến nữa, đừng khách sáo vậy.","en":"Of course, please have a seat. Oh, and please don't worry about bringing a gift."},{"speaker":"sales_male","jp":"はい、ありがとうございます。先日の納品の件で、お詫びに参りました。","vi":"Cảm ơn chị. Em đến để xin lỗi về vụ giao hàng hôm trước ạ.","en":"Thank you. I've come to apologize about the recent delivery."},{"speaker":"manager_female","jp":"そうですね。納期が三日ほど遅れましたね。","vi":"Ừ nhỉ. Hạn giao trễ mất ba ngày đấy.","en":"Yes. The delivery was about three days late, wasn't it."},{"speaker":"sales_male","jp":"はい、ご迷惑をおかけして、申し訳ございません。","vi":"Dạ, gây phiền toái cho chị, em vô cùng xin lỗi ạ.","en":"Yes, I'm very sorry for the inconvenience we caused."},{"speaker":"manager_female","jp":"うん、現場も少し困りましたよ。原因は分かりましたか。","vi":"Ừ, bên hiện trường cũng gặp chút rắc rối. Đã rõ nguyên nhân chưa?","en":"Yes, our site had some trouble too. Do you know what caused it?"},{"speaker":"sales_male","jp":"はい、手配ミスでした。再発防止策をまとめました。","vi":"Dạ, do sắp xếp nhầm. Em đã tổng hợp biện pháp để không tái diễn ạ.","en":"Yes, it was a mistake in the arrangements. I've put together measures to prevent it happening again."},{"speaker":"manager_female","jp":"なるほど。対策はしっかりしていますね。","vi":"Ra vậy. Ừ, biện pháp đối phó làm kỹ đấy.","en":"I see. Well, the countermeasures look thorough."},{"speaker":"sales_male","jp":"ありがとうございます。昨日発送済みで、明日届く予定です。","vi":"Cảm ơn chị. Hàng đã gửi đi hôm qua, mai sẽ tới ạ.","en":"Thank you. It went out yesterday and should arrive tomorrow."},{"speaker":"manager_female","jp":"分かりました。では、今後ともよろしくお願いしますね。","vi":"Tôi hiểu rồi. Vậy thì, mong anh tiếp tục giúp đỡ nhé.","en":"Understood. Well then, I look forward to working with you as always."}],"vocabulary":[{"jp":"お礼","reading":"おれい","vi":"cảm ơn","en":"thanks"},{"jp":"お詫び","reading":"おわび","vi":"lời xin lỗi trang trọng","en":"formal apology"},{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery deadline"},{"jp":"ご迷惑","reading":"ごめいわく","vi":"phiền toái","en":"inconvenience"},{"jp":"手配","reading":"てはい","vi":"sắp xếp","en":"arrangement"},{"jp":"再発防止","reading":"さいはつぼうし","vi":"ngăn tái diễn","en":"preventing recurrence"},{"jp":"手土産","reading":"てみやげ","vi":"quà mang theo khi thăm","en":"gift brought on a visit"},{"jp":"発送","reading":"はっそう","vi":"gửi hàng đi","en":"dispatch, shipping"},{"jp":"今後とも","reading":"こんごとも","vi":"từ nay về sau","en":"from now on"}]},{"slug":"adobaisu-wo-motomeru","file":"assets/video-adobaisu-wo-motomeru-sua-loi-2.mp4","date":"2026-11-08","duration_sec":66,"category":"iken-kokan","situation":{"jp":"アドバイスを求める ― 気難しいお客さんとの初打ち合わせ","vi":"Xin lời khuyên — chuẩn bị gặp khách hàng khó tính lần đầu","en":"Asking for advice — preparing to meet a difficult client for the first time"},"dialogue":[{"speaker":"junior_female","jp":"渡辺さん、すみません。相談があって、アドバイスをいただけますか。","vi":"Chị Watanabe, xin lỗi chị. Em có việc muốn hỏi, chị cho em xin lời khuyên được không ạ?","en":"Watanabe-san, sorry — I have something to ask. Could I get your advice?"},{"speaker":"senior_female","jp":"あ、どうしたの？何かあった？","vi":"Ơ, sao thế? Có chuyện gì à?","en":"Oh, what's up? Did something happen?"},{"speaker":"junior_female","jp":"明日、初めて山崎さんと打ち合わせなんです。気難しいって評判で、緊張してて。","vi":"Ngày mai em có buổi họp đầu tiên với anh Yamazaki. Nghe nói anh ấy nổi tiếng là khó tính, nên em đang hồi hộp.","en":"Tomorrow I have my first meeting with Mr. Yamazaki. He's known for being hard to please, so I'm nervous."},{"speaker":"senior_female","jp":"ああ、山崎さんね。確かに最初は厳しいけど。","vi":"À, anh Yamazaki à. Ừ, lúc đầu anh ấy nghiêm khắc thật, nhưng mà…","en":"Ah, Mr. Yamazaki. Yes, he's strict at first, but…"},{"speaker":"junior_female","jp":"どうしたらいいでしょうか。気をつけること、ありますか。","vi":"Em nên làm thế nào ạ? Có điều gì cần lưu ý không?","en":"What should I do? Is there anything I should watch out for?"},{"speaker":"senior_female","jp":"そうね。まず、最初は軽い話から。","vi":"Ừ nhỉ. Trước hết, hãy bắt đầu từ vài câu chuyện nhẹ nhàng.","en":"Well. First, start with some light conversation."},{"speaker":"junior_female","jp":"なるほど。あ、それから資料は、会社概要と実績と価格の3点にまとめました。","vi":"Em hiểu rồi. À, còn tài liệu thì em đã tóm tắt thành 3 điểm: giới thiệu công ty, thành tích và giá ạ.","en":"I see. Oh, and the materials — I've summarized them into three points: company overview, track record, and price."},{"speaker":"senior_female","jp":"いいわね。あと、印象も大事よ。","vi":"Ừ, tốt đấy. À, ấn tượng đầu tiên cũng quan trọng nhé.","en":"Yes, good. First impressions matter too."},{"speaker":"junior_female","jp":"はい、あの、もし分からないことを聞かれたら、どうすれば…。","vi":"Vâng. Ơ, nếu anh ấy hỏi điều em không biết thì em phải làm sao ạ…","en":"Yes. Um, if he asks me something I don't know, what should I do…?"},{"speaker":"senior_female","jp":"その場で無理に答えないで。確認して、ご連絡しますって言えばいいの。","vi":"Đừng cố trả lời ngay tại chỗ. Cứ nói 'Để em kiểm tra rồi liên hệ lại ạ' là được.","en":"Don't force an answer on the spot. Just say 'I'll check and get back to you.'"}],"vocabulary":[{"jp":"アドバイス","reading":"アドバイス","vi":"lời khuyên","en":"advice"},{"jp":"相談する","reading":"そうだんする","vi":"hỏi ý kiến, tham khảo","en":"to consult, ask for advice"},{"jp":"緊張する","reading":"きんちょうする","vi":"hồi hộp, căng thẳng","en":"to be nervous, tense"},{"jp":"気難しい","reading":"きむずかしい","vi":"khó tính, khó chiều","en":"hard to please"},{"jp":"評判","reading":"ひょうばん","vi":"tiếng tăm, danh tiếng","en":"reputation"},{"jp":"打ち合わせ","reading":"うちあわせ","vi":"buổi họp, cuộc gặp làm việc","en":"meeting, discussion"},{"jp":"印象","reading":"いんしょう","vi":"ấn tượng","en":"impression"},{"jp":"資料","reading":"しりょう","vi":"tài liệu","en":"materials, documents"},{"jp":"確認する","reading":"かくにんする","vi":"xác nhận, kiểm tra","en":"to confirm, check"}]},{"slug":"kaigi-no-shinko","file":"assets/video-kaigi-no-shinko-sua-loi.mp4","date":"2026-11-09","duration_sec":66,"category":"kaigi-nittei","situation":{"jp":"会議の進行 ― 進捗会議のまとめと決定","vi":"Điều hành cuộc họp: tổng kết & chốt quyết định trong họp tiến độ","en":"Running a meeting: summarizing and deciding in a progress meeting"},"dialogue":[{"speaker":"staff_male","jp":"では、定例の進捗会議を始めます。今日の議題は、新商品の発売日についてです。","vi":"Vậy thì, chúng ta bắt đầu buổi họp tiến độ định kỳ. Chủ đề hôm nay là ngày ra mắt sản phẩm mới.","en":"Let's start the regular progress meeting. Today's agenda is the new product's launch date."},{"speaker":"manager_female","jp":"はい、よろしくお願いします。まず、現在の進捗を教えてください。","vi":"Dạ, nhờ anh nhé. Trước hết, hãy cho tôi biết tiến độ hiện tại.","en":"Yes, please go ahead. First, tell me the current progress."},{"speaker":"staff_male","jp":"はい、開発はほぼ終わりました。ただ、パッケージのデザインが、まだ決まっていません。","vi":"Dạ, phần phát triển gần như đã xong. Chỉ có điều, thiết kế bao bì vẫn chưa chốt được.","en":"Yes, development is almost finished. However, the package design hasn't been decided yet."},{"speaker":"manager_female","jp":"そうですか。デザインが決まらないと、印刷も始められませんね。","vi":"Ra vậy. Nếu thiết kế chưa chốt thì cũng chưa bắt đầu in được nhỉ.","en":"I see. If the design isn't decided, we can't start printing either."},{"speaker":"staff_male","jp":"そうなんです。来週の水曜日までには、デザインの提案を一つに絞ります。","vi":"Vâng, đúng vậy ạ. Chậm nhất là thứ Tư tuần sau, em sẽ rút gọn các phương án thiết kế còn một.","en":"Yes, that's right. By next Wednesday, I'll narrow the design proposals down to one."},{"speaker":"manager_female","jp":"分かりました。では、発売日は来月の十日に決定しましょうか。","vi":"Tôi hiểu rồi. Vậy thì, ngày ra mắt chốt vào ngày 10 tháng sau nhé.","en":"Understood. Then, shall we set the launch date for the 10th of next month?"},{"speaker":"staff_male","jp":"はい、十日でしたら、期限に間に合います。あの、広告の準備は、どうしますか。","vi":"Dạ, ngày 10 thì kịp hạn ạ. À, còn việc chuẩn bị quảng cáo thì sao ạ?","en":"Yes, the 10th works — we'll make the deadline. Um, what about preparing the ads?"},{"speaker":"manager_female","jp":"広告は、来週から始めましょう。担当は、佐藤さんにお願いします。","vi":"Quảng cáo thì bắt đầu từ tuần sau nhé. Nhờ anh Sato phụ trách.","en":"Let's start the ads next week. I'll ask Mr. Sato to take charge."},{"speaker":"staff_male","jp":"かしこまりました。結論をまとめますと、発売日は来月十日、広告は来週からですね。","vi":"Dạ vâng. Tóm lại kết luận là: ngày ra mắt là ngày 10 tháng sau, quảng cáo bắt đầu từ tuần sau, đúng không ạ?","en":"Certainly. To sum up: the launch date is the 10th of next month, and the ads start next week, correct?"},{"speaker":"manager_female","jp":"はい、その通りです。","vi":"Dạ, đúng như vậy ạ.","en":"Yes, exactly."}],"vocabulary":[{"jp":"進行","reading":"しんこう","vi":"điều hành, tiến hành","en":"proceedings, running (a meeting)"},{"jp":"議題","reading":"ぎだい","vi":"chủ đề cuộc họp","en":"agenda, topic"},{"jp":"進捗","reading":"しんちょく","vi":"tiến độ","en":"progress"},{"jp":"結論","reading":"けつろん","vi":"kết luận","en":"conclusion"},{"jp":"決定","reading":"けってい","vi":"quyết định, chốt","en":"decision"},{"jp":"担当","reading":"たんとう","vi":"phụ trách","en":"in charge"},{"jp":"期限","reading":"きげん","vi":"hạn (chót)","en":"deadline"},{"jp":"次回","reading":"じかい","vi":"lần sau","en":"next time"},{"jp":"提案","reading":"ていあん","vi":"đề xuất, phương án","en":"proposal"}]},{"slug":"kakaku-kosho","file":"assets/video-kakaku-kosho-sua-loi.mp4","date":"2026-11-09","duration_sec":66,"category":"irai-koushou","situation":{"en":"Price negotiation: asking a supplier for a discount","jp":"価格交渉 ― 仕入先との値引き交渉","vi":"Đàm phán giá: thương lượng giảm giá với nhà cung cấp"},"dialogue":[{"speaker":"staff_female","jp":"お世話になっております。今回の見積書の件で、ちょっとご相談があって。","vi":"Xin chào ạ. Về bản báo giá lần này, tôi có chút việc muốn trao đổi.","en":"Hello. Regarding this quotation, I have something I'd like to discuss."},{"speaker":"manager_female","jp":"どうぞ。価格の件ですね。","vi":"Vâng, mời chị cứ nói. Là chuyện về giá, đúng không ạ?","en":"Yes, please go ahead. It's about the price, isn't it?"},{"speaker":"staff_female","jp":"はい。単価なんですが、今のままだと予算オーバーでして。","vi":"Dạ. Về đơn giá, với mức hiện tại thì hơi vượt ngân sách của chúng tôi.","en":"Yes. About the unit price — as it stands, it goes a bit over our budget."},{"speaker":"manager_female","jp":"数量を増やしていただければ、値引きも検討できます。","vi":"Nếu chị tăng số lượng thì chúng tôi cũng có thể xem xét giảm giá.","en":"If you could increase the quantity, we could consider a discount."},{"speaker":"staff_female","jp":"来月から月200個に増やす予定です。","vi":"Vâng, từ tháng sau chúng tôi dự định tăng lên 200 cái mỗi tháng.","en":"Yes, from next month we plan to increase it to 200 units a month."},{"speaker":"manager_female","jp":"それでしたら、3％の値引きなら、すぐにお答えできます。","vi":"Nếu vậy thì mức giảm 3%, tôi có thể trả lời ngay.","en":"In that case, a 3% discount is something I can agree to right away."},{"speaker":"staff_female","jp":"3％ですか。…あ、長期取引で、5％でも…。","vi":"3% ạ... À, nếu chị cân nhắc hợp tác lâu dài thì 5% cũng...","en":"3%? ... Ah, if you consider a long-term partnership, even 5%..."},{"speaker":"manager_female","jp":"長期の契約ですか。…分かりました。1年なら、5％で対応します。","vi":"Hợp đồng dài hạn ạ... Tôi hiểu rồi. Nếu là hợp đồng 1 năm thì chúng tôi sẽ đáp ứng mức 5%.","en":"A long-term contract? ... Understood. If it's a one-year contract, we can offer 5%."},{"speaker":"staff_female","jp":"ありがとうございます！修正した見積書を、明日までに送っていただけますか。","vi":"Cảm ơn chị nhiều! Chị có thể gửi bản báo giá đã sửa chậm nhất là ngày mai được không ạ?","en":"Thank you so much! Could you send the revised quotation by tomorrow?"},{"speaker":"manager_female","jp":"はい、もちろんです。納期は来週の金曜日のままですよ。","vi":"Vâng, tất nhiên rồi. Ngày giao hàng vẫn là thứ Sáu tuần sau, chị cứ yên tâm.","en":"Yes, of course. The delivery date is still next Friday, so please don't worry."}],"vocabulary":[{"jp":"価格交渉","reading":"かかくこうしょう","vi":"đàm phán giá","en":"price negotiation"},{"jp":"値引き","reading":"ねびき","vi":"giảm giá","en":"discount"},{"jp":"単価","reading":"たんか","vi":"đơn giá","en":"unit price"},{"jp":"数量","reading":"すうりょう","vi":"số lượng","en":"quantity"},{"jp":"見積書","reading":"みつもりしょ","vi":"bản báo giá","en":"quotation"},{"jp":"契約","reading":"けいやく","vi":"hợp đồng","en":"contract"},{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery date"},{"jp":"条件","reading":"じょうけん","vi":"điều kiện","en":"condition"},{"jp":"長期取引","reading":"ちょうきとりひき","vi":"giao dịch dài hạn","en":"long-term business"}]},{"slug":"nouki-no-henko","date":"2026-11-10","duration_sec":66,"category":"tehai-logistics","situation":{"jp":"納期の変更 ― 納品の遅れと新しい日程のご案内","vi":"Thay đổi ngày giao hàng: báo trễ & đề xuất lịch mới","en":"Changing the delivery date: reporting a delay & proposing a new schedule"},"dialogue":[{"speaker":"sales_male","jp":"お世話になっております。今回の納期変更の件で、ご相談があって伺いました。","vi":"Xin chào ạ. Về việc thay đổi ngày giao hàng lần này, tôi đến để trao đổi với anh ạ.","en":"Hello. I've come to discuss the change to the delivery date this time."},{"speaker":"client_male","jp":"ああ、納期の件か。何か問題でもあったのか。","vi":"À, chuyện ngày giao hàng à. Có vấn đề gì sao?","en":"Ah, the delivery date. Is there a problem?"},{"speaker":"sales_male","jp":"はい、申し訳ございません。部品の入荷が遅れまして、納期が一週間ほど延びそうです。","vi":"Dạ, tôi vô cùng xin lỗi. Việc nhập linh kiện bị chậm nên ngày giao có thể sẽ lùi lại khoảng một tuần.","en":"Yes, I'm very sorry. The parts delivery is delayed, so the delivery date will likely slip by about a week."},{"speaker":"client_male","jp":"一週間もか。それは困ったな。うちの予定にも影響が出るよ。","vi":"Lùi cả một tuần sao... Vậy thì rắc rối rồi. Kế hoạch bên tôi cũng sẽ bị ảnh hưởng.","en":"A whole week... That's a problem. It will affect our schedule too."},{"speaker":"sales_male","jp":"ええ、本当に申し訳ございません。代替案として、数量を分けてお届けするのはいかがでしょうか。","vi":"Vâng, tôi thực sự xin lỗi. Thay vào đó, chúng tôi chia số lượng giao làm hai đợt thì anh thấy thế nào ạ?","en":"Yes, I truly apologize. As an alternative, how about splitting the quantity into two deliveries?"},{"speaker":"client_male","jp":"分納か。うん、それなら何とかなるかもしれない。","vi":"Giao chia đợt à. Ừ, vậy thì có lẽ cũng xoay xở được.","en":"Split delivery... Hmm, that might just work."},{"speaker":"sales_male","jp":"はい、まず来週の水曜日までに半分をお届けして、残りは翌週の月曜日に。","vi":"Dạ, trước hết chúng tôi sẽ giao một nửa trước thứ Tư tuần sau, phần còn lại vào thứ Hai tuần sau nữa.","en":"Yes, first we'll deliver half by next Wednesday, and the rest on the Monday of the week after."},{"speaker":"client_male","jp":"なるほど。じゃあ、その方向で調整してくれ。","vi":"Ra vậy. Vậy thì cứ theo hướng đó mà điều chỉnh giúp tôi.","en":"I see. Then please arrange it that way."},{"speaker":"sales_male","jp":"かしこまりました。ご迷惑をおかけして、","vi":"Dạ vâng. Gây phiền toái cho anh,","en":"Certainly. I'm sorry for the inconvenience..."},{"speaker":"client_male","jp":"分かった。今後は、早めに連絡してくれよ。","vi":"Được rồi. Từ nay về sau, hãy liên lạc sớm hơn nhé.","en":"Understood. From now on, please contact us earlier."}],"vocabulary":[{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery date"},{"jp":"変更","reading":"へんこう","vi":"thay đổi","en":"change"},{"jp":"延期","reading":"えんき","vi":"hoãn lại","en":"postponement"},{"jp":"遅れる","reading":"おくれる","vi":"bị chậm","en":"to be delayed"},{"jp":"お詫び","reading":"おわび","vi":"lời xin lỗi","en":"apology"},{"jp":"ご迷惑","reading":"ごめいわく","vi":"phiền toái","en":"inconvenience"},{"jp":"調整","reading":"ちょうせい","vi":"điều chỉnh","en":"adjustment"},{"jp":"対応","reading":"たいおう","vi":"ứng phó, xử lý","en":"handling, response"},{"jp":"代替案","reading":"だいたいあん","vi":"phương án thay thế","en":"alternative plan"}]},{"slug":"shinnyu-shain-no-shido","date":"2026-11-10","duration_sec":66,"category":"houkoku-renraku","situation":{"en":"Guiding a new employee: handover & report–contact–consult","jp":"新入社員の指導 ― 新人の業務指導と報連相","vi":"Hướng dẫn nhân viên mới: bàn giao công việc & báo cáo–liên lạc–trao đổi"},"dialogue":[{"speaker":"senior_female","jp":"ようこそ、うちのチームへ。新入社員の指導は、私が担当します。","vi":"Chào mừng em đến với đội của chị. Việc hướng dẫn nhân viên mới sẽ do chị phụ trách.","en":"Welcome to our team. I'll be in charge of guiding you as a new employee."},{"speaker":"employee_male","jp":"はい、よろしくお願いします。まず、何をしたらいいですか。","vi":"Dạ, em mong được chị chỉ bảo ạ. Trước tiên em nên làm gì ạ?","en":"Yes, I look forward to working with you. What should I do first?"},{"speaker":"senior_female","jp":"まず、研修のスケジュールを確認しましょう。","vi":"Trước hết, mình cùng xem lịch đào tạo nhé.","en":"First, let's check the training schedule."},{"speaker":"employee_male","jp":"午前は社内のルール、午後は引き継ぎですね。","vi":"Buổi sáng là nội quy công ty, buổi chiều là bàn giao công việc ạ.","en":"Company rules in the morning, and the handover of work in the afternoon, right?"},{"speaker":"senior_female","jp":"うん、メモを取ること。分からないことは、すぐ相談してね。","vi":"Ừ, hãy ghi chép lại nhé. Không hiểu gì thì hỏi ngay nhé.","en":"Yes — take notes. If you don't understand something, ask right away."},{"speaker":"employee_male","jp":"報連相ですね。報告と連絡と相談、覚えました。","vi":"Báo cáo – liên lạc – trao đổi ạ. Báo cáo, liên lạc và trao đổi, em nhớ rồi ạ.","en":"Reporting, contacting, and consulting. Report, contact, consult — I'll remember."},{"speaker":"senior_female","jp":"その調子。送る前に、必ず確認してね。","vi":"Đúng rồi, cứ thế nhé. Trước khi gửi, nhớ kiểm tra kỹ nhé.","en":"That's right. Before sending anything, always check it first."},{"speaker":"employee_male","jp":"はい。あの、お客様への対応で、気をつけることはありますか。","vi":"Dạ. À, khi tiếp khách hàng, có điều gì cần lưu ý không ạ?","en":"Yes. Um, when dealing with customers, is there anything I should be careful about?"},{"speaker":"senior_female","jp":"まず、相手の話を最後まで聞くこと。返事は「確認して、ご連絡します」でいいよ。","vi":"Trước hết, hãy nghe hết câu chuyện của đối phương. Trả lời \"Để tôi xác nhận rồi liên hệ lại\" là được.","en":"First, listen to the other person all the way to the end. Replying \"I'll check and get back to you\" is fine."},{"speaker":"employee_male","jp":"はい、ありがとうございます。がんばります！","vi":"Dạ, em cảm ơn chị ạ. Em sẽ cố gắng ạ!","en":"Yes, thank you very much. I'll do my best!"}],"vocabulary":[{"jp":"新入社員","reading":"しんにゅうしゃいん","vi":"nhân viên mới","en":"new employee"},{"jp":"指導","reading":"しどう","vi":"hướng dẫn","en":"guidance"},{"jp":"引き継ぎ","reading":"ひきつぎ","vi":"bàn giao","en":"handover"},{"jp":"報連相","reading":"ほうれんそう","vi":"báo cáo–liên lạc–trao đổi","en":"report–contact–consult"},{"jp":"敬語","reading":"けいご","vi":"kính ngữ","en":"honorific language"},{"jp":"確認","reading":"かくにん","vi":"xác nhận, kiểm tra","en":"confirmation, check"},{"jp":"対応","reading":"たいおう","vi":"ứng phó, tiếp đón","en":"handling, dealing with"},{"jp":"研修","reading":"けんしゅう","vi":"đào tạo","en":"training"},{"jp":"配属","reading":"はいぞく","vi":"phân công về đội","en":"assignment to a team"}]},{"slug":"taishoku-idou-no-aisatsu","date":"2026-11-10","duration_sec":66,"category":"aisatsu-reigi","situation":{"en":"Farewell when transferring or leaving the company","jp":"退職・異動の挨拶 ― 会社を去る時のあいさつ","vi":"Lời chào khi chuyển công tác / nghỉ việc"},"dialogue":[{"speaker":"manager_male","jp":"あ、高橋さん。来月から大阪へ異動するんだってね。","vi":"À, Takahashi này. Nghe nói tháng sau em chuyển công tác sang Osaka à?","en":"Ah, Takahashi. I hear you're transferring to Osaka next month."},{"speaker":"employee_female","jp":"来月の一日から、大阪支社へ転勤することになりました。","vi":"Từ ngày mùng 1 tháng sau, em sẽ chuyển sang chi nhánh Osaka ạ.","en":"From the 1st of next month, I'll be transferred to the Osaka branch."},{"speaker":"manager_male","jp":"そうか。三年間、本当によくがんばってくれたね。","vi":"Ra vậy. Ba năm qua, em đã làm việc rất chăm chỉ.","en":"I see. You've really worked hard these three years."},{"speaker":"employee_female","jp":"いえ、部長には本当にお世話になりました。心から感謝しています。","vi":"Dạ không, em mới là người được sếp giúp đỡ rất nhiều ạ. Em vô cùng biết ơn.","en":"Not at all — I've truly been in your care, manager. I'm grateful from the bottom of my heart."},{"speaker":"manager_male","jp":"うん。で、引き継ぎの方は、どうなってる？","vi":"Ừ. Thế còn việc bàn giao thì sao rồi?","en":"Right. So, how's the handover going?"},{"speaker":"employee_female","jp":"はい、後任の鈴木さんに、資料と一緒に引き継ぎをしています。","vi":"Dạ, em đang bàn giao cho anh Suzuki — người kế nhiệm — cùng với tài liệu ạ.","en":"Yes, I'm handing over to my successor, Suzuki-san, along with the documents."},{"speaker":"manager_male","jp":"あ、そう。金曜日の送別会、みんな楽しみにしてるよ。","vi":"À, ra vậy. Mọi người đều mong chờ buổi tiệc chia tay thứ Sáu đấy.","en":"Ah, I see. Everyone's looking forward to Friday's farewell party."},{"speaker":"employee_female","jp":"ええ、ありがとうございます。最後に、みなさんにご挨拶させていただきます。","vi":"Dạ, em cảm ơn ạ. Cuối buổi, em xin phép nói vài lời chào tạm biệt với mọi người.","en":"Yes, thank you very much. At the end, I'd like to say a few farewell words to everyone."},{"speaker":"manager_male","jp":"うん、ぜひ。新しい職場でも、がんばってね。","vi":"Ừ, cứ nói nhé. Sang chỗ làm mới cũng cố gắng lên nhé.","en":"Yes, please do. Do your best at your new workplace too."},{"speaker":"employee_female","jp":"はい、ありがとうございます！大阪でもがんばります。","vi":"Dạ, em cảm ơn sếp nhiều ạ! Sang Osaka em cũng sẽ cố gắng ạ!","en":"Yes, thank you so much! I'll do my best in Osaka too."}],"vocabulary":[{"jp":"異動","reading":"いどう","vi":"chuyển công tác","en":"internal transfer"},{"jp":"転勤","reading":"てんきん","vi":"chuyển nơi làm việc","en":"job relocation, transfer"},{"jp":"退職","reading":"たいしょく","vi":"nghỉ việc, thôi việc","en":"resignation, retirement"},{"jp":"お世話になる","reading":"おせわになる","vi":"được ai giúp đỡ","en":"to be in someone's care"},{"jp":"引き継ぎ","reading":"ひきつぎ","vi":"bàn giao","en":"handover"},{"jp":"後任","reading":"こうにん","vi":"người kế nhiệm","en":"successor"},{"jp":"感謝","reading":"かんしゃ","vi":"lòng biết ơn","en":"gratitude"},{"jp":"送別会","reading":"そうべつかい","vi":"tiệc chia tay","en":"farewell party"},{"jp":"挨拶","reading":"あいさつ","vi":"lời chào tạm biệt","en":"farewell speech"}]},{"slug":"shin-seihin-no-shokai","date":"2026-11-11","duration_sec":66,"category":"sekkyaku-outai","situation":{"jp":"新製品の紹介 ― 取引先への商品説明","vi":"Giới thiệu sản phẩm mới với khách hàng","en":"Introducing a new product to a client"},"dialogue":[{"speaker":"sales_male","jp":"お世話になっております。新製品のタブレットなんですが、今日はサンプルをお持ちしました。","vi":"Xin chào ạ. Về chiếc máy tính bảng mới, hôm nay tôi mang mẫu đến ạ.","en":"Hello. Regarding our new tablet, I've brought a sample today."},{"speaker":"client_male","jp":"ああ、ありがとう。で、どんな特徴があるのか。","vi":"À, cảm ơn. Vậy nó có những đặc điểm gì nào.","en":"Ah, thank you. So, what features does it have?"},{"speaker":"sales_male","jp":"はい、まず、とても軽量なんです。","vi":"Dạ, trước hết, nó rất nhẹ ạ.","en":"Yes, first of all, it's very lightweight."},{"speaker":"client_male","jp":"なるほど。バッテリーは、どれくらい持つんだい。","vi":"Ra vậy. Pin thì dùng được bao lâu?","en":"I see. How long does the battery last?"},{"speaker":"sales_male","jp":"ええ、連続で12時間使えます。あの、仕様の詳細はこちらのカタログに載っております。","vi":"Dạ, dùng liên tục được 12 tiếng ạ. Chi tiết thông số kỹ thuật có trong cuốn catalogue này ạ.","en":"Yes, it runs for 12 hours continuously. The detailed specifications are in this catalog."},{"speaker":"client_male","jp":"うん。で、価格の方は、どうなってる？","vi":"Ừ. Thế giá cả thì sao?","en":"Right. And what about the price?"},{"speaker":"sales_male","jp":"はい、1台58,000円です。ただ、50台以上まとめてご注文いただければ、5％お値引きできます。","vi":"Dạ, 58.000 yên một chiếc ạ. Nhưng nếu quý công ty đặt gộp từ 50 chiếc trở lên, chúng tôi giảm giá 5% ạ.","en":"Yes, 58,000 yen per unit. But if you order 50 or more together, we can offer a 5% discount."},{"speaker":"client_male","jp":"そうか。発売はいつからなんだ。","vi":"Ra vậy. Khi nào thì bán ra?","en":"I see. When does it go on sale?"},{"speaker":"sales_male","jp":"来月から発売予定です。サンプルはこちらにございますので、ぜひお試しください。","vi":"Dự kiến bán ra từ tháng sau ạ. Mẫu ở đây ạ, mời anh dùng thử.","en":"It's scheduled to go on sale from next month. Here's the sample — please try it out."},{"speaker":"client_male","jp":"分かった。社内で検討して、来週までにご連絡するよ。","vi":"Được rồi. Tôi sẽ bàn bạc trong công ty rồi liên lạc lại trước tuần sau.","en":"Understood. I'll discuss it internally and get back to you by next week."}],"vocabulary":[{"jp":"新製品","reading":"しんせいひん","vi":"sản phẩm mới","en":"new product"},{"jp":"特徴","reading":"とくちょう","vi":"đặc điểm nổi bật","en":"feature"},{"jp":"仕様","reading":"しよう","vi":"thông số kỹ thuật","en":"specifications"},{"jp":"軽量","reading":"けいりょう","vi":"nhẹ","en":"lightweight"},{"jp":"バッテリー","reading":"battery","vi":"pin","en":"battery"},{"jp":"価格","reading":"かかく","vi":"giá cả","en":"price"},{"jp":"サンプル","reading":"sample","vi":"mẫu thử","en":"sample"},{"jp":"カタログ","reading":"catalog","vi":"cuốn catalogue","en":"catalog"},{"jp":"発売","reading":"はつばい","vi":"bán ra","en":"release, going on sale"}]},{"slug":"chikoku-no-renraku","file":"assets/video-chikoku-no-renraku-sua-loi-2.mp4","date":"2026-11-11","duration_sec":66,"category":"denwa","situation":{"en":"Calling your boss about being late due to a train delay","jp":"遅刻の連絡 ― 電車の遅れを上司に電話で知らせる","vi":"Báo trễ với cấp trên vì tàu điện bị trễ"},"dialogue":[{"speaker":"staff_female","jp":"課長、おはようございます。中村です。あの、今、電車が止まってしまって…","vi":"Trưởng phòng, chào buổi sáng ạ. Em là Nakamura. À, giờ tàu điện dừng lại mất rồi…","en":"Manager, good morning. This is Nakamura. Um, the train has stopped…"},{"speaker":"boss_male","jp":"ああ、どうしたの？","vi":"À, có chuyện gì thế?","en":"Ah, what's wrong?"},{"speaker":"staff_female","jp":"はい、信号トラブルで運転見合わせになって、新宿駅で足止めされています。","vi":"Dạ, do sự cố tín hiệu nên tàu tạm ngừng chạy, em đang bị kẹt ở ga Shinjuku ạ.","en":"Yes, due to a signal problem the service is suspended, and I'm stuck at Shinjuku Station."},{"speaker":"boss_male","jp":"そうか。で、何時ごろ着けそうなんだい。","vi":"Ra vậy. Thế khoảng mấy giờ thì em tới được?","en":"I see. So around what time can you get here?"},{"speaker":"staff_female","jp":"ええ、あと30分ほどかかるそうです。10時10分ごろの到着になりそうです。","vi":"Dạ, nghe nói còn mất khoảng 30 phút nữa mới chạy lại. Em sẽ tới nơi vào khoảng 10 giờ 10 ạ.","en":"Yes, they say it'll take about 30 more minutes. I should arrive around 10:10."},{"speaker":"boss_male","jp":"10時の定例会議があるけど、どうする？","vi":"10 giờ có cuộc họp định kỳ đấy, em tính sao?","en":"There's the 10 o'clock regular meeting — what shall we do?"},{"speaker":"staff_female","jp":"申し訳ありません。資料はチャットで送ります。最初だけお願いできますか。","vi":"Em xin lỗi ạ. Tài liệu em sẽ gửi qua chat. Anh phụ trách giúp em phần đầu được không ạ?","en":"I'm very sorry. I'll send the materials by chat. Could you cover just the first part for me?"},{"speaker":"boss_male","jp":"分かった。最初はこっちでやっておくよ。無理せず気をつけて来なさい。","vi":"Được rồi. Phần đầu để bên này lo. Đừng cố quá, cứ đi cẩn thận rồi tới nhé.","en":"Understood. We'll handle the beginning here. Don't rush — come carefully."},{"speaker":"staff_female","jp":"ありがとうございます。動き出したら、またご連絡します。遅延証明書ももらってきます。","vi":"Cảm ơn anh ạ. Khi tàu chạy lại em sẽ liên lạc lại. Em cũng sẽ lấy giấy chứng nhận tàu trễ ạ.","en":"Thank you. I'll contact you again once the train starts moving. I'll also get a delay certificate."},{"speaker":"boss_male","jp":"ああ、頼むよ。遅刻の連絡、ありがとう。じゃ、気をつけて。","vi":"Ừ, nhờ em đấy. Cảm ơn em đã báo trễ. Thôi, đi cẩn thận nhé.","en":"Right, thanks. Thank you for letting me know you'll be late. Take care."}],"vocabulary":[{"jp":"遅刻","reading":"ちこく","vi":"đi trễ","en":"lateness"},{"jp":"信号トラブル","reading":"しんごうトラブル","vi":"sự cố tín hiệu","en":"signal trouble"},{"jp":"運転見合わせ","reading":"うんてんみあわせ","vi":"tạm ngừng chạy","en":"service suspension"},{"jp":"足止め","reading":"あしどめ","vi":"bị kẹt lại","en":"being stranded"},{"jp":"到着","reading":"とうちゃく","vi":"đến nơi","en":"arrival"},{"jp":"定例会議","reading":"ていれいかいぎ","vi":"họp định kỳ","en":"regular meeting"},{"jp":"資料","reading":"しりょう","vi":"tài liệu","en":"materials"},{"jp":"遅延証明書","reading":"ちえんしょうめいしょ","vi":"giấy chứng nhận tàu trễ","en":"delay certificate"},{"jp":"連絡","reading":"れんらく","vi":"liên lạc","en":"contact"}]},{"slug":"kaigi-shitsu-no-yoyaku","file":"assets/video-kaigi-shitsu-no-yoyaku-sua-loi-2.mp4","date":"2026-11-11","duration_sec":66,"category":"kaigi-nittei","situation":{"en":"Booking a meeting room & preparing equipment","jp":"会議室の予約と準備 ― 取引先との会議の手配","vi":"Đặt phòng họp & chuẩn bị thiết bị"},"dialogue":[{"speaker":"staff_female","jp":"鈴木さん、ちょっといいですか。明日の午後5時からの打ち合わせで、会議室を予約したいんですが。","vi":"Chị Suzuki, chị có tiện một chút không ạ? Em muốn đặt phòng họp cho buổi họp 5 giờ chiều mai ạ.","en":"Suzuki, do you have a moment? I'd like to book a meeting room for tomorrow's 5 p.m. meeting."},{"speaker":"soumu_female","jp":"ああ、いいよ。何人で使うの？プロジェクターも要る？","vi":"À, được chứ. Dùng cho mấy người? Có cần máy chiếu không?","en":"Sure. How many people will use it? Do you need a projector too?"},{"speaker":"staff_female","jp":"はい、参加者は6名です。あの、プロジェクターと、ウェブ会議の機材もお願いできますか。","vi":"Dạ, có 6 người tham dự ạ. À, chị cho em mượn thêm máy chiếu và thiết bị họp trực tuyến được không ạ?","en":"Yes, six participants. Um, could I also ask for a projector and the video-conference equipment?"},{"speaker":"soumu_female","jp":"分かった。3階の会議室Aなら、空いてるよ。","vi":"Được rồi. Phòng họp A tầng 3 thì đang trống đấy.","en":"Got it. Meeting room A on the 3rd floor is free."},{"speaker":"staff_female","jp":"ええ、助かります。あの、資料は6部、お願いしてもいいですか。","vi":"Dạ, may quá. À, chị giúp em 6 bộ tài liệu được không ạ?","en":"Great, that helps. Um, could I ask you for six copies of the handouts?"},{"speaker":"soumu_female","jp":"いいよ。データ、今日の5時までにチャットで送ってくれる？","vi":"Được. Em gửi dữ liệu cho chị qua chat trước 5 giờ hôm nay nhé?","en":"Sure. Can you send me the data by 5 today on chat?"},{"speaker":"staff_female","jp":"はい、すぐ送ります。あと、ホワイトボードのマーカーも準備していただけますか。","vi":"Dạ, em gửi ngay ạ. Với cả, chị chuẩn bị giúp em bút viết bảng trắng nữa được không ạ?","en":"Yes, I'll send it right away. Also, could you prepare whiteboard markers too?"},{"speaker":"soumu_female","jp":"もちろん。じゃあ、全部そろえておくね。確認のメールも送るよ。","vi":"Dĩ nhiên rồi. Chị sẽ chuẩn bị xong mọi thứ. Chị cũng gửi email xác nhận cho em.","en":"Of course. I'll have everything ready. I'll send you a confirmation email too."},{"speaker":"staff_female","jp":"ありがとうございます。","vi":"Cảm ơn chị nhiều ạ.","en":"Thank you very much."},{"speaker":"soumu_female","jp":"いいえ、気にしないで。明日の打ち合わせ、がんばってね。","vi":"Không có gì đâu. Buổi họp ngày mai cố gắng nhé.","en":"Not at all. Good luck with tomorrow's meeting."}],"vocabulary":[{"jp":"会議室","reading":"かいぎしつ","vi":"phòng họp","en":"meeting room"},{"jp":"予約","reading":"よやく","vi":"đặt trước","en":"reservation, booking"},{"jp":"機材","reading":"きざい","vi":"thiết bị","en":"equipment"},{"jp":"プロジェクター","reading":"projector","vi":"máy chiếu","en":"projector"},{"jp":"空き","reading":"あき","vi":"còn trống","en":"availability"},{"jp":"参加者","reading":"さんかしゃ","vi":"người tham dự","en":"participant"},{"jp":"資料","reading":"しりょう","vi":"tài liệu","en":"handout, material"},{"jp":"確認","reading":"かくにん","vi":"xác nhận","en":"confirmation"},{"jp":"準備","reading":"じゅんび","vi":"chuẩn bị","en":"preparation"}]},{"slug":"keihi-seisan-no-kakunin","date":"2026-11-12","duration_sec":66.07,"category":"keiri-keiyaku","situation":{"en":"Checking an expense report & its deadline","jp":"経費精算の確認 ― 出張費の精算と締め切り","vi":"Xác nhận quyết toán chi phí công tác"},"dialogue":[{"speaker":"staff_male","jp":"山本さん、ちょっといいですか。先週の出張の経費精算について、確認させてください。","vi":"Chị Yamamoto, chị có tiện một chút không ạ? Em muốn xác nhận về việc quyết toán chi phí chuyến công tác tuần trước ạ.","en":"Ms. Yamamoto, do you have a moment? I'd like to check the expense settlement for last week's business trip."},{"speaker":"accounting_female","jp":"あ、田中さん。どうぞ。申請書は、もう出しましたか。","vi":"À, anh Tanaka. Mời anh. Anh đã nộp đơn đề nghị thanh toán chưa?","en":"Ah, Mr. Tanaka. Go ahead. Have you submitted the application form yet?"},{"speaker":"staff_male","jp":"はい、ええと…今朝、システムで送ったんですが、領収書の原本も必要ですか。","vi":"Dạ, ừm… sáng nay em đã gửi qua hệ thống rồi, nhưng có cần cả bản gốc hóa đơn không ạ?","en":"Yes, um… I sent it through the system this morning, but do I need the original receipts too?"},{"speaker":"accounting_female","jp":"そうですね。原本は、月末までに経理に届けてくださいね。締め切りは15日ですから。","vi":"Ừ, đúng rồi. Bản gốc thì anh gửi cho phòng kế toán trước cuối tháng nhé. Hạn chót là ngày 15 đấy.","en":"That's right. Please bring the originals to Accounting by the end of the month. The deadline is the 15th."},{"speaker":"staff_male","jp":"あ、15日ですね。交通費と宿泊費で、合計4万3千円です。","vi":"À, ngày 15 ạ. Tiền đi lại và tiền khách sạn, tổng cộng là 43.000 yên ạ.","en":"Ah, the 15th. Transport and hotel costs, 43,000 yen in total."},{"speaker":"accounting_female","jp":"はい、確認しますね。宿泊費の領収書、1枚足りないですね。","vi":"Dạ, để tôi kiểm tra nhé. Hóa đơn tiền khách sạn còn thiếu 1 tờ đấy.","en":"Let me check. It looks like one hotel receipt is missing."},{"speaker":"staff_male","jp":"えっ、本当ですか。あの、ホテルの分は、メールで届いたPDFでもいいですか。","vi":"Hả, thật ạ? À, phần khách sạn thì bản PDF gửi qua email có được không ạ?","en":"Huh, really? Um, for the hotel part, would the PDF that arrived by email be okay?"},{"speaker":"accounting_female","jp":"ええ、大丈夫ですよ。PDFを印刷して、申請書、一緒に提出してください。","vi":"Ừ, được nhé. Anh in PDF ra rồi nộp cùng với đơn đề nghị thanh toán nhé.","en":"Yes, that's fine. Please print the PDF and submit it together with the application form."},{"speaker":"staff_male","jp":"分かりました。すぐ出します。承認はいつごろになりますか。","vi":"Vâng, em nộp ngay ạ. Việc phê duyệt thì khoảng khi nào xong ạ?","en":"Understood, I'll submit it right away. About how long until it's approved?"},{"speaker":"accounting_female","jp":"承認が下りたら、来月の10日に振り込みますね。お疲れさまでした。","vi":"Khi được duyệt, tiền sẽ được chuyển vào ngày 10 tháng sau nhé. Anh vất vả rồi.","en":"Once it's approved, we'll transfer the money on the 10th of next month. Good work today."}],"vocabulary":[{"jp":"経費精算","reading":"けいひせいさん","vi":"quyết toán chi phí","en":"expense settlement"},{"jp":"出張","reading":"しゅっちょう","vi":"chuyến công tác","en":"business trip"},{"jp":"領収書","reading":"りょうしゅうしょ","vi":"hóa đơn, biên lai","en":"receipt"},{"jp":"締め切り","reading":"しめきり","vi":"hạn chót","en":"deadline"},{"jp":"交通費","reading":"こうつうひ","vi":"tiền đi lại","en":"transport costs"},{"jp":"宿泊費","reading":"しゅくはくひ","vi":"tiền khách sạn","en":"hotel costs"},{"jp":"申請書","reading":"しんせいしょ","vi":"đơn đề nghị","en":"application form"},{"jp":"承認","reading":"しょうにん","vi":"phê duyệt","en":"approval"},{"jp":"振込","reading":"ふりこみ","vi":"chuyển khoản","en":"bank transfer"}]},{"slug":"shanai-kenshu-no-annai","date":"2026-11-12","duration_sec":66,"category":"annai-oshirase","situation":{"en":"Announcing in-house training: explaining the new training program","jp":"社内研修の案内 ― 新しい研修制度の説明","vi":"Giới thiệu đào tạo nội bộ: giải thích chế độ đào tạo mới"},"dialogue":[{"speaker":"training_manager_male","jp":"山田君、来月からの新しい社内研修の件、もう聞いた？","vi":"Anh Yamada, em đã nghe về chương trình đào tạo nội bộ mới từ tháng sau chưa?","en":"Yamada, have you heard about the new in-house training starting next month?"},{"speaker":"staff_male","jp":"あ、はい。ええと、メールは見たんですけど、詳しくはまだ…","vi":"À, dạ. Ừm, em có thấy email rồi nhưng chưa rõ chi tiết…","en":"Ah, yes. Um, I saw the email, but I don't know the details yet…"},{"speaker":"training_manager_male","jp":"そうか。じゃあ、簡単に説明するよ。対象は入社3年目まで、締め切りは今週の金曜日だ。","vi":"Ra vậy. Để anh giải thích ngắn gọn nhé. Đối tượng là nhân viên trong 3 năm đầu, hạn đăng ký là thứ Sáu tuần này.","en":"I see. Let me explain briefly. It's for employees in their first three years, and the application deadline is this Friday."},{"speaker":"staff_male","jp":"えっ、今週の金曜日ですか。受講料は自己負担ですか。","vi":"Hả, thứ Sáu tuần này ạ? Học phí có phải tự trả không ạ?","en":"Huh, this Friday? Do we have to pay the tuition ourselves?"},{"speaker":"training_manager_male","jp":"いや、費用は会社持ちだよ。オンラインと対面、好きなほうを選べるんだ。","vi":"Không, công ty lo toàn bộ chi phí. Có thể chọn học online hoặc trực tiếp, thích bên nào cũng được.","en":"No, the company covers the full cost. You can choose online or in person, whichever you like."},{"speaker":"staff_male","jp":"そうなんですね。あの、修了証って、もらえるんですか。","vi":"Ra vậy ạ. Ừm, có được cấp chứng chỉ hoàn thành không ạ?","en":"I see. Um, do we get a certificate of completion?"},{"speaker":"training_manager_male","jp":"もちろん。最後まで受講すれば、修了証を出すよ。","vi":"Tất nhiên. Học đến cuối thì sẽ được cấp chứng chỉ.","en":"Of course. If you complete it, you'll get a certificate."},{"speaker":"staff_male","jp":"分かりました。じゃあ、今日中に申し込みます。申請は専用サイトからですよね。","vi":"Em hiểu rồi. Vậy hôm nay em sẽ đăng ký. Nộp đơn qua trang web chuyên dụng đúng không ạ?","en":"Understood. I'll apply today. The application is via the dedicated website, right?"},{"speaker":"training_manager_male","jp":"そう、サイトから申し込んでくれ。参加は勤務時間内だよ。分からないことがあったら聞きに来て。","vi":"Đúng, đăng ký qua trang đó nhé. Tham gia trong giờ làm việc nên cứ yên tâm. Có gì không hiểu thì cứ đến hỏi anh.","en":"Yes, apply via the site. It's during working hours, so don't worry. If anything's unclear, come and ask me."},{"speaker":"staff_male","jp":"ありがとうございます。さっそく申し込みます。","vi":"Cảm ơn anh ạ. Em sẽ đăng ký ngay.","en":"Thank you. I'll apply right away."}],"vocabulary":[{"jp":"研修","reading":"けんしゅう","vi":"đào tạo nội bộ","en":"in-house training"},{"jp":"対象","reading":"たいしょう","vi":"đối tượng","en":"eligible people"},{"jp":"申し込み","reading":"もうしこみ","vi":"đăng ký","en":"application"},{"jp":"締め切り","reading":"しめきり","vi":"hạn chót","en":"deadline"},{"jp":"受講料","reading":"じゅこうりょう","vi":"học phí","en":"tuition fee"},{"jp":"費用","reading":"ひよう","vi":"chi phí","en":"cost, expense"},{"jp":"修了証","reading":"しゅうりょうしょう","vi":"chứng chỉ hoàn thành","en":"certificate of completion"},{"jp":"受講","reading":"じゅこう","vi":"tham gia khóa học","en":"to take a course"},{"jp":"申請","reading":"しんせい","vi":"nộp đơn","en":"formal application"}]},{"slug":"kuremu-no-foro-appu","date":"2026-11-12","duration_sec":66,"category":"sekkyaku-outai","situation":{"en":"Complaint follow-up: checking the exchanged product & apologizing by phone","jp":"クレームのフォローアップ ― 交換後の状況確認とお詫びの電話","vi":"Theo dõi sau khiếu nại: kiểm tra sản phẩm đã đổi & xin lỗi qua điện thoại"},"dialogue":[{"speaker":"support_female","jp":"お世話になっております。ABC商事の中村と申します。","vi":"Xin chào, tôi là Nakamura của công ty ABC Shoji ạ.","en":"Hello, this is Nakamura from ABC Shoji."},{"speaker":"customer_male","jp":"はい、渡辺です。交換していただいた掃除機の件ですね。","vi":"Vâng, tôi là Watanabe. Về chiếc máy hút bụi đã được đổi cho tôi đúng không ạ?","en":"Yes, this is Watanabe. It's about the vacuum cleaner you exchanged, right?"},{"speaker":"support_female","jp":"はい、改めてお詫び申し上げます。交換後の状況はいかがでしょうか。","vi":"Dạ, tôi xin lỗi thêm lần nữa. Sau khi đổi, tình hình sử dụng thế nào ạ?","en":"Yes. Once again, I sincerely apologize. How is the exchanged product working for you?"},{"speaker":"customer_male","jp":"うん、問題なく使えていますよ。","vi":"Ừ, đến giờ dùng vẫn ổn.","en":"Yeah, it's working fine so far."},{"speaker":"support_female","jp":"そうですか、よかったです。ご不便はございませんか。","vi":"Vậy thì tốt quá ạ. Có gì bất tiện không ạ?","en":"I see, that's good to hear. Is there any inconvenience?"},{"speaker":"customer_male","jp":"ええ、大丈夫です。不具合もありませんよ。","vi":"Dạ, không sao. Cũng không có lỗi gì.","en":"Yes, it's fine. There's no defect either."},{"speaker":"support_female","jp":"ありがとうございます。保証期間は1年間延長いたしました。","vi":"Cảm ơn anh. Thời hạn bảo hành đã được kéo dài thêm 1 năm ạ.","en":"Thank you. We have extended the warranty period by one year."},{"speaker":"customer_male","jp":"ああ、そうなんですか。えっと、保証書はどうなりますか。","vi":"À, vậy sao. Ừm, còn phiếu bảo hành thì sao?","en":"Oh, is that so? Um, what about the warranty card?"},{"speaker":"support_female","jp":"はい、保証書は今週中に郵送をいたします。","vi":"Dạ, phiếu bảo hành mới sẽ được gửi qua bưu điện trong tuần này ạ.","en":"Yes, we will mail the new warranty card to you within this week."},{"speaker":"customer_male","jp":"はい、分かりました。何かありましたら、またご連絡します。今日はありがとうございました。","vi":"Vâng, tôi hiểu rồi. Có gì tôi sẽ liên lạc lại. Cảm ơn chị hôm nay nhé.","en":"Yes, understood. If anything comes up, I'll contact you again. Thank you for today."}],"vocabulary":[{"jp":"交換","reading":"こうかん","vi":"đổi hàng","en":"exchange, replacement"},{"jp":"お詫び","reading":"おわび","vi":"lời xin lỗi","en":"apology"},{"jp":"状況","reading":"じょうきょう","vi":"tình hình","en":"situation, condition"},{"jp":"ご不便","reading":"ごふべん","vi":"sự bất tiện","en":"inconvenience"},{"jp":"不具合","reading":"ふぐあい","vi":"lỗi, trục trặc","en":"defect, malfunction"},{"jp":"保証","reading":"ほしょう","vi":"bảo hành","en":"warranty, guarantee"},{"jp":"保証書","reading":"ほしょうしょ","vi":"phiếu bảo hành","en":"warranty card"},{"jp":"郵送","reading":"ゆうそう","vi":"gửi qua bưu điện","en":"mailing"},{"jp":"ご連絡","reading":"ごれんらく","vi":"liên lạc","en":"contact"}]},{"slug":"shigoto-no-irai","file":"assets/video-shigoto-no-irai-sua-loi-2.mp4","date":"2026-11-13","duration_sec":66,"category":"irai-koushou","situation":{"jp":"仕事の依頼 ― 同僚に資料作成を依頼する","vi":"Nhờ đồng nghiệp chuẩn bị tài liệu cho buổi họp","en":"Asking a colleague to prepare documents for a meeting"},"dialogue":[{"speaker":"employee_female","jp":"あの、山田さん、ちょっとお願いがあるんだけど、いい？","vi":"À, Yamada này, mình có việc muốn nhờ cậu, được không?","en":"Um, Yamada, I have a favour to ask — is that OK?"},{"speaker":"colleague_female","jp":"ええ、どうしたんですか。","vi":"Dạ, có chuyện gì vậy ạ?","en":"Sure, what's up?"},{"speaker":"employee_female","jp":"はい、実は3時からの会議の資料、まだ途中なんです。急にクライアントが来ちゃって。","vi":"Dạ, thật ra tài liệu cho buổi họp lúc 3 giờ vẫn đang làm dở. Tự nhiên khách hàng lại đến sớm.","en":"Yes, actually the documents for the 3 o'clock meeting are still unfinished. A client suddenly showed up early."},{"speaker":"colleague_female","jp":"あ、そうなんですか。で、どうすればいいですか。","vi":"À, vậy sao ạ. Vậy mình phải làm gì ạ?","en":"Oh, is that so? So what should I do?"},{"speaker":"employee_female","jp":"うん、2枚目の途中までできてるから、あと2枚の作成、お願いできませんか。","vi":"Ừ, mình làm đến giữa trang thứ 2 rồi, cậu chuẩn bị giúp mình 2 trang còn lại được không?","en":"Yeah, I've got as far as the middle of page 2 — could you prepare the remaining 2 pages for me?"},{"speaker":"colleague_female","jp":"わかりました。締め切りは何時ですか。","vi":"Tôi hiểu rồi. Hạn chót là mấy giờ ạ?","en":"Understood. What time is the deadline?"},{"speaker":"employee_female","jp":"至急で、2時半までにお願いしたいんです。引き継ぎ、ここにメモしてあります。","vi":"Gấp lắm, mình muốn nhờ cậu xong trước 2 giờ rưỡi. Phần bàn giao mình ghi chú ở đây rồi.","en":"It's urgent — I'd like it by 2:30. I've written the handover notes here."},{"speaker":"colleague_female","jp":"はい、2時半ですね。内容、確認しますね。","vi":"Vâng, 2 giờ rưỡi ạ. Tôi sẽ kiểm tra lại nội dung.","en":"OK, 2:30. I'll check the content."},{"speaker":"employee_female","jp":"ありがとう。依頼を受けてくれて、助かります。終わったら、メールで送ってもらえますか。","vi":"Cảm ơn nhé. Cậu nhận lời giúp, may quá. Xong thì gửi qua email giúp mình nhé.","en":"Thank you. It really helps that you'll take this on. When it's done, could you send it by email?"},{"speaker":"colleague_female","jp":"はい、もちろんです。間に合うようにします。","vi":"Vâng, tất nhiên rồi. Mình sẽ làm kịp.","en":"Yes, of course. I'll make it in time."}],"vocabulary":[{"jp":"依頼","reading":"いらい","vi":"nhờ việc","en":"request, asking a favour"},{"jp":"資料","reading":"しりょう","vi":"tài liệu","en":"documents, materials"},{"jp":"作成","reading":"さくせい","vi":"soạn thảo, chuẩn bị","en":"preparation, creation"},{"jp":"締め切り","reading":"しめきり","vi":"hạn chót","en":"deadline"},{"jp":"至急","reading":"しきゅう","vi":"gấp, khẩn","en":"urgent"},{"jp":"お願い","reading":"おねがい","vi":"nhờ vả","en":"request, ask"},{"jp":"引き継ぎ","reading":"ひきつぎ","vi":"bàn giao","en":"handover"},{"jp":"確認","reading":"かくにん","vi":"xác nhận","en":"confirmation, check"},{"jp":"間に合う","reading":"まにあう","vi":"kịp","en":"to be in time"}]},{"slug":"kyuka-no-hikitsugi-renraku","file":"assets/video-kyuka-no-hikitsugi-renraku-sua-loi-2.mp4","date":"2026-11-13","duration_sec":66,"category":"houkoku-renraku","situation":{"jp":"休暇中の業務の引き継ぎ連絡 ― 休暇前に同僚へ引き継ぎを伝える","vi":"Bàn giao công việc trước kỳ nghỉ: truyền đạt nội dung bàn giao cho đồng nghiệp","en":"Handing over work before a vacation: briefing a colleague on ongoing tasks"},"dialogue":[{"speaker":"employee_male","jp":"あの、鈴木さん、来週、休暇を取るので、引き継ぎをお願いできますか。","vi":"À, Suzuki này, tuần sau mình nghỉ phép nên muốn nhờ cậu bàn giao công việc giúp mình được không?","en":"Um, Suzuki, I'm taking next week off, so could I ask you to handle the handover for me?"},{"speaker":"colleague_female","jp":"もちろんです。何から伝えていただけますか。","vi":"Tất nhiên rồi ạ. Anh muốn truyền đạt từ đâu trước ạ?","en":"Of course. What would you like to start with?"},{"speaker":"employee_male","jp":"はい、まず、A社のプロジェクトです。締め切りは金曜日の5時で、資料は共有フォルダに入れてあります。","vi":"Vâng, trước hết là dự án của công ty A. Hạn chót là 5 giờ chiều thứ Sáu, tài liệu mình đã để trong thư mục chung rồi.","en":"Yes, first, the A Company project. The deadline is 5 p.m. Friday, and the files are in the shared folder."},{"speaker":"colleague_female","jp":"あ、わかりました。で、承認はもう取れていますか。","vi":"À, tôi hiểu rồi. Thế đã xin được phê duyệt chưa ạ?","en":"Ah, understood. Has the approval been obtained yet?"},{"speaker":"employee_male","jp":"ええ、まだなんです。部長の承認が必要で、木曜日の朝までに、取っていただけますか。","vi":"Ừ, vẫn chưa ạ. Cần có phê duyệt của trưởng phòng, cậu xin giúp mình trước sáng thứ Năm được không?","en":"Well, not yet. We need the manager's approval — could you get it by Thursday morning?"},{"speaker":"colleague_female","jp":"はい、大丈夫です。木曜日の朝、部長に確認しますね。","vi":"Vâng, được ạ. Sáng thứ Năm tôi sẽ xác nhận với trưởng phòng.","en":"Yes, no problem. I'll check with the manager on Thursday morning."},{"speaker":"employee_male","jp":"ありがとうございます。あと、急ぎの連絡は、携帯に連絡してください。連絡先は、ここに書いてあります。","vi":"Cảm ơn nhé. Còn việc gì gấp thì cứ liên lạc qua điện thoại di động giúp mình. Thông tin liên lạc mình ghi ở đây rồi.","en":"Thank you. And for anything urgent, please contact me on my mobile. My contact details are written here."},{"speaker":"colleague_female","jp":"あ、なるほど。で、困ったときは、誰に聞けばいいですか。","vi":"À, ra vậy. Thế lúc gặp khó khăn thì hỏi ai ạ?","en":"Ah, I see. And if I run into trouble, who should I ask?"},{"speaker":"employee_male","jp":"うん、詳しいことは、山本さんが担当です。山本さんに聞いてください。戻るのは、再来週の月曜日です。","vi":"Ừ, việc chi tiết thì anh Yamamoto phụ trách. Cậu hỏi anh Yamamoto nhé. Mình trở lại vào thứ Hai tuần sau nữa.","en":"Yeah, Yamamoto is in charge of the details. Please ask him. I'll be back on Monday the week after next."},{"speaker":"colleague_female","jp":"良い休暇を。戻られたら、また教えてくださいね。","vi":"Chúc anh kỳ nghỉ vui vẻ. Khi trở lại thì kể cho tôi nghe nhé.","en":"Have a good vacation. Tell me all about it when you're back."}],"vocabulary":[{"jp":"引き継ぎ","reading":"ひきつぎ","vi":"bàn giao","en":"handover"},{"jp":"休暇","reading":"きゅうか","vi":"kỳ nghỉ","en":"vacation, holiday"},{"jp":"締め切り","reading":"しめきり","vi":"hạn chót","en":"deadline"},{"jp":"承認","reading":"しょうにん","vi":"phê duyệt","en":"approval"},{"jp":"担当","reading":"たんとう","vi":"phụ trách","en":"person in charge"},{"jp":"資料","reading":"しりょう","vi":"tài liệu","en":"materials, files"},{"jp":"連絡先","reading":"れんらくさき","vi":"thông tin liên lạc","en":"contact details"},{"jp":"共有フォルダ","reading":"きょうゆうフォルダ","vi":"thư mục chung","en":"shared folder"},{"jp":"連絡","reading":"れんらく","vi":"liên lạc","en":"contact, communication"}]},{"slug":"meishi-kokan-jiko-shokai","date":"2026-11-13","duration_sec":66,"category":"aisatsu-reigi","situation":{"jp":"名刺交換と自己紹介 ― 新しい担当が取引先と初めて挨拶する","vi":"Đổi danh thiếp và tự giới thiệu: nhân viên phụ trách mới chào hỏi khách hàng lần đầu","en":"Exchanging business cards and introducing yourself: a new account rep greets a client for the first time"},"dialogue":[{"speaker":"sales_male","jp":"初めまして、ABC商事、営業部の小林と申します。","vi":"Xin chào, tôi là Kobayashi, phòng Kinh doanh, công ty ABC Shoji.","en":"Nice to meet you, I'm Kobayashi from the Sales Department at ABC Shoji."},{"speaker":"client_male","jp":"あ、初めまして。中村です。こちらこそ、どうぞよろしく。","vi":"À, xin chào. Tôi là Nakamura. Tôi mới là người mong được giúp đỡ.","en":"Ah, nice to meet you. I'm Nakamura. The pleasure is mine."},{"speaker":"sales_male","jp":"本日はお時間をいただき、ありがとうございます。こちら、私の名刺です。","vi":"Cảm ơn ông đã dành thời gian hôm nay. Đây là danh thiếp của tôi.","en":"Thank you for your time today. Here is my business card."},{"speaker":"client_male","jp":"こちらこそ、どうぞ。私の名刺もお渡しします。","vi":"Tôi cũng vậy, mời ông nhận. Tôi cũng xin gửi danh thiếp của mình.","en":"Likewise, please take this. Here is my card as well."},{"speaker":"sales_male","jp":"あ、ありがとうございます。恐れ入ります。この度、御社の担当になりました。","vi":"À, cảm ơn ông. Thật ngại quá. Từ lần này, tôi sẽ phụ trách quý công ty.","en":"Ah, thank you very much. I'm much obliged. I've just become the person in charge of your company."},{"speaker":"client_male","jp":"そうですか。前任の山田さんから引き継ぎの話は伺っておりますよ。","vi":"Vậy à. Tôi đã nghe anh Yamada, người tiền nhiệm, kể về việc bàn giao rồi.","en":"I see. I've already heard about the handover from Mr. Yamada, your predecessor."},{"speaker":"sales_male","jp":"はい、山田さんからも詳しく伺っております。","vi":"Vâng, tôi cũng đã nghe anh Yamada kể chi tiết rồi ạ.","en":"Yes, Mr. Yamada has also briefed me in detail."},{"speaker":"client_male","jp":"いえいえ、こちらこそ、よろしくお願いします。さっそくですが、来週、打ち合わせをお願いできますか。","vi":"Không có gì, tôi mới là người mong được giúp đỡ. Nhân tiện, tuần tới chúng ta có thể họp được không?","en":"Not at all, the pleasure is mine. By the way, could we arrange a meeting next week?"},{"speaker":"sales_male","jp":"はい、もちろんです。日程はこちらからメールでご連絡いたします。","vi":"Vâng, tất nhiên rồi ạ. Tôi sẽ gửi email báo lịch cho ông.","en":"Yes, of course. I'll email you with the schedule."},{"speaker":"client_male","jp":"ええ、お願いします。では、今後とも、どうぞよろしく。","vi":"Vâng, nhờ ông nhé. Vậy thì, mong được hợp tác lâu dài.","en":"Yes, please do. Well then, I look forward to working with you."}],"vocabulary":[{"jp":"名刺","reading":"めいし","vi":"danh thiếp","en":"business card"},{"jp":"申す","reading":"もうす","vi":"nói (khiêm nhường)","en":"to say (humble)"},{"jp":"担当","reading":"たんとう","vi":"phụ trách","en":"person in charge"},{"jp":"引き継ぎ","reading":"ひきつぎ","vi":"bàn giao","en":"handover"},{"jp":"伺う","reading":"うかがう","vi":"nghe, hỏi (khiêm nhường)","en":"to hear, ask (humble)"},{"jp":"前任","reading":"ぜんにん","vi":"người tiền nhiệm","en":"predecessor"},{"jp":"打ち合わせ","reading":"うちあわせ","vi":"buổi họp, trao đổi","en":"meeting, discussion"},{"jp":"日程","reading":"にってい","vi":"lịch trình","en":"schedule"},{"jp":"恐れ入ります","reading":"おそれいります","vi":"thật ngại quá","en":"I'm much obliged"}]},{"slug":"gurafu-shiryo-no-setsumei","date":"2026-11-14","duration_sec":66,"category":"houkoku-renraku","situation":{"jp":"グラフ・資料の説明 ― 売上グラフを見ながら数字の変化を説明する","vi":"Giải thích biểu đồ và tài liệu: giải thích sự thay đổi của số liệu khi xem biểu đồ doanh số","en":"Explaining a graph and materials: describing changes in figures while looking at a sales graph"},"dialogue":[{"speaker":"staff_female","jp":"課長、4月の売上グラフをご覧いただけますか。","vi":"Trưởng phòng, anh xem giúp em biểu đồ doanh số tháng 4 được không ạ.","en":"Manager, could you take a look at April's sales graph?"},{"speaker":"manager_male","jp":"ああ、見せてくれ。…うん、4月は伸びているな。","vi":"Ừ, cho tôi xem nào. …Ừ, tháng 4 tăng thật đấy.","en":"Sure, show me. …Yes, April really is up."},{"speaker":"staff_female","jp":"はい、まず、新商品のお売上が前年比で15%増加しています。","vi":"Dạ, trước hết, doanh số sản phẩm mới đã tăng 15% so với cùng kỳ năm ngoái.","en":"Yes, first of all, new-product sales are up 15% year on year."},{"speaker":"manager_male","jp":"なるほど。でも、青い線は下がっているね。","vi":"Ra vậy. Nhưng đường màu xanh thì đang đi xuống đấy.","en":"I see. But the blue line is going down."},{"speaker":"staff_female","jp":"既存商品は前月比で8%減少しています。","vi":"Sản phẩm hiện có giảm 8% so với tháng trước.","en":"Existing products are down 8% month on month."},{"speaker":"manager_male","jp":"そうか。全体では、前年比でどれくらい増えたんだ？","vi":"Vậy à. Tính chung thì tăng bao nhiêu so với cùng kỳ năm ngoái?","en":"I see. Overall, how much is it up year on year?"},{"speaker":"staff_female","jp":"はい、この推移で、全体では前年比で12%増加しています。","vi":"Dạ, với đà này, tính chung tăng 12% so với cùng kỳ năm ngoái.","en":"Yes, at this rate, overall it is up 12% year on year."},{"speaker":"manager_male","jp":"うん、いい傾向だ。減少の要因もまとめてくれ。","vi":"Ừ, xu hướng tốt đấy. Ghi cả nguyên nhân giảm vào báo cáo nhé.","en":"Good trend. Put the reasons for the decline in the report too."},{"speaker":"staff_female","jp":"かしこまりました。割合の変化も資料に加えて、明日提出します。","vi":"Dạ vâng. Em sẽ thêm cả sự thay đổi về tỷ lệ vào tài liệu và nộp vào ngày mai.","en":"Certainly. I'll add the change in shares to the materials and submit them tomorrow."},{"speaker":"manager_male","jp":"よろしく頼むよ。数字の裏付けがあれば、説得力がある。","vi":"Nhờ cô nhé. Có số liệu làm căn cứ thì sẽ thuyết phục hơn.","en":"Thanks. With figures to back it up, it'll be more convincing."}],"vocabulary":[{"jp":"売上","reading":"うりあげ","vi":"doanh số","en":"sales"},{"jp":"グラフ","reading":"グラフ","vi":"biểu đồ","en":"graph"},{"jp":"前年比","reading":"ぜんねんひ","vi":"so cùng kỳ năm ngoái","en":"year-on-year"},{"jp":"増加","reading":"ぞうか","vi":"tăng","en":"increase"},{"jp":"減少","reading":"げんしょう","vi":"giảm","en":"decrease"},{"jp":"前月比","reading":"ぜんげつひ","vi":"so với tháng trước","en":"month-on-month"},{"jp":"要因","reading":"よういん","vi":"nguyên nhân","en":"factor, cause"},{"jp":"推移","reading":"すいい","vi":"đà diễn biến","en":"trend over time"},{"jp":"割合","reading":"わりあい","vi":"tỷ lệ","en":"proportion, share"}]},{"slug":"shuccho-hokoku","date":"2026-11-14","duration_sec":66,"category":"houkoku-renraku","situation":{"jp":"出張の報告 ― 大阪出張の結果と経費の報告","vi":"Báo cáo chuyến công tác: kết quả & chi phí chuyến đi Osaka","en":"Reporting on a business trip: results & expenses of the Osaka trip"},"dialogue":[{"speaker":"staff_male","jp":"部長、ただいま戻りました。大阪出張のご報告をさせていただけますでしょうか。","vi":"Trưởng phòng, em đã về rồi ạ. Em có thể báo cáo về chuyến công tác Osaka được không ạ?","en":"Manager, I'm back. May I report on the Osaka business trip?"},{"speaker":"manager_female","jp":"お疲れさま。で、どうだった？商談のほうは。","vi":"Vất vả cho em rồi. Thế nào, buổi thương lượng ra sao?","en":"Welcome back. So, how did it go? The negotiation?"},{"speaker":"staff_male","jp":"結論から先に申しますと、A社との商談は、ほぼまとまりました。","vi":"Nói kết luận trước thì buổi thương lượng với công ty A gần như đã xong ạ.","en":"To give the conclusion first, the negotiation with Company A is almost settled."},{"speaker":"manager_female","jp":"そうか。契約の見通しはどうだい。","vi":"Vậy à. Triển vọng ký hợp đồng thế nào?","en":"I see. What are the prospects for the contract?"},{"speaker":"staff_male","jp":"はい、来週中には契約書を交わせる見込みです。見積もりも、先方にご了承いただきました。","vi":"Dạ, trong tuần sau có thể trao đổi được hợp đồng ạ. Bên kia cũng đã đồng ý với bản báo giá rồi ạ.","en":"Yes, we expect to exchange the contract within next week. They've also approved the quotation."},{"speaker":"manager_female","jp":"よくやったね。で、宿泊と交通費のほうは？","vi":"Làm tốt lắm. Còn chỗ ở và chi phí đi lại thì sao?","en":"Well done. And what about the hotel and travel expenses?"},{"speaker":"staff_male","jp":"はい、領収書はこちらにまとめてあります。精算書は、明日までに提出いたします。","vi":"Dạ, hóa đơn em đã gom lại ở đây ạ. Bảng quyết toán thì ngày mai em sẽ nộp ạ.","en":"Yes, I've gathered all the receipts here. I'll submit the settlement form by tomorrow."},{"speaker":"manager_female","jp":"うん、ありがとう。あ、そうだ、取引先の反応はどうだった？","vi":"Ừ, cảm ơn em. À, mà phản ứng của đối tác thì sao?","en":"Thanks. Oh — how did the client react?"},{"speaker":"staff_male","jp":"ええ、新製品への関心が高くて、次回は本社での打ち合わせをご希望でした。","vi":"Dạ, họ rất quan tâm đến sản phẩm mới, và lần tới họ muốn họp ở trụ sở chính ạ.","en":"Yes, they're very interested in the new product, and next time they'd like to meet at their head office."},{"speaker":"manager_female","jp":"分かった。くわしいことはレポートにまとめておいてくれ。お疲れさま。","vi":"Được rồi. Ghi chi tiết vào báo cáo nhé. Vất vả cho em rồi.","en":"Understood. Put the details in the report. Good work."}],"vocabulary":[{"jp":"出張","reading":"しゅっちょう","vi":"công tác","en":"business trip"},{"jp":"商談","reading":"しょうだん","vi":"thương lượng, đàm phán","en":"business negotiation"},{"jp":"契約","reading":"けいやく","vi":"hợp đồng","en":"contract"},{"jp":"見積もり","reading":"みつもり","vi":"bản báo giá","en":"quotation, estimate"},{"jp":"宿泊","reading":"しゅくはく","vi":"lưu trú, ở lại","en":"lodging, stay"},{"jp":"交通費","reading":"こうつうひ","vi":"chi phí đi lại","en":"travel expenses"},{"jp":"精算","reading":"せいさん","vi":"quyết toán","en":"settlement"},{"jp":"領収書","reading":"りょうしゅうしょ","vi":"hóa đơn","en":"receipt"},{"jp":"取引先","reading":"とりひきさき","vi":"đối tác, khách hàng","en":"client, business partner"}]},{"slug":"kaigi-no-nittei-henko","date":"2026-11-14","duration_sec":66,"category":"kaigi-nittei","situation":{"jp":"会議の日程変更 ― 電話で会議の延期をお願いする","vi":"Đổi lịch họp qua điện thoại: xin dời buổi họp với khách hàng","en":"Rescheduling a meeting by phone: asking a client to postpone a meeting"},"dialogue":[{"speaker":"staff_female","jp":"お世話になっております。ABC商事の佐藤と申します。","vi":"Xin chào ạ. Tôi là Sato, bên ABC Shoji ạ.","en":"Hello. This is Sato from ABC Shoji."},{"speaker":"client_female","jp":"あ、佐藤さん。お世話になっております。","vi":"À, cô Sato. Xin chào ạ.","en":"Ah, Ms. Sato. Hello."},{"speaker":"staff_female","jp":"あの、明日の午後2時からの会議の件で、お電話いたしました。","vi":"Dạ, tôi gọi về buổi họp lúc 2 giờ chiều mai ạ.","en":"I'm calling about tomorrow's meeting at 2 p.m."},{"speaker":"client_female","jp":"はい、明日の会議ですね。何かございましたか。","vi":"Vâng, buổi họp ngày mai đúng không. Có chuyện gì vậy?","en":"Yes, tomorrow's meeting. What is it about?"},{"speaker":"staff_female","jp":"はい、申し訳ございません。急な出張が入りまして、日程の変更をお願いできますでしょうか。","vi":"Dạ, tôi vô cùng xin lỗi. Đột nhiên có chuyến công tác nên tôi có thể xin đổi lịch được không ạ?","en":"Yes, I'm very sorry. An urgent business trip has come up, so may I ask to change the schedule?"},{"speaker":"client_female","jp":"ああ、そうですか。延期です。","vi":"À, ra vậy. Dời lại đúng không?","en":"Ah, I see. A postponement, then."},{"speaker":"staff_female","jp":"はい、木曜日の午前10時はいかがでしょうか。","vi":"Dạ, 10 giờ sáng thứ Năm thì sao ạ?","en":"How about Thursday at 10 a.m.?"},{"speaker":"client_female","jp":"木曜日の午前10時ですね。ええ、都合は大丈夫です。","vi":"10 giờ sáng thứ Năm đúng không. Vâng, giờ đó thì tiện ạ.","en":"Thursday at 10 a.m. Yes, that time suits me."},{"speaker":"staff_female","jp":"ありがとうございます。参加者にも確認して、メールでご連絡いたします。","vi":"Cảm ơn chị. Tôi sẽ xác nhận với những người tham gia rồi liên lạc lại qua email ạ.","en":"Thank you. I'll confirm with the participants and follow up by email."},{"speaker":"client_female","jp":"ええ、よろしくお願いします。では、木曜日にお会いしましょう。","vi":"Vâng, nhờ cô nhé. Vậy hẹn gặp nhau thứ Năm nhé.","en":"Yes, please do. Then, see you on Thursday."}],"vocabulary":[{"jp":"日程","reading":"にってい","vi":"lịch trình","en":"schedule"},{"jp":"変更","reading":"へんこう","vi":"thay đổi","en":"change"},{"jp":"延期","reading":"えんき","vi":"dời lại","en":"postponement"},{"jp":"会議","reading":"かいぎ","vi":"buổi họp","en":"meeting"},{"jp":"出張","reading":"しゅっちょう","vi":"công tác","en":"business trip"},{"jp":"都合","reading":"つごう","vi":"tiện, lịch trống","en":"availability"},{"jp":"確認","reading":"かくにん","vi":"xác nhận","en":"confirmation"},{"jp":"参加者","reading":"さんかしゃ","vi":"người tham gia","en":"participant"},{"jp":"連絡","reading":"れんらく","vi":"liên lạc","en":"contact"}]},{"slug":"kangeikai-no-aisatsu","date":"2026-11-15","duration_sec":66,"category":"aisatsu-reigi","situation":{"jp":"歓迎会の挨拶 ― 新入社員の歓迎会で乾杯の挨拶をする","vi":"Lời chào ở tiệc chào đón: chúc mừng nhân viên mới","en":"Welcome-party greeting: a toast for a new employee"},"dialogue":[{"speaker":"manager_male","jp":"皆さん、山田さんの歓迎会にお集まりいただき、ありがとうございます。","vi":"Cảm ơn mọi người đã đến dự buổi tiệc chào đón Yamada hôm nay.","en":"Thank you all for gathering for Ms. Yamada's welcome party."},{"speaker":"new_employee_female","jp":"ありがとうございます。皆さんにお会いできて、とてもうれしいです。","vi":"Cảm ơn mọi người. Được gặp mọi người, tôi rất vui.","en":"Thank you. I'm so happy to meet you all."},{"speaker":"manager_male","jp":"新入社員の山田さんは、今月から営業部に配属されました。","vi":"Yamada, nhân viên mới, từ tháng này được phân công về phòng Kinh doanh.","en":"Ms. Yamada, our new employee, has been assigned to the Sales Department this month."},{"speaker":"new_employee_female","jp":"はい、まだ分からないことも多いですが、一生懸命頑張ります。","vi":"Dạ, vẫn còn nhiều điều em chưa biết, nhưng em sẽ cố gắng hết sức.","en":"Yes, there's still a lot I don't know, but I'll do my very best."},{"speaker":"manager_male","jp":"期待していますよ。分からないことがあれば、先輩に遠慮なく聞いてください。","vi":"Mọi người đang kỳ vọng ở em đấy. Có gì không hiểu thì cứ hỏi các anh chị đi trước, đừng ngại nhé.","en":"We're counting on you. If there's anything you don't understand, don't hesitate to ask your seniors."},{"speaker":"new_employee_female","jp":"はい、ありがとうございます。精いっぱい努力…","vi":"Dạ, cảm ơn anh. Em sẽ nỗ lực hết mình…","en":"Yes, thank you. I'll give it my all…"},{"speaker":"manager_male","jp":"では、音頭を取らせていただきます。皆さん、グラスをどうぞ。山田さんの新しいスタートに、乾杯！","vi":"Vậy thì, để tôi xin phép hô lời chúc mừng. Mọi người, xin mời nâng ly. Chúc cho khởi đầu mới của Yamada — cạn ly!","en":"Now, allow me to propose the toast. Everyone, please raise your glasses. To Ms. Yamada's fresh start — cheers!"},{"speaker":"new_employee_female","jp":"本当にありがとうございます。","vi":"Cảm ơn mọi người rất nhiều.","en":"Thank you so much."},{"speaker":"manager_male","jp":"山田さんの挨拶、すてきでしたね。これからも、同僚としてよろしくお願いします。","vi":"Lời chào của Yamada hay lắm. Từ nay chúng ta cùng làm việc với nhau nhé.","en":"Ms. Yamada, your speech was lovely. Let's keep working together as colleagues."},{"speaker":"new_employee_female","jp":"はい、こちらこそ、よろしくお願いいたします。","vi":"Dạ, mong mọi người giúp đỡ ạ.","en":"Yes, I look forward to working with you all."}],"vocabulary":[{"jp":"歓迎会","reading":"かんげいかい","vi":"buổi tiệc chào đón","en":"welcome party"},{"jp":"乾杯","reading":"かんぱい","vi":"cạn ly, chúc mừng","en":"toast; cheers"},{"jp":"新入社員","reading":"しんにゅうしゃいん","vi":"nhân viên mới","en":"new employee"},{"jp":"配属","reading":"はいぞく","vi":"phân công về phòng","en":"assignment"},{"jp":"挨拶","reading":"あいさつ","vi":"lời chào, phát biểu","en":"greeting; speech"},{"jp":"期待","reading":"きたい","vi":"sự kỳ vọng","en":"expectation"},{"jp":"同僚","reading":"どうりょう","vi":"đồng nghiệp","en":"colleague"},{"jp":"頑張る","reading":"がんばる","vi":"cố gắng hết sức","en":"to do one's best"},{"jp":"音頭","reading":"おんど","vi":"lời hô chúc mừng","en":"leading a toast"}]},{"slug":"hisashiburi-no-aisatsu","date":"2026-11-15","duration_sec":66,"category":"aisatsu-reigi","situation":{"jp":"久しぶりに会った時の挨拶 ― 海外赴任から帰任した同僚との再会","vi":"Lâu ngày gặp lại: đồng nghiệp trở về sau khi đi công tác nước ngoài","en":"Meeting after a long time: reuniting with a colleague back from an overseas assignment"},"dialogue":[{"speaker":"senpai_female","jp":"佐藤さん、お久しぶりですね。ご無沙汰しております。","vi":"À, cô Sato! Lâu rồi không gặp. Tôi đã lâu không liên lạc, xin lỗi nhé.","en":"Ah, Ms. Sato! It's been a while. Sorry I haven't been in touch."},{"speaker":"staff_female","jp":"田中さん、ご無沙汰しております。お久しぶりです。お元気でしたか。","vi":"Chị Tanaka, em cũng đã lâu không liên lạc. Lâu rồi không gặp. Chị vẫn khỏe chứ ạ?","en":"Ms. Tanaka, sorry I haven't been in touch either. It's been a while. Have you been well?"},{"speaker":"senpai_female","jp":"おかげさまで。佐藤さんこそ、海外赴任から帰任されたんですよね。","vi":"Vâng, nhờ trời vẫn khỏe. Còn cô mới là người vừa trở về sau khi đi công tác nước ngoài đúng không?","en":"Yes, thanks to you I'm fine. You're the one who just returned from your overseas assignment, right?"},{"speaker":"staff_female","jp":"先週帰任しました。三年ぶりの本社です。部署も変わって、営業部になりました。","vi":"Tuần trước em vừa trở về. Đây là lần đầu quay lại trụ sở sau ba năm. Phòng ban cũng đổi, giờ em ở phòng Kinh doanh ạ.","en":"I returned last week. It's my first time back at head office in three years. My department changed too — I'm in Sales now."},{"speaker":"senpai_female","jp":"そうなんですか。異動先の営業部は、いかがですか。お仕事のほうは。","vi":"Vậy à. Phòng Kinh doanh nơi cô chuyển đến thì sao? Công việc thế nào?","en":"Is that so? How is the Sales Department you transferred to? How's the work?"},{"speaker":"staff_female","jp":"まだ慣れなくて、毎日覚えることが多くて大変です。でも…","vi":"Em vẫn chưa quen, mỗi ngày có nhiều thứ phải nhớ nên vất vả lắm. Nhưng…","en":"I'm still getting used to it — there's so much to learn every day, it's tough. But…"},{"speaker":"senpai_female","jp":"あ、それはよかった。相変わらず、忙しそうですね。近況を聞かせてください。","vi":"À, vậy thì tốt quá. Cô vẫn bận rộn như xưa nhỉ. Kể cho tôi nghe tình hình gần đây đi.","en":"Ah, that's good to hear. You're as busy as ever, I see. Tell me how things have been."},{"speaker":"staff_female","jp":"ぜひ、今度、ランチでも…","vi":"Vâng, nhất định ạ. Hôm nào mình đi ăn trưa cùng nhau nhé…","en":"Yes, I'd love to. Shall we have lunch together sometime…"},{"speaker":"senpai_female","jp":"いいですね。来週の水曜日はいかがですか。お昼、空いております。","vi":"Được đấy. Thứ Tư tuần sau thì sao? Buổi trưa tôi rảnh ạ.","en":"That sounds good. How about next Wednesday? I'm free at lunch."},{"speaker":"staff_female","jp":"はい、水曜日でお願いします。連絡先は変わっていませんので…","vi":"Vâng, vậy thứ Tư nhé. Số liên lạc của em không đổi nên…","en":"Yes, Wednesday it is. My contact details haven't changed, so…"}],"vocabulary":[{"jp":"久しぶり","reading":"ひさしぶり","vi":"lâu rồi không gặp","en":"after a long time"},{"jp":"ご無沙汰","reading":"ごぶさた","vi":"lâu không liên lạc","en":"long silence"},{"jp":"赴任","reading":"ふにん","vi":"đi nhận nhiệm sở","en":"overseas assignment"},{"jp":"帰任","reading":"きにん","vi":"trở về sau nhiệm sở","en":"return from assignment"},{"jp":"異動","reading":"いどう","vi":"chuyển công tác","en":"transfer"},{"jp":"部署","reading":"ぶしょ","vi":"phòng ban","en":"department"},{"jp":"相変わらず","reading":"あいかわらず","vi":"vẫn như xưa","en":"as always"},{"jp":"おかげさまで","reading":"おかげさまで","vi":"nhờ trời / nhờ mọi người","en":"thanks to you"},{"jp":"近況","reading":"きんきょう","vi":"tình hình gần đây","en":"recent situation"}]},{"slug":"denwa-dengon-wo-nokosu","date":"2026-11-15","duration_sec":66,"category":"denwa","situation":{"jp":"電話で伝言を残す ― 担当者が外出中で、留守番電話に伝言を残す","vi":"Để lại lời nhắn qua điện thoại: người phụ trách đi vắng, để lại lời nhắn vào máy trả lời tự động","en":"Leaving a phone message: the person in charge is out, leave a message on the answering machine"},"dialogue":[{"speaker":"sales_male","jp":"お世話になっております。ABC商事の小林と申します。田中課長をお願いいたします。","vi":"Xin chào ạ. Tôi là Kobayashi bên ABC Shoji. Tôi có thể gặp trưởng phòng Tanaka được không ạ?","en":"Hello. This is Kobayashi from ABC Shoji. May I speak with Manager Tanaka, please?"},{"speaker":"reception_male","jp":"あ、お世話になっております。あいにく田中は外出中でございます。","vi":"À, xin chào ạ. Tiếc là anh Tanaka hiện đang ra ngoài ạ.","en":"Ah, hello. Unfortunately, Mr. Tanaka is currently out of the office."},{"speaker":"sales_male","jp":"はい、そうですか。では、留守番電話に伝言を残させていただきます。","vi":"Ra vậy. Vậy tôi xin để lại lời nhắn qua máy trả lời tự động ạ.","en":"I see. In that case, may I leave a message on the answering machine?"},{"speaker":"reception_male","jp":"はい、承知いたしました。ご用件を伺ってもよろしいでしょうか。","vi":"Dạ vâng. Tôi có thể hỏi nội dung lời nhắn được không ạ?","en":"Yes, certainly. May I ask what your message is about?"},{"speaker":"sales_male","jp":"はい、明日の納期の件なんですが、数量を50個から80個に変更したいんです。","vi":"Dạ, về hạn giao hàng ngày mai, tôi muốn đổi số lượng từ 50 lên 80 cái ạ.","en":"Yes, it's about tomorrow's delivery deadline — I'd like to change the quantity from 50 to 80 units."},{"speaker":"reception_male","jp":"80個ですね。確認いたしました。ほかにございますか。","vi":"80 cái đúng không ạ. Tôi đã xác nhận. Còn gì nữa không ạ?","en":"80 units, noted. I've confirmed it. Is there anything else?"},{"speaker":"sales_male","jp":"あ、それから、折り返しのご連絡を、今日の5時までにお願いできますか。","vi":"À, ngoài ra, anh có thể gọi lại cho tôi trước 5 giờ chiều nay được không ạ?","en":"Ah, also, could I ask for a callback by 5 p.m. today?"},{"speaker":"reception_male","jp":"はい、確かにお伝えします。連絡先を伺ってもよろしいでしょうか。","vi":"Dạ, tôi sẽ chuyển lời chắc chắn ạ. Anh cho tôi xin số liên lạc được không ạ?","en":"Yes, I'll make sure to pass that on. May I have your contact number?"},{"speaker":"sales_male","jp":"はい、090の1234の5678でございます。よろしくお願いいたします。","vi":"Dạ, số của tôi là 090-1234-5678 ạ. Nhờ anh giúp ạ.","en":"Yes, it's 090-1234-5678. Thank you."},{"speaker":"reception_male","jp":"はい、承知いたしました。田中が戻りましたら、すぐお伝えします。","vi":"Dạ vâng. Khi anh Tanaka quay lại tôi sẽ chuyển lời ngay ạ.","en":"Yes, understood. I'll pass it on as soon as Mr. Tanaka returns."}],"vocabulary":[{"jp":"伝言","reading":"でんごん","vi":"lời nhắn","en":"message"},{"jp":"留守番電話","reading":"るすばんでんわ","vi":"máy trả lời tự động","en":"answering machine"},{"jp":"外出中","reading":"がいしゅつちゅう","vi":"đang ra ngoài","en":"out of the office"},{"jp":"折り返し","reading":"おりかえし","vi":"gọi lại","en":"callback"},{"jp":"連絡先","reading":"れんらくさき","vi":"số liên lạc","en":"contact number"},{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery deadline"},{"jp":"数量","reading":"すうりょう","vi":"số lượng","en":"quantity"},{"jp":"変更","reading":"へんこう","vi":"thay đổi","en":"change"},{"jp":"確認","reading":"かくにん","vi":"xác nhận","en":"confirmation"}]},{"slug":"nenmatsu-nenshi-no-aisatsu","date":"2026-11-16","duration_sec":66,"category":"aisatsu-reigi","situation":{"jp":"年末年始の挨拶 ― 営業担当が取引先を訪ね、年末の挨拶とお歳暮を渡し、年始の挨拶回りの日程を決める","vi":"Chào cuối năm • đầu năm: nhân viên kinh doanh đến chào khách hàng cuối năm, tặng quà và hẹn lịch chào năm mới","en":"Year-end & New Year greetings: a sales rep visits a client with a year-end gift and fixes the New Year greeting round"},"dialogue":[{"speaker":"sales_suzuki_female","jp":"お忙しいところ、失礼します。年末のご挨拶に参りました。","vi":"Xin lỗi đã làm phiền lúc anh đang bận. Tôi đến chào cuối năm ạ.","en":"Sorry to disturb you while you're busy. I've come for the year-end greeting."},{"speaker":"manager_takahashi_male","jp":"鈴木さん、わざわざありがとう。どうぞ、おかけください。","vi":"Cô Suzuki, cảm ơn cô đã cất công đến. Mời cô ngồi.","en":"Ms. Suzuki, thank you for coming all this way. Please, have a seat."},{"speaker":"sales_suzuki_female","jp":"今年もお世話になりました。こちら、お歳暮です。","vi":"Năm nay cảm ơn anh đã giúp đỡ nhiều. Đây là quà cuối năm ạ.","en":"Thank you for all your help this year. This is a year-end gift."},{"speaker":"manager_takahashi_male","jp":"お気遣いなく。いつもありがとうございます。","vi":"Cô khách sáo quá. Lúc nào cũng cảm ơn cô.","en":"You shouldn't have. Thank you, as always."},{"speaker":"sales_suzuki_female","jp":"年始の挨拶回りは、十日の午前に参ります。","vi":"Đầu năm, tôi sẽ đến chào năm mới vào sáng ngày mùng 10 ạ.","en":"For the New Year greeting round, I'll come on the morning of the 10th."},{"speaker":"manager_takahashi_male","jp":"ああ、十日ですね。休暇明けですが、大丈夫ですよ。","vi":"À, ngày mùng 10. Vừa hết kỳ nghỉ nhưng được ạ.","en":"Ah, the 10th. We're just back from the holiday, but that's fine."},{"speaker":"sales_suzuki_female","jp":"では、十日の十時に伺います。よろしいでしょうか。","vi":"Vậy tôi sẽ đến lúc 10 giờ ngày mùng 10, được không ạ?","en":"Then I'll come at 10 a.m. on the 10th. Is that all right?"},{"speaker":"manager_takahashi_male","jp":"ぜひ、来年もよろしくお願いします。","vi":"Ừ, mời cô. Năm sau cũng mong được cô giúp đỡ.","en":"Yes, please do. I look forward to working with you next year too."},{"speaker":"sales_suzuki_female","jp":"はい、よいお年をお迎えください。","vi":"Vâng, chúc anh đón năm mới an lành.","en":"Yes, I wish you a happy New Year."},{"speaker":"manager_takahashi_male","jp":"鈴木さんも、よいお年を。","vi":"Cô Suzuki cũng vậy, chúc cô năm mới tốt lành.","en":"You too, Ms. Suzuki — have a good New Year."}],"vocabulary":[{"jp":"年末","reading":"ねんまつ","vi":"cuối năm","en":"year-end"},{"jp":"年始","reading":"ねんし","vi":"đầu năm","en":"New Year"},{"jp":"お歳暮","reading":"おせいぼ","vi":"quà cuối năm","en":"year-end gift"},{"jp":"お世話になる","reading":"おせわになる","vi":"được giúp đỡ","en":"to receive help"},{"jp":"挨拶回り","reading":"あいさつまわり","vi":"đi chào hỏi đầu năm","en":"greeting rounds"},{"jp":"よいお年を","reading":"よいおとしを","vi":"chúc năm mới tốt lành","en":"have a good New Year"},{"jp":"休暇","reading":"きゅうか","vi":"kỳ nghỉ","en":"holiday"},{"jp":"ご挨拶","reading":"ごあいさつ","vi":"lời chào hỏi","en":"greeting"},{"jp":"参る","reading":"まいる","vi":"đến (khiêm nhường)","en":"to come (humble)"}]},{"slug":"denwa-ga-natta-toki-no-taiou","date":"2026-11-16","duration_sec":66,"category":"denwa","situation":{"jp":"電話が鳴った時の対応","vi":"Nghe máy & xưng tên công ty","en":"Answering the phone — when it rings"},"dialogue":[{"speaker":"staff_sato_female","jp":"はい、山田商事、営業部の佐藤でございます。","vi":"A-lô, tôi là Sato, phòng Kinh doanh, công ty Yamada Shoji ạ.","en":"Hello, this is Sato from the Sales Department at Yamada Shoji."},{"speaker":"client_kobayashi_male","jp":"お世話になっております。A社の小林と申します。","vi":"Xin chào, tôi là Kobayashi, công ty A ạ.","en":"Hello, this is Kobayashi from Company A."},{"speaker":"staff_sato_female","jp":"小林様、いつもお世話になっております。","vi":"Anh Kobayashi, lúc nào cũng cảm ơn anh đã giúp đỡ ạ.","en":"Mr. Kobayashi, thank you for your continued support."},{"speaker":"client_kobayashi_male","jp":"田中課長はいらっしゃいますか。","vi":"Trưởng phòng Tanaka có ở đó không ạ?","en":"Is Manager Tanaka in?"},{"speaker":"staff_sato_female","jp":"申し訳ございません。課長はただいま不在です。","vi":"Xin lỗi anh. Trưởng phòng hiện đang vắng mặt ạ.","en":"I'm sorry. The manager is currently out of the office."},{"speaker":"client_kobayashi_male","jp":"そうですか。では、担当の方に伝言をお願いできますか。","vi":"Ra vậy. Vậy tôi có thể nhờ nhắn lại với người phụ trách không?","en":"I see. Then, could I leave a message with the person in charge?"},{"speaker":"staff_sato_female","jp":"はい、承知いたしました。課長に伝言を取り次ぎます。","vi":"Dạ vâng. Tôi sẽ chuyển lời nhắn cho trưởng phòng ạ.","en":"Yes, certainly. I'll pass the message on to the manager."},{"speaker":"client_kobayashi_male","jp":"ええ、来週の納品を少し早めていただきたいのですが。","vi":"Vâng, tôi muốn đơn hàng tuần sau được giao sớm hơn một chút.","en":"Yes — I'd like next week's delivery to be brought forward a little."},{"speaker":"staff_sato_female","jp":"承知いたしました。内容を確認して、折り返しご連絡いたします。","vi":"Dạ vâng. Tôi sẽ kiểm tra nội dung rồi gọi lại ngay khi trưởng phòng về ạ.","en":"Understood. I'll check the details and call you back as soon as he returns."},{"speaker":"client_kobayashi_male","jp":"ありがとうございます。よろしくお願いいたします。","vi":"Cảm ơn cô nhiều. Nhờ cô giúp nhé.","en":"Thank you very much. I appreciate it."}],"vocabulary":[{"jp":"お世話になる","reading":"おせわになる","vi":"được giúp đỡ","en":"to be in one's care"},{"jp":"来週","reading":"らいしゅう","vi":"tuần sau","en":"next week"},{"jp":"納品","reading":"のうひん","vi":"giao hàng","en":"delivery of goods"},{"jp":"担当","reading":"たんとう","vi":"phụ trách","en":"in charge"},{"jp":"不在","reading":"ふざい","vi":"vắng mặt","en":"absent"},{"jp":"伝言","reading":"でんごん","vi":"lời nhắn","en":"message"},{"jp":"取り次ぐ","reading":"とりつぐ","vi":"chuyển lời","en":"to pass on"},{"jp":"折り返し","reading":"おりかえし","vi":"gọi lại","en":"callback"},{"jp":"確認する","reading":"かくにんする","vi":"xác nhận","en":"to confirm"}]},{"slug":"honnin-ni-kawatte-outai","date":"2026-11-16","duration_sec":66,"category":"denwa","situation":{"jp":"本人にかわって応対する ― 担当者不在の電話に代わって応対し、伝言を承る","vi":"Nghe hộ điện thoại cho đồng nghiệp vắng mặt: nhận thay và ghi lại lời nhắn","en":"Answering the phone on a colleague's behalf: taking over and taking a message when the person is out"},"dialogue":[{"speaker":"client_female","jp":"はい、お世話になっております。AC自動車の鈴木と申します。田中課長をお願いできますでしょうか。","vi":"Xin chào, tôi là Suzuki, công ty AC Jidosha. Tôi muốn gặp trưởng phòng Tanaka ạ.","en":"Hello, this is Suzuki from AC Motors. May I speak with Manager Tanaka, please?"},{"speaker":"staff_male","jp":"はい、山田商事でございます。","vi":"Vâng, công ty Yamada Shoji xin nghe.","en":"Hello, this is Yamada Shoji."},{"speaker":"client_female","jp":"そうですか。何時ごろお戻りになりますか。","vi":"Ra vậy. Khoảng mấy giờ anh ấy quay lại ạ?","en":"I see. Around what time will he be back?"},{"speaker":"staff_male","jp":"ええ、夕方4時ごろ戻る予定です。申しわけございません。","vi":"Dạ, anh ấy dự kiến quay lại vào khoảng 4 giờ chiều. Xin lỗi chị.","en":"He is expected back around 4 p.m. I sincerely apologize."},{"speaker":"client_female","jp":"じゃあ、お戻りになりましたら、お電話いただけますでしょうか。","vi":"Vậy khi anh ấy về, anh có thể nhờ anh ấy gọi lại cho tôi được không ạ?","en":"Then, when he returns, could you ask him to call me back?"},{"speaker":"staff_male","jp":"はい、承知いたしました。田中のかわりに承ります。","vi":"Dạ vâng. Tôi sẽ nhận thay anh Tanaka ạ.","en":"Yes, certainly. I'll take this on Mr. Tanaka's behalf."},{"speaker":"client_female","jp":"ありがとうございます。明日の打ち合わせの時間を変更したいのですが。","vi":"Cảm ơn anh. Tôi muốn đổi giờ họp ngày mai ạ.","en":"Thank you. I'd like to change the time of tomorrow's meeting."},{"speaker":"staff_male","jp":"かしこまりました。伝言をお預かりします。何時がよろしいでしょうか。","vi":"Dạ vâng. Tôi sẽ ghi lại lời nhắn. Mấy giờ thì tiện cho chị ạ?","en":"Certainly. I'll take the message. What time would suit you?"},{"speaker":"client_female","jp":"ええ、午後2時から3時にお願いできますか。","vi":"Vâng, nhờ anh đổi sang 2 đến 3 giờ chiều được không ạ?","en":"Yes — could you change it to 2 to 3 p.m., please?"},{"speaker":"staff_male","jp":"承知いたしました。田中から折り返しお電話させていただきます。","vi":"Dạ vâng. Anh Tanaka sẽ gọi lại cho chị ạ.","en":"Understood. Mr. Tanaka will call you back."}],"vocabulary":[{"jp":"お世話になる","reading":"おせわになる","vi":"được giúp đỡ","en":"to be in one's care"},{"jp":"代わる","reading":"かわる","vi":"thay mặt, nhận thay","en":"to act on behalf of"},{"jp":"戻る","reading":"もどる","vi":"quay lại","en":"to return"},{"jp":"予定","reading":"よてい","vi":"dự kiến","en":"scheduled"},{"jp":"申しわけありません","reading":"もうしわけありません","vi":"xin lỗi","en":"I sincerely apologize"},{"jp":"承知する","reading":"しょうちする","vi":"vâng, đã rõ","en":"to understand, to accept"},{"jp":"打ち合わせ","reading":"うちあわせ","vi":"buổi họp","en":"meeting"},{"jp":"伝言","reading":"でんごん","vi":"lời nhắn","en":"message"},{"jp":"折り返し","reading":"おりかえし","vi":"gọi lại","en":"callback"}]},{"slug":"aite-no-koe-ya-namae-ga-hakkiri-shinai","date":"2026-11-17","duration_sec":66,"category":"denwa","situation":{"jp":"相手の声や名前がはっきりしない","vi":"Nghe không rõ tên người gọi","en":"When you can't hear the caller's name clearly"},"dialogue":[{"speaker":"client_hamamoto_female","jp":"もしもし、お世話になっております。浜本と申します。","vi":"A-lô, xin chào, tôi là Hamamoto ạ.","en":"Hello, this is Hamamoto speaking."},{"speaker":"staff_aoki_female","jp":"はい、山田商事でございます。お電話が遠いようなんですが。","vi":"Vâng, công ty Yamada Shoji xin nghe. Hình như điện thoại hơi khó nghe ạ.","en":"Hello, this is Yamada Shoji. Your voice sounds a little faint, I'm afraid."},{"speaker":"client_hamamoto_female","jp":"あ、すみません。駅からかけておりまして、まわりがうるさくて聞き取りにくいんです。","vi":"À, xin lỗi chị. Tôi đang gọi từ ga nên xung quanh ồn quá, khó nghe rõ.","en":"Oh, I'm sorry. I'm calling from the station, and it's noisy around me, so it's hard to hear clearly."},{"speaker":"staff_aoki_female","jp":"ええ、山本様でいらっしゃいますか。","vi":"Vâng, chị là Yamamoto phải không ạ?","en":"I see — are you Ms. Yamamoto?"},{"speaker":"client_hamamoto_female","jp":"いいえ、浜本です。はまもと、と申します。","vi":"Không ạ, tôi là Hamamoto. Hamamoto ạ.","en":"No, I'm Hamamoto. Ha-ma-mo-to."},{"speaker":"staff_aoki_female","jp":"あ、失礼いたしました。浜本様ですね。スペルでお願いできますか。","vi":"À, xin lỗi chị. Chị là Hamamoto phải không ạ. Chị đánh vần giúp tôi được không ạ?","en":"Oh, I apologize. Ms. Hamamoto, then. Could you spell it for me, please?"},{"speaker":"client_hamamoto_female","jp":"はい、「は」は「花」の「は」、「ま」は「松」の「ま」です。","vi":"Vâng, chữ \"ha\" là \"ha\" trong \"hana\" (hoa), chữ \"ma\" là \"ma\" trong \"matsu\" (thông) ạ.","en":"Yes — \"ha\" as in \"hana\" (flower), \"ma\" as in \"matsu\" (pine)."},{"speaker":"staff_aoki_female","jp":"浜本様ですね。かしこまりました。ご用件をお伺いできますか。","vi":"Chị Hamamoto phải không ạ. Tôi đã rõ. Tôi có thể hỏi chị cần gì được không ạ?","en":"Ms. Hamamoto, understood. May I ask what this is regarding?"},{"speaker":"client_hamamoto_female","jp":"ええ、明日の打ち合わせの時間を確認したいのですが。","vi":"Vâng, tôi muốn xác nhận giờ họp ngày mai ạ.","en":"Yes — I'd like to confirm the time of tomorrow's meeting."},{"speaker":"staff_aoki_female","jp":"はい、午後2時からでございます。お気をつけてお越しください。","vi":"Vâng, bắt đầu từ 2 giờ chiều ạ. Chị đi đường cẩn thận nhé.","en":"Yes, it starts at 2 p.m. Please take care on your way here."}],"vocabulary":[{"jp":"お世話になる","reading":"おせわになる","vi":"được giúp đỡ","en":"to be in one's care"},{"jp":"遠い","reading":"とおい","vi":"xa, khó nghe (điện thoại)","en":"distant, faint"},{"jp":"聞き取る","reading":"ききとる","vi":"nghe rõ","en":"to catch (what is said)"},{"jp":"まわり","reading":"まわり","vi":"xung quanh","en":"surroundings"},{"jp":"失礼する","reading":"しつれいする","vi":"xin lỗi, thất lễ","en":"to apologize"},{"jp":"スペル","reading":"スペル","vi":"cách đánh vần","en":"spelling"},{"jp":"伺う","reading":"うかがう","vi":"hỏi (kính ngữ)","en":"to ask (humbly)"},{"jp":"確認する","reading":"かくにんする","vi":"xác nhận","en":"to confirm"},{"jp":"打ち合わせ","reading":"うちあわせ","vi":"buổi họp","en":"meeting"}]},{"slug":"kyoka-shinai","date":"2026-11-17","duration_sec":66,"category":"shinsei-kyoka","situation":{"jp":"許可しない ― 早退の許可を求める","vi":"Từ chối cho phép: xin về sớm","en":"Denying permission: asking to leave early"},"dialogue":[{"speaker":"staff_nakamura_female","jp":"課長、すみません。今日、早退の許可をいただけないでしょうか。","vi":"Trưởng phòng, xin lỗi anh. Hôm nay em có thể xin phép về sớm được không ạ?","en":"Manager, excuse me. May I have permission to leave early today?"},{"speaker":"manager_takahashi_male","jp":"早退？どうしたんだ。何かあったのか。","vi":"Về sớm à? Có chuyện gì vậy? Có việc gì à?","en":"Leave early? What's wrong? Did something happen?"},{"speaker":"staff_nakamura_female","jp":"はい、実は、ちょっと用事ができてしまいまして。","vi":"Dạ, thực ra em đột nhiên có việc riêng ạ.","en":"Yes, actually, something personal suddenly came up."},{"speaker":"manager_takahashi_male","jp":"ああ、でも今日は棚卸の日だろう。無理だよ。","vi":"À, nhưng hôm nay là ngày kiểm kê mà. Không được đâu.","en":"Ah, but today is inventory day. That's not possible."},{"speaker":"staff_nakamura_female","jp":"そうですか……。やっぱり、無理でしょうか。","vi":"Vậy sao ạ… Quả nhiên là không được phải không ạ.","en":"I see… So it really isn't possible, is it?"},{"speaker":"manager_takahashi_male","jp":"ああ、悪いな。明日は提案書の締め切りなんだ。","vi":"Ừ, xin lỗi nhé. Ngày mai là hạn chót nộp bản đề xuất mà.","en":"Yeah, sorry. Tomorrow is the deadline for the proposal."},{"speaker":"staff_nakamura_female","jp":"そうですか。わかりました。じゃあ、今回はあきらめます。","vi":"Vâng ạ. Em hiểu rồi. Vậy lần này em đành chịu vậy.","en":"I understand. Well, I'll give up on it this time."},{"speaker":"manager_takahashi_male","jp":"ただ、書類を仕上げれば、4時ごろには帰れるよ。","vi":"Nhưng mà, nếu làm xong tài liệu thì khoảng 4 giờ em có thể về được đấy.","en":"But if you finish the documents, you can leave around 4."},{"speaker":"staff_nakamura_female","jp":"あ、本当ですか。じゃあ、根本さんに手伝ってもらいます。","vi":"À, thật ạ? Vậy em sẽ nhờ anh Nemoto giúp ạ.","en":"Oh, really? Then I'll ask Mr. Nemoto to help me."},{"speaker":"manager_takahashi_male","jp":"ああ、僕からも声をかけておくよ。よろしく頼むよ。","vi":"Ừ, anh cũng sẽ nói với cậu ấy một tiếng. Nhờ em nhé.","en":"Yes, I'll have a word with him too. I'm counting on you."}],"vocabulary":[{"jp":"早退","reading":"そうたい","vi":"về sớm","en":"leaving early"},{"jp":"許可","reading":"きょか","vi":"sự cho phép","en":"permission"},{"jp":"用事","reading":"ようじ","vi":"việc riêng, việc bận","en":"personal matter"},{"jp":"棚卸","reading":"たなおろし","vi":"kiểm kê","en":"inventory count"},{"jp":"提案書","reading":"ていあんしょ","vi":"bản đề xuất","en":"proposal document"},{"jp":"締め切り","reading":"しめきり","vi":"hạn chót","en":"deadline"},{"jp":"手伝う","reading":"てつだう","vi":"giúp đỡ","en":"to help"},{"jp":"仕上げる","reading":"しあげる","vi":"hoàn thành, làm xong","en":"to finish (work)"},{"jp":"あきらめる","reading":"あきらめる","vi":"đành chịu, từ bỏ","en":"to give up"}]},{"slug":"moshideru","date":"2026-11-17","duration_sec":66,"category":"shinsei-kyoka","situation":{"en":"Offering to help: volunteering to take over work","jp":"申し出る ― 手伝いを申し出る","vi":"Chủ động đề nghị giúp đỡ"},"dialogue":[{"speaker":"tanaka","jp":"課長、お疲れさまです。お手伝いを申し出ても、いいでしょうか。","vi":"Trưởng phòng, anh vất vả rồi. Em có thể xin phép giúp anh một tay không ạ?","en":"Manager, good work today. May I offer to help you?"},{"speaker":"yamamoto","jp":"ああ、田中君。いや、大丈夫だよ。もう少しで一段落するから。","vi":"À, Tanaka. Không sao đâu. Anh làm sắp xong một chặng rồi.","en":"Ah, Tanaka. No, it's fine. I'm almost done with this part."},{"speaker":"tanaka","jp":"でも、明日は打ち合わせですよね。僕、一段落しましたから。","vi":"Nhưng ngày mai là buổi họp với khách hàng mà. Em thì vừa xong một chặng rồi ạ.","en":"But tomorrow is the client meeting, isn't it? I've finished my part."},{"speaker":"yamamoto","jp":"ええ、でも、もうすぐ終わるから。1人で大丈夫だよ。","vi":"Ừ, nhưng sắp xong rồi. Một mình anh vẫn ổn.","en":"Yes, but it'll be done soon. I'm fine on my own."},{"speaker":"tanaka","jp":"あ、そうですか……。じゃあ、会場の手配だけ、僕に任せていただけませんか。","vi":"À, vậy ạ… Vậy chỉ riêng việc sắp xếp hội trường, anh có thể giao cho em không ạ?","en":"Oh, I see… Then could you at least leave the venue arrangements to me?"},{"speaker":"yamamoto","jp":"うーん……。じゃあ、会場の手配と、資料のコピー、お願いしようかな。","vi":"Ừm… Vậy thì việc sắp xếp hội trường và photo tài liệu, nhờ cậu nhé.","en":"Hmm… Then I'll ask you to handle the venue arrangements and the document copies."},{"speaker":"tanaka","jp":"はい、わかりました。すぐ引き継ぎます。締め切りは何時ですか。","vi":"Dạ, em hiểu rồi. Em tiếp nhận ngay. Hạn chót là mấy giờ ạ?","en":"Yes, understood. I'll take it over right away. What's the deadline?"},{"speaker":"yamamoto","jp":"5時まででいいよ。助かるよ、本当に。","vi":"Trước 5 giờ là được. Nhẹ cả người, cảm ơn cậu thật đấy.","en":"By 5 o'clock is fine. That's a real help, truly."},{"speaker":"tanaka","jp":"はい、4時までには仕上げます。何かあったら、すぐ連絡します。","vi":"Dạ, trước 4 giờ em sẽ hoàn thành. Có gì em liên lạc ngay ạ.","en":"Yes, I'll finish by 4. I'll contact you right away if anything comes up."},{"speaker":"yamamoto","jp":"ああ、よろしく頼むよ。ありがとう。","vi":"Ừ, nhờ cậu nhé. Cảm ơn.","en":"Yes, I'm counting on you. Thank you."}],"vocabulary":[{"jp":"申し出る","reading":"もうしでる","vi":"chủ động đề nghị","en":"to offer to do something"},{"jp":"手伝う","reading":"てつだう","vi":"giúp đỡ","en":"to help"},{"jp":"一段落","reading":"いちだんらく","vi":"xong một chặng","en":"a stopping point"},{"jp":"任せる","reading":"まかせる","vi":"giao phó","en":"to entrust"},{"jp":"資料","reading":"しりょう","vi":"tài liệu","en":"documents, materials"},{"jp":"引き継ぐ","reading":"ひきつぐ","vi":"tiếp nhận, bàn giao","en":"to take over (work)"},{"jp":"締め切り","reading":"しめきり","vi":"hạn chót","en":"deadline"},{"jp":"助かる","reading":"たすかる","vi":"được giúp, nhẹ nhõm","en":"to be helped; a relief"},{"jp":"頼む","reading":"たのむ","vi":"nhờ vả","en":"to ask, to request"}]},{"slug":"chui-suru","date":"2026-11-18","duration_sec":66,"category":"iken-kokan","situation":{"en":"Cautioning a colleague about a small mistake","jp":"注意する ― 同僚の小さなミスに気づかせる","vi":"Nhắc nhở đồng nghiệp về lỗi nhỏ"},"dialogue":[{"speaker":"watanabe","jp":"小林くん、ちょっといい？A社へのメール、見たんだけど……。","vi":"Kobayashi này, chị nói một chút được không? Chị vừa xem email gửi cho công ty A……","en":"Kobayashi, do you have a moment? I saw the email to Company A…"},{"speaker":"kobayashi","jp":"はい、渡辺さん。あ、見積書の件ですよね。","vi":"Dạ, chị Watanabe. À, là chuyện báo giá đúng không ạ?","en":"Yes, Ms. Watanabe. Oh, it's about the quotation, right?"},{"speaker":"watanabe","jp":"ええ、そう。添付ファイル、古い見積書になってるの。気づいた？","vi":"Ừ, đúng vậy. File đính kèm đang là báo giá cũ đấy. Em có để ý không?","en":"Yes, that's it. The attached file is the old quotation. Did you notice?"},{"speaker":"kobayashi","jp":"本当ですか……。すみません、間違えました。","vi":"Thật ạ……? Em xin lỗi, em đã nhầm rồi.","en":"Really…? I'm sorry, I made a mistake."},{"speaker":"watanabe","jp":"いいの、いいの。まだ開いてないみたいだから、今なら直せるよ。","vi":"Không sao, không sao. Có vẻ họ chưa mở đâu, nên bây giờ vẫn sửa được đấy.","en":"It's fine, it's fine. They don't seem to have opened it yet, so you can still fix it now."},{"speaker":"kobayashi","jp":"すぐ送り直します。送信する前に、もう一度確認します。","vi":"Em gửi lại ngay ạ. Trước khi gửi, em sẽ kiểm tra lại một lần nữa.","en":"I'll resend it right away. I'll check once more before sending."},{"speaker":"watanabe","jp":"うん、それが大事。……あと、CCに課長を入れるのも、注意してね。","vi":"Ừ, điều đó quan trọng đấy. ……À, còn việc đưa trưởng phòng vào CC nữa, em cũng lưu ý nhé.","en":"Yes, that's important. …Also, be careful to include the manager in CC."},{"speaker":"kobayashi","jp":"はい、わかりました。申し訳ありませんでした。","vi":"Dạ, em hiểu rồi. Em thật sự xin lỗi.","en":"Yes, understood. I'm very sorry."},{"speaker":"watanabe","jp":"気にしないで。誰にでもあることよ。次から気をつければいいの。","vi":"Đừng bận tâm. Ai cũng có lúc như vậy mà. Từ lần sau cẩn thận hơn là được.","en":"Don't worry about it. It happens to everyone. Just be careful from next time."},{"speaker":"kobayashi","jp":"ありがとうございます。次は必ず確認してから送信します。","vi":"Em cảm ơn chị. Lần sau em nhất định sẽ kiểm tra kỹ rồi mới gửi.","en":"Thank you. Next time I'll make sure to check before sending."}],"vocabulary":[{"jp":"注意する","reading":"ちゅういする","vi":"nhắc nhở, lưu ý","en":"to caution; to be careful"},{"jp":"気をつける","reading":"きをつける","vi":"chú ý, cẩn thận","en":"to be careful"},{"jp":"添付する","reading":"てんぷする","vi":"đính kèm (file)","en":"to attach (a file)"},{"jp":"見積書","reading":"みつもりしょ","vi":"báo giá","en":"quotation"},{"jp":"間違える","reading":"まちがえる","vi":"nhầm lẫn","en":"to make a mistake"},{"jp":"確認する","reading":"かくにんする","vi":"kiểm tra, xác nhận","en":"to check; to confirm"},{"jp":"送信する","reading":"そうしんする","vi":"gửi (mail)","en":"to send (an email)"},{"jp":"申し訳ない","reading":"もうしわけない","vi":"xin lỗi","en":"I'm sorry"},{"jp":"気づく","reading":"きづく","vi":"nhận ra, để ý","en":"to notice; to realize"}]},{"slug":"futashika-na-koto-wo-iu","date":"2026-11-18","duration_sec":66,"category":"houkoku-renraku","situation":{"en":"Reporting uncertain information — the delivery date is unclear","jp":"不確かなことを言う ― 納期の情報がはっきりしない","vi":"Nói điều chưa chắc chắn — thông tin về hạn giao hàng chưa rõ ràng"},"dialogue":[{"speaker":"staff_female","jp":"課長、今よろしいでしょうか。A社の納品の件で、ちょっと気になることがあって。","vi":"Trưởng phòng, chị có tiện bây giờ không ạ?\nVề việc giao hàng cho công ty A,\nem có điều hơi băn khoăn.","en":"Manager, do you have a moment?\nAbout the delivery for Company A —\nthere's something I'm a little worried about."},{"speaker":"manager_female","jp":"どうしたの？何かあった？","vi":"Có chuyện gì vậy?\nXảy ra chuyện gì à?","en":"What's up?\nDid something happen?"},{"speaker":"staff_female","jp":"はい、実のところ、まだ不確かなんですが、来週の入荷、遅れるかもしれません。","vi":"Dạ, thực ra vẫn chưa chắc chắn ạ,\nnhưng có lẽ lô hàng nhập kho tuần sau sẽ bị trễ.","en":"Well, actually, it's still uncertain,\nbut next week's shipment may be delayed."},{"speaker":"manager_female","jp":"遅れる？それ、確かな情報なの？","vi":"Trễ à?\nThông tin đó có chắc chắn không?","en":"Delayed?\nIs that certain information?"},{"speaker":"staff_female","jp":"記憶が正しければ、先週の金曜日に連絡があったと思うんですけど……。","vi":"Nếu trí nhớ của em đúng\nthì thứ Sáu tuần trước đã có liên lạc như vậy…","en":"If my memory is correct,\nI think there was a message like that last Friday…"},{"speaker":"manager_female","jp":"そう。じゃあ、取引先に問い合わせて、確認してもらえる？","vi":"Ra vậy. Vậy em liên hệ với đối tác\nđể xác nhận giúp chị nhé?","en":"I see. Then could you contact the supplier\nand check for me?"},{"speaker":"staff_female","jp":"はい、わかりました。すぐメールで問い合わせてみます。","vi":"Dạ, em hiểu rồi.\nEm sẽ gửi mail hỏi ngay ạ.","en":"Yes, understood.\nI'll email them right away to ask."},{"speaker":"manager_female","jp":"うん、お願い。納期が遅れるなら、早めにお客さまに連絡しないとね。","vi":"Ừ, nhờ em. Nếu hạn giao bị trễ\nthì phải báo cho khách hàng sớm đấy nhé.","en":"Yes, please. If the delivery date slips,\nwe need to tell the customer early."},{"speaker":"staff_female","jp":"確かにそうですね。確認が取れ次第、すぐご報告します。","vi":"Đúng là vậy ạ.\nNgay khi xác nhận được, em sẽ báo cáo ngay ạ.","en":"That's true.\nAs soon as I confirm it, I'll report back right away."},{"speaker":"manager_female","jp":"よろしく。あ、もし違っていたら、それも教えてね。","vi":"Nhờ em nhé. À, nếu hóa ra không phải vậy\nthì cũng báo chị nhé.","en":"Thanks. Oh, and if it turns out otherwise,\nlet me know too."}],"vocabulary":[{"jp":"不確か","reading":"ふたしか","vi":"không chắc chắn","en":"uncertain; not sure"},{"jp":"確か","reading":"たしか","vi":"chắc chắn; nếu nhớ đúng","en":"certain; if I recall"},{"jp":"記憶","reading":"きおく","vi":"trí nhớ","en":"memory"},{"jp":"納期","reading":"のうき","vi":"hạn giao hàng","en":"delivery deadline"},{"jp":"入荷","reading":"にゅうか","vi":"hàng nhập kho","en":"arrival of goods"},{"jp":"確認する","reading":"かくにんする","vi":"kiểm tra, xác nhận","en":"to check; to confirm"},{"jp":"問い合わせる","reading":"といあわせる","vi":"liên hệ hỏi","en":"to inquire; to contact"},{"jp":"取引先","reading":"とりひきさき","vi":"đối tác, nhà cung cấp","en":"business partner"},{"jp":"遅れる","reading":"おくれる","vi":"bị trễ","en":"to be delayed"}]},{"slug":"iken-wo-horyu-suru","date":"2026-11-18","duration_sec":66,"category":"iken-kokan","situation":{"en":"Deferring an opinion","jp":"意見を保留する ― 返事を先延ばしにする","vi":"Chưa quyết được, xin thêm thời gian xem xét"},"dialogue":[{"speaker":"yamada","jp":"課長、A案とB案なんですが、どちらをおすすめすればいいでしょうか。","vi":"Trưởng phòng, về phương án A và phương án B,\nnên giới thiệu phương án nào thì tốt ạ?","en":"Manager, about Plan A and Plan B —\nwhich one should I recommend?"},{"speaker":"takahashi","jp":"そうだなあ……。この場では、即答できかねるんだよね。","vi":"Chà, ngay tại đây\nthì chị không thể trả lời ngay được.","en":"Well, I can't give\nan immediate answer right here."},{"speaker":"yamada","jp":"ええ、わかりました。ただ、取引先への返事は、来週の月曜日までなんです。","vi":"Dạ, em hiểu ạ. Nhưng hạn trả lời khách hàng\nlà đến thứ Hai tuần sau ạ.","en":"I see. But the deadline to reply\nto the client is next Monday."},{"speaker":"takahashi","jp":"そうか……。来週まででいいかい？部長会にかけるから。","vi":"Vậy à… Để đến tuần sau được không?\nChị sẽ đưa ra cuộc họp trưởng phòng.","en":"I see… Can it wait until next week?\nI'll take it to the department-head meeting."},{"speaker":"yamada","jp":"はい、もちろんです。あの、検討のポイントを、教えていただけますか。","vi":"Dạ, tất nhiên ạ. À, chị có thể cho em biết\nđiểm cần xem xét không ạ?","en":"Yes, of course. Um, could you tell me\nthe key points to consider?"},{"speaker":"takahashi","jp":"うん。コストと納期のバランスかな。意見は、保留させてもらえるかな。","vi":"Ừ. Chắc là sự cân bằng giữa chi phí và hạn giao.\nCho chị giữ lại ý kiến nhé.","en":"Yes. Probably the balance between cost\nand delivery time. Let me hold off on my opinion."},{"speaker":"yamada","jp":"はい、承知いたしました。資料を、もう一度整理しておきます。","vi":"Dạ, em hiểu rồi ạ.\nEm sẽ sắp xếp lại tài liệu một lần nữa.","en":"Yes, understood.\nI'll go over the documents once more."},{"speaker":"takahashi","jp":"ありがとう。一存では決めかねるから、慎重に検討するね。","vi":"Cảm ơn em. Vì một mình chị không thể quyết được\nnên chị sẽ xem xét cẩn thận.","en":"Thank you. I can't decide on my own authority,\nso I'll consider it carefully."},{"speaker":"yamada","jp":"よろしくお願いいたします。ご連絡、お待ちしております。","vi":"Mong chị giúp đỡ ạ.\nEm sẽ chờ liên lạc từ chị.","en":"I look forward to it.\nI'll be waiting for your reply."},{"speaker":"takahashi","jp":"うん、来週の月曜日までに、必ず返事するから。安心して。","vi":"Ừ, chậm nhất là thứ Hai tuần sau\nchị nhất định sẽ trả lời. Cứ yên tâm nhé.","en":"Yes, I'll definitely reply by next Monday.\nDon't worry."}],"vocabulary":[{"jp":"保留する","reading":"ほりゅうする","vi":"giữ lại, hoãn quyết","en":"to hold off; to defer"},{"jp":"一存","reading":"いちぞん","vi":"ý riêng, quyền tự quyết","en":"one's own discretion"},{"jp":"決めかねる","reading":"きめかねる","vi":"không thể quyết được","en":"to be unable to decide"},{"jp":"即答","reading":"そくとう","vi":"trả lời ngay","en":"immediate answer"},{"jp":"返事","reading":"へんじ","vi":"câu trả lời, hồi đáp","en":"reply; response"},{"jp":"検討","reading":"けんとう","vi":"xem xét, cân nhắc","en":"consideration; examination"},{"jp":"部長会","reading":"ぶちょうかい","vi":"họp các trưởng phòng","en":"department-head meeting"},{"jp":"案","reading":"あん","vi":"phương án, đề xuất","en":"plan; proposal"},{"jp":"おすすめ","reading":"おすすめ","vi":"giới thiệu, khuyên dùng","en":"recommendation"}]},{"slug":"ichinichi-no-wakare-no-aisatsu","date":"2026-11-19","duration_sec":66,"category":"aisatsu-reigi","situation":{"jp":"一日の別れの挨拶 ― 帰る時間の挨拶","vi":"Chào ra về cuối ngày làm việc, hẹn ngày mai","en":"Parting at the end of work"},"dialogue":[{"speaker":"yamada","jp":"課長、お先に失礼します。","vi":"Trưởng phòng, em xin phép về trước ạ.","en":"Manager, I'll head home first."},{"speaker":"sato","jp":"ああ、おつかれさま。今日は、定時に上がれたな。","vi":"À, vất vả rồi. Hôm nay\nvề đúng giờ được nhỉ.","en":"Ah, good work today. You managed\nto leave right on time."},{"speaker":"yamada","jp":"はい、なんとか。あの、明日の会議の資料は、デスクに置いてあります。","vi":"Dạ, cũng tạm ổn ạ. À, tài liệu cho cuộc họp ngày mai\nem đã để trên bàn rồi ạ.","en":"Yes, somehow. Um, the documents for\ntomorrow's meeting are on the desk."},{"speaker":"sato","jp":"うん、確認したよ。ありがとう。明日は、9時からだね。","vi":"Ừ, anh đã kiểm tra rồi. Cảm ơn nhé.\nNgày mai bắt đầu lúc 9 giờ nhỉ.","en":"Yes, I checked them. Thanks.\nTomorrow it starts at 9, right?"},{"speaker":"yamada","jp":"はい、9時からです。ええと、課長は、今日は残業ですか。","vi":"Dạ, bắt đầu lúc 9 giờ ạ. À,\ntrưởng phòng hôm nay làm thêm ạ?","en":"Yes, from 9. Um, Manager,\nare you working overtime today?"},{"speaker":"sato","jp":"ああ、もう少しだけね。見積書を仕上げてから、帰るよ。","vi":"À, chỉ một chút nữa thôi.\nAnh hoàn thành nốt bản báo giá rồi mới về.","en":"Ah, just a little more. I'll finish\nthe quotation first, then go home."},{"speaker":"yamada","jp":"そうですか。あまり、無理なさらないでくださいね。","vi":"Vậy ạ. Anh đừng cố quá nhé.","en":"I see. Please don't push yourself too hard."},{"speaker":"sato","jp":"ありがとう。山田くんも、気をつけて帰ってね。","vi":"Cảm ơn em. Yamada, em cũng\ncẩn thận trên đường về nhé.","en":"Thanks. Yamada, take care\non your way home."},{"speaker":"yamada","jp":"はい、ありがとうございます。では、また明日。","vi":"Dạ, cảm ơn anh ạ.\nVậy thì, hẹn gặp lại ngày mai ạ.","en":"Yes, thank you.\nWell then, see you tomorrow."},{"speaker":"sato","jp":"うん、また明日。おつかれさま。","vi":"Ừ, hẹn mai nhé. Vất vả rồi.","en":"Yes, see you tomorrow. Good work today."}],"vocabulary":[{"jp":"お先に失礼する","reading":"おさきにしつれいする","vi":"xin phép về trước","en":"to leave work before others"},{"jp":"おつかれさま","reading":"おつかれさま","vi":"vất vả rồi (chào cuối ngày)","en":"\"good work today\""},{"jp":"定時","reading":"ていじ","vi":"giờ làm quy định","en":"regular working hours"},{"jp":"会議","reading":"かいぎ","vi":"cuộc họp","en":"meeting"},{"jp":"資料","reading":"しりょう","vi":"tài liệu","en":"documents; materials"},{"jp":"残業","reading":"ざんぎょう","vi":"làm thêm giờ","en":"overtime work"},{"jp":"見積書","reading":"みつもりしょ","vi":"bản báo giá","en":"written estimate; quotation"},{"jp":"気をつける","reading":"きをつける","vi":"cẩn thận, chú ý","en":"to take care; be careful"},{"jp":"明日","reading":"あす","vi":"ngày mai","en":"tomorrow"}]}]};
